import AppKit
import SwiftUI
import UniformTypeIdentifiers

struct RootView: View {
    @EnvironmentObject private var model: ElephantAppModel
    @AppStorage("elephant.mac.onboardingComplete") private var onboardingComplete = false
    @AppStorage("elephant.mac.sidebarVisible") private var sidebarVisible = true
    private let sidebarWidth: CGFloat = 96

    var body: some View {
        ZStack(alignment: .topLeading) {
            AppBackground()
            HStack(spacing: 0) {
                if sidebarVisible {
                    SidebarView()
                        .frame(width: sidebarWidth)
                        .transition(.move(edge: .leading).combined(with: .opacity))
                }
                DetailView(section: model.selectedSection)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .allowsHitTesting(!model.isSleepDisplayPresented && !model.showingOnboarding)
            .accessibilityHidden(model.isSleepDisplayPresented || model.showingOnboarding)
            .blur(radius: model.showingOnboardingLetterEnvelope ? 8 : 0)
            .animation(.easeInOut(duration: 0.18), value: sidebarVisible)

            if model.isSleepDisplayPresented && !model.showingOnboarding {
                SleepDisplayView()
                    .environmentObject(model)
                    .transition(.opacity.combined(with: .scale(scale: 1.015)))
                    .zIndex(20)
            }

            if model.showingOnboarding {
                OnboardingFlow {
                    onboardingComplete = true
                    model.completeOnboarding()
                }
                .environmentObject(model)
                .transition(.opacity)
                .zIndex(40)
            }

            if model.showingOnboardingLetterPrompt, let entry = model.onboardingLetterEntry, !model.showingOnboarding {
                OnboardingLetterToast(entry: entry)
                    .environmentObject(model)
                    .padding(.trailing, 28)
                    .padding(.bottom, 28)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottomTrailing)
                    .transition(.asymmetric(
                        insertion: .move(edge: .trailing).combined(with: .opacity).combined(with: .scale(scale: 0.98, anchor: .bottomTrailing)),
                        removal: .opacity.combined(with: .scale(scale: 0.98, anchor: .bottomTrailing))
                    ))
                    .zIndex(55)
            }

            if model.showingOnboardingLetterEnvelope, let entry = model.onboardingLetterEntry {
                ElephantLetterEnvelopeOverlay(entry: entry)
                    .environmentObject(model)
                    .transition(.opacity)
                    .zIndex(60)
            }
        }
        .background(AppActivityMonitor {
            model.registerUserActivity()
        })
        .environment(\.locale, Locale(identifier: model.appLanguage.localeIdentifier))
        .animation(.spring(response: 0.42, dampingFraction: 0.86), value: model.isSleepDisplayPresented)
        .animation(.easeInOut(duration: 0.24), value: model.showingOnboarding)
        .animation(.spring(response: 0.42, dampingFraction: 0.88), value: model.showingOnboardingLetterPrompt)
        .animation(.spring(response: 0.46, dampingFraction: 0.86), value: model.showingOnboardingLetterEnvelope)
        .onChange(of: model.snapshot.hasElephant) { hasElephant in
            if hasElephant && !model.snapshot.providerID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                onboardingComplete = true
            }
        }
        .onChange(of: model.snapshot.providerID) { providerID in
            if model.snapshot.hasElephant && !providerID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                onboardingComplete = true
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: .elephantToggleSidebar)) { notification in
            if let visible = notification.object as? Bool {
                sidebarVisible = visible
            } else {
                sidebarVisible.toggle()
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: .elephantNewChat)) { _ in
            model.startNewChat()
        }
        .onReceive(NotificationCenter.default.publisher(for: .elephantEnterSleepDisplay)) { _ in
            model.beginSleepDisplay(reason: "manual")
        }
        .onReceive(NotificationCenter.default.publisher(for: .elephantSelectSection)) { notification in
            guard let rawValue = notification.object as? String,
                  let section = AppSection(rawValue: rawValue) else { return }
            model.selectedSection = section
        }
        .onChange(of: model.selectedSection) { section in
            switch section {
            case .paths, .herd, .learn, .usage, .cron:
                Task { try? await model.refreshDashboard() }
            default:
                break
            }
        }
        .task(id: providerLogoPreloadKey) {
            await RemoteLogoCache.shared.preload(ProviderLogoAsset.urls(for: model.snapshot.providerOptions))
        }
    }

    private var providerLogoPreloadKey: String {
        model.snapshot.providerOptions
            .map { "\($0.id):\($0.displayName)" }
            .joined(separator: "|")
    }
}

