                    .foregroundStyle(ElephantTheme.faint)
                    .frame(width: 24, height: 24)
                    .background(Color(nsColor: .controlBackgroundColor).opacity(0.72), in: Circle())
                    .overlay(Circle().stroke(ElephantTheme.line.opacity(0.62), lineWidth: 1))
            }
            .buttonStyle(PressablePlainButtonStyle())
            .padding(.top, 9)
            .padding(.trailing, 9)
            .help(localizedYouText(model.appLanguage, en: "Dismiss", zh: "暂不查看", fr: "Ignorer", de: "Schliessen"))
        }
        .onHover { hovering = $0 }
        .accessibilityElement(children: .combine)
        .accessibilityLabel(onboardingLetterTitle(model.appLanguage))
    }

    private var letterToastBackground: some View {
        RoundedRectangle(cornerRadius: 16, style: .continuous)
            .fill(Color(nsColor: .textBackgroundColor).opacity(0.96))
            .overlay(
                LinearGradient(
                    colors: [
                        ElephantTheme.ember.opacity(0.12),
                        ElephantTheme.gold.opacity(0.11),
                        Color.white.opacity(0.18)
                    ],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
                .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))
            )
    }
}

struct ElephantLetterEnvelopeOverlay: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var entry: DiaryEntry
    @State private var opened = false
    @State private var measuredContentHeight: CGFloat = 0

    var body: some View {
        GeometryReader { geometry in
            let content = displayedOnboardingLetterContent(entry.content, language: model.appLanguage)
            let layout = letterLayout(for: geometry.size)

            ZStack {
                LetterOpenBackdrop()
                    .ignoresSafeArea()
                    .onTapGesture {
                        model.closeOnboardingLetterEnvelope()
                    }

                VStack(spacing: 0) {
                    envelopeHeader
                    Divider().opacity(0.55)
                    letterScrollView(content: content, viewportHeight: layout.contentHeight)
                }
                .frame(width: layout.width, height: layout.height)
                .background(letterPaper)
                .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 18, style: .continuous)
                        .stroke(ElephantTheme.gold.opacity(0.34), lineWidth: 1.2)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 13, style: .continuous)
                        .stroke(Color.white.opacity(0.54), lineWidth: 1)
                        .padding(7)
                )
                .shadow(color: Color.black.opacity(0.28), radius: 42, y: 24)
                .offset(y: opened ? 0 : 18)
                .opacity(opened ? 1 : 0)
            }
        }
        .onAppear {
            guard !reduceMotion else {
                opened = true
                return
            }
            withAnimation(.spring(response: 0.56, dampingFraction: 0.82, blendDuration: 0.08)) {
                opened = true
            }
        }
        .onExitCommand {
            model.closeOnboardingLetterEnvelope()
        }
    }

    private func letterScrollView(content: String, viewportHeight: CGFloat) -> some View {
        ScrollViewReader { proxy in
            ScrollView(.vertical) {
                VStack(alignment: .leading, spacing: 0) {
                    MarkdownBody(
                        text: content,
                        font: .body,
                        color: ElephantTheme.ink,
                        blockSpacing: 7,
                        lineSpacing: 3.2,
                        selectable: false
                    )
                    .background(
                        GeometryReader { contentProxy in
                            Color.clear.preference(key: LetterContentHeightPreferenceKey.self, value: contentProxy.size.height)
                        }
                    )
                    .padding(.horizontal, 38)
                    .padding(.top, 28)
                    .padding(.bottom, 38)
                    .frame(maxWidth: .infinity, alignment: .leading)

                    Color.clear
                        .frame(height: 1)
                        .id("letter-bottom")
                }
            }
            .frame(height: viewportHeight)
            .scrollIndicators(.visible)
            .onPreferenceChange(LetterContentHeightPreferenceKey.self) { height in
                measuredContentHeight = height
            }
            .task(id: autoScrollKey(content: content, viewportHeight: viewportHeight)) {
                guard shouldAutoScroll(viewportHeight: viewportHeight), !reduceMotion else { return }
                try? await Task.sleep(nanoseconds: 1_150_000_000)
                withAnimation(.linear(duration: autoScrollDuration(viewportHeight: viewportHeight))) {
                    proxy.scrollTo("letter-bottom", anchor: .bottom)
                }
            }
        }
    }

    private func letterLayout(for container: CGSize) -> (width: CGFloat, height: CGFloat, contentHeight: CGFloat) {
        let width = min(max(container.width - 112, 660), 880).rounded(.down)
        let maxHeight = min(max(container.height - 96, 520), 820).rounded(.down)
        let desiredHeight = headerHeight + measuredContentHeight + 78
        let height = min(max(desiredHeight, minimumLetterHeight), maxHeight).rounded(.down)
        return (width, height, max(260, height - headerHeight).rounded(.down))
    }

    private var headerHeight: CGFloat { 96 }
    private var minimumLetterHeight: CGFloat { 420 }

    private func shouldAutoScroll(viewportHeight: CGFloat) -> Bool {
        measuredContentHeight + 66 > viewportHeight + 12
    }

    private func autoScrollDuration(viewportHeight: CGFloat) -> Double {
        let overflow = max(0, measuredContentHeight + 66 - viewportHeight)
        return min(18, max(7.5, Double(overflow / 54)))
    }

    private func autoScrollKey(content: String, viewportHeight: CGFloat) -> String {
        "\(content.hashValue)-\(Int(measuredContentHeight.rounded()))-\(Int(viewportHeight.rounded()))"
    }

    private var envelopeHeader: some View {
        HStack(alignment: .center, spacing: 15) {
            BrandMark(size: 58, framed: true, framedFill: Color(nsColor: .textBackgroundColor).opacity(0.96))
                .shadow(color: Color.black.opacity(0.10), radius: 12, y: 6)

            VStack(alignment: .leading, spacing: 4) {
                Text(onboardingLetterTitle(model.appLanguage))
                    .font(.title3.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                    .lineLimit(2)
                    .fixedSize(horizontal: false, vertical: true)
                Text(entry.generatedAt.isEmpty ? localizedYouText(model.appLanguage, en: "written after onboarding", zh: "在认识你之后写下", fr: "écrite après l'accueil", de: "nach dem Onboarding geschrieben") : MacLocalDateTime.formattedDate(entry.generatedAt, language: model.appLanguage))
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
            }

            Spacer(minLength: 0)

            Button {
                Task { await model.regenerateOnboardingLetter(entry) }
            } label: {
                Image(systemName: model.isRegeneratingOnboardingLetter ? "arrow.triangle.2.circlepath" : "arrow.clockwise")
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundStyle(Color.white.opacity(model.learningLaunchDisabled ? 0.26 : 0.62))
                    .shadow(color: Color.black.opacity(0.10), radius: 3, y: 1)
                    .frame(width: 28, height: 28)
                    .contentShape(Circle())
            }
            .buttonStyle(PressablePlainButtonStyle())
            .disabled(model.learningLaunchDisabled)
            .help(localizedYouText(model.appLanguage, en: "Regenerate letter", zh: "重新生成这封信", fr: "Régénérer la lettre", de: "Brief neu erstellen"))

            Button {
                model.closeOnboardingLetterEnvelope()
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 13, weight: .bold))
                    .foregroundStyle(ElephantTheme.ink.opacity(0.70))
                    .frame(width: 30, height: 30)
                    .background(Color(nsColor: .controlBackgroundColor).opacity(0.62), in: Circle())
                    .overlay(Circle().stroke(ElephantTheme.line.opacity(0.64), lineWidth: 1))
            }
            .buttonStyle(PressablePlainButtonStyle())
            .help(localizedYouText(model.appLanguage, en: "Close letter", zh: "收起信", fr: "Fermer la lettre", de: "Brief schliessen"))
        }
        .padding(.leading, 24)
        .padding(.trailing, 18)
        .frame(height: headerHeight)
    }

    private var letterPaper: some View {
        RoundedRectangle(cornerRadius: 18, style: .continuous)
            .fill(Color(nsColor: .textBackgroundColor).opacity(0.985))
            .overlay(
                LinearGradient(
                    colors: [
                        Color.white.opacity(0.20),
                        ElephantTheme.gold.opacity(0.10),
                        Color(nsColor: .textBackgroundColor).opacity(0.10),
                        ElephantTheme.ember.opacity(0.045)
                    ],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
                .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
            )
            .overlay(
                LetterPaperTexture()
                    .opacity(0.10)
                    .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
            )
    }

    private var letterDecoration: some View {
        ZStack(alignment: .top) {
            LetterPaperTexture()
                .opacity(0.18)
                .clipShape(RoundedRectangle(cornerRadius: 14, style: .continuous))
                .allowsHitTesting(false)
            LinearGradient(
                colors: [ElephantTheme.gold.opacity(0.12), Color.clear],
                startPoint: .top,
                endPoint: .bottom
            )
            .frame(height: 130)
            .allowsHitTesting(false)
            VStack {
                HStack {
                    Spacer()
                    BrandMark(size: 140, framed: false)
                        .opacity(0.035)
                        .padding(.top, 110)
                        .padding(.trailing, 28)
                }
                Spacer()
            }
            .allowsHitTesting(false)
        }
    }
}

