struct LetterAmbientBackdrop: View {
    var paused: Bool

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: paused)) { timeline in
            Canvas { context, size in
                let seconds = paused ? 0 : timeline.date.timeIntervalSinceReferenceDate
                let palette = [ElephantTheme.gold, ElephantTheme.accent, ElephantTheme.green]
                for index in 0..<5 {
                    let phase = seconds * 0.10 + Double(index) * 0.82
                    let x = size.width * (0.18 + 0.68 * CGFloat((sin(phase) + 1) / 2))
                    let y = size.height * (0.20 + 0.58 * CGFloat((cos(phase * 0.82) + 1) / 2))
                    let rect = CGRect(x: x - 170, y: y - 170, width: 340, height: 340)
                    context.fill(Path(ellipseIn: rect), with: .color(palette[index % palette.count].opacity(0.10)))
                }
            }
        }
    }
}

private struct LetterContentHeightPreferenceKey: PreferenceKey {
    static var defaultValue: CGFloat = 0

    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
        value = max(value, nextValue())
    }
}

struct LetterPaperTexture: View {
    var body: some View {
        Canvas { context, size in
            var y: CGFloat = 92
            while y < size.height - 24 {
                var path = Path()
                path.move(to: CGPoint(x: 34, y: y))
                path.addLine(to: CGPoint(x: size.width - 34, y: y))
                context.stroke(path, with: .color(ElephantTheme.gold.opacity(0.10)), lineWidth: 0.6)
                y += 32
            }
            var margin = Path()
            margin.move(to: CGPoint(x: 86, y: 76))
            margin.addLine(to: CGPoint(x: 86, y: size.height - 34))
            context.stroke(margin, with: .color(ElephantTheme.ember.opacity(0.08)), lineWidth: 1)
        }
    }
}

struct LetterEnvelopeFoldLines: View {
    var body: some View {
        Canvas { context, size in
            let middle = CGPoint(x: size.width * 0.50, y: size.height * 0.42)
            var topFlap = Path()
            topFlap.move(to: CGPoint(x: 26, y: 76))
            topFlap.addLine(to: middle)
            topFlap.addLine(to: CGPoint(x: size.width - 26, y: 76))
            context.stroke(topFlap, with: .color(ElephantTheme.gold.opacity(0.26)), style: StrokeStyle(lineWidth: 1.4, lineCap: .round, lineJoin: .round))

            var lowerFold = Path()
            lowerFold.move(to: CGPoint(x: 28, y: size.height - 30))
            lowerFold.addLine(to: CGPoint(x: size.width * 0.50, y: size.height * 0.66))
            lowerFold.addLine(to: CGPoint(x: size.width - 28, y: size.height - 30))
            context.stroke(lowerFold, with: .color(ElephantTheme.ember.opacity(0.13)), style: StrokeStyle(lineWidth: 1.1, lineCap: .round, lineJoin: .round))

            let border = CGRect(x: 9, y: 9, width: size.width - 18, height: size.height - 18)
            context.stroke(Path(roundedRect: border, cornerRadius: 13), with: .color(ElephantTheme.gold.opacity(0.20)), lineWidth: 1.2)
        }
    }
}

struct SidebarView: View {
    @EnvironmentObject private var model: ElephantAppModel
    private let glassWidth: CGFloat = 82
    private let iconHitSize: CGFloat = 56
    private let navSpacing: CGFloat = 6
    private let glassVerticalPadding: CGFloat = 14
    private let footerReservedHeight: CGFloat = 144

    var body: some View {
        GeometryReader { proxy in
            let availableNavHeight = max(360, proxy.size.height - footerReservedHeight - 48)
            let navHeight = min(navigationContentHeight, availableNavHeight)
            let needsScrolling = navigationContentHeight > availableNavHeight

            VStack(spacing: 0) {
                Spacer(minLength: 24)

                navigationGlass(height: navHeight, scrolls: needsScrolling)

                Spacer(minLength: 16)

                VStack(spacing: 10) {
                    StatusDot(tint: phaseTint)
                        .help(statusLine)
                    SidebarIconButton(
                        section: .settings,
                        language: model.appLanguage,
                        selected: model.selectedSection == .settings
                    ) {
                        model.selectedSection = .settings
                    }
                }
                .padding(.bottom, 16)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .background(Color.clear)
    }

    private var navigationContentHeight: CGFloat {
        let buttonCount = CGFloat(AppSection.primary.count)
        let buttonsHeight = buttonCount * iconHitSize + max(0, buttonCount - 1) * navSpacing
        return glassVerticalPadding * 2 + buttonsHeight + 4
    }

    private func navigationGlass(height: CGFloat, scrolls: Bool) -> some View {
        VStack(spacing: navSpacing) {
            if scrolls {
                ScrollView(.vertical, showsIndicators: false) {
                    navigationButtons
                        .padding(.vertical, 2)
                }
            } else {
                navigationButtons
                    .padding(.vertical, 2)
            }
        }
        .padding(.vertical, glassVerticalPadding)
        .frame(width: glassWidth, height: height, alignment: .top)
        .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 22, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .stroke(Color(nsColor: .separatorColor).opacity(0.16), lineWidth: 1)
        )
    }

    private var navigationButtons: some View {
        VStack(spacing: navSpacing) {
            ForEach(AppSection.primary) { section in
                SidebarIconButton(
                    section: section,
                    language: model.appLanguage,
                    selected: model.selectedSection == section
                ) {
                    model.selectedSection = section
                    if section == .wake {
                        model.focusComposer()
                    }
                }
            }
        }
    }

    private var statusLine: String {
        switch model.corePhase {
        case .ready:
            return model.snapshot.readyForInteraction ? "Elephant ready" : "Warming local model"
        case .starting: return "Starting local core"
        case .failed: return "Local core needs attention"
        case .idle: return "Local core idle"
        }
    }

    private var phaseTint: Color {
        switch model.corePhase {
        case .ready: return model.snapshot.readyForInteraction ? ElephantTheme.green : ElephantTheme.accent
        case .starting: return ElephantTheme.accent
        case .failed: return ElephantTheme.orange
        case .idle: return ElephantTheme.faint
        }
    }
}

