struct WakeComposerPanel: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Binding var historyVisible: Bool
    @StateObject private var speech = SpeechInputController()
    @State private var composerFocused = false
    @State private var lastScrollTargetID: UUID?
    @State private var composerTextHeight: CGFloat = 26
    @State private var voiceCaptureVisible = false
    @State private var voiceDraftSourceText = ""
    @State private var voiceRecognizedDraft = ""
    @State private var dismissedFilePreviewKey = ""
    private let chatBottomSpacerID = "chat-active-response-spacer"

    var body: some View {
        NativePanel {
            ZStack {
                HStack(alignment: .top, spacing: 14) {
                ZStack(alignment: .topTrailing) {
                VStack(spacing: 0) {
                HStack {
                    Button {
                        historyVisible.toggle()
                    } label: {
                        Image(systemName: "sidebar.leading")
                            .font(.system(size: 14, weight: .semibold))
                            .frame(width: 28, height: 28)
                    }
                    .buttonStyle(PressablePlainButtonStyle())
                    .help(model.text(historyVisible ? .hideChatHistory : .showChatHistory))
                    .accessibilityLabel(model.text(historyVisible ? .hideChatHistory : .showChatHistory))

                    Text(model.activeEpisodeID.isEmpty ? model.text(.newConversation) : model.text(.conversation))
                        .font(.headline)
                        .foregroundStyle(ElephantTheme.ink)
                    Spacer()
                    if !historyVisible {
                        Button {
                            model.startNewChat()
                        } label: {
                            Image(systemName: "plus")
                                .font(.system(size: 12, weight: .semibold))
                                .foregroundStyle(ElephantTheme.muted)
                                .frame(width: 24, height: 24)
                        }
                        .buttonStyle(PressablePlainButtonStyle())
                        .help(model.text(.newChat))
                        .accessibilityLabel(model.text(.newChat))
                        .transition(.opacity.combined(with: .scale(scale: 0.96)))
                    }
                    Button {
                        model.selectedSection = .settings
                    } label: {
                        Pill(text: providerLabel, symbol: "cpu", tint: providerTint)
                    }
                    .buttonStyle(PressablePlainButtonStyle())
                    .help(providerActionHelp)
                    .accessibilityLabel(providerActionHelp)
                }
                .padding(.bottom, 12)

                ScrollViewReader { proxy in
                    Group {
                        if visibleMessages.isEmpty {
                            ChatEmptyState()
                                .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
                                .padding(.horizontal, 28)
                        } else {
                            GeometryReader { geometry in
                                ScrollView {
                                    LazyVStack(alignment: .leading, spacing: 4) {
                                        ForEach(visibleMessages) { message in
                                            MessageBubble(message: message)
                                                .equatable()
                                                .id(message.id)
                                        }
                                        Color.clear
                                            .frame(height: responseRunway(in: geometry.size.height))
                                            .id(chatBottomSpacerID)
                                    }
                                    .padding(.vertical, 8)
                                    .padding(.horizontal, 24)
                                    .frame(maxWidth: .infinity, alignment: .top)
                                }
                            }
                        }
                    }
                    .frame(minHeight: 320, maxHeight: .infinity)
                    .onChange(of: model.chatScrollRevision) { _ in
                        let targetID = visibleMessages.last?.id
                        let targetChanged = targetID != nil && targetID != lastScrollTargetID
                        scrollToTranscriptBottom(proxy: proxy, animated: targetChanged || !model.isWakeRunning)
                        lastScrollTargetID = targetID
                    }
                    .onChange(of: model.isWakeRunning) { running in
                        guard !running else { return }
                        scrollToTranscriptBottom(proxy: proxy, animated: true)
                    }
                }

                Divider()

                if !model.wakeQueue.isEmpty {
                    WakeQueuePanel(items: model.wakeQueue) { item in
                        model.removeQueuedWakeMessage(item)
                    }
                    .frame(maxWidth: queueMaxWidth, alignment: .leading)
                    .frame(maxWidth: .infinity, alignment: .center)
                    .padding(.top, 8)
                    .padding(.bottom, -8)
                }

                VStack(alignment: .leading, spacing: 6) {
                    if let question = model.pendingQuestionReply {
                        PendingQuestionReplyCard(
                            language: model.appLanguage,
                            question: question,
                            isCompact: composerFocused || !model.wakeDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
                            onCancel: { model.cancelQuestionReplyDraft() }
                        )
                    }

                    if !model.wakeAttachments.isEmpty {
                        WakeAttachmentStrip(attachments: model.wakeAttachments, removable: true) { attachment in
                            model.removeWakeAttachment(attachment)
                        }
                    }

                    ZStack(alignment: .bottomTrailing) {
                        ZStack(alignment: .topLeading) {
                            MacComposerTextView(
                                text: $model.wakeDraft,
                                isFocused: $composerFocused,
                                measuredHeight: $composerTextHeight
                            ) {
                                guard canSend else { return }
                                speech.stop()
                                Task { await model.sendWakeMessage() }
                            } onPasteImages: {
                                model.importWakeImages(from: .general)
                            }
                            .frame(height: composerTextHeight)
                            .padding(.leading, 42)
                            .padding(.trailing, 86)
                        }
                        .frame(maxWidth: .infinity, minHeight: composerControlHeight, alignment: .topLeading)
                        .onHover { hovering in
                            if hovering {
                                NSCursor.iBeam.set()
                            }
                        }

                        HStack(spacing: 0) {
                            Button {
                                let urls = OpenPanelBridge.pickChatImageURLs(language: model.appLanguage)
                                model.addWakeImageURLs(urls)
                            } label: {
                                Image(systemName: "plus")
                                    .font(.system(size: 16, weight: .semibold))
                                    .frame(width: 32, height: 32)
                                    .foregroundStyle(ElephantTheme.muted)
                                    .background(
                                        Circle()
                                            .fill(ElephantTheme.panel.opacity(0.72))
                                    )
                                    .overlay(
                                        Circle()
                                            .stroke(ElephantTheme.line.opacity(0.50), lineWidth: 1)
                                    )
                            }
                            .buttonStyle(PressablePlainButtonStyle())
                            .help(localizedYouText(model.appLanguage, en: "Attach image", zh: "添加图片", fr: "Joindre une image", de: "Bild anhängen"))
                            .accessibilityLabel(localizedYouText(model.appLanguage, en: "Attach image", zh: "添加图片", fr: "Joindre une image", de: "Bild anhängen"))
                            Spacer(minLength: 0)
                        }
                        .padding(.bottom, 1)

                        HStack(spacing: 8) {
                            Button {
                                if speech.isRecording {
                                    stopVoiceCapture()
                                } else {
                                    startVoiceCapture()
                                }
                            } label: {
                                Image(systemName: voiceInputButtonSymbol)
                                    .font(.system(size: 14, weight: .semibold))
                                    .frame(width: 30, height: 30)
                                    .foregroundStyle(voiceInputButtonForeground)
                                    .background(
                                        Circle()
                                            .fill(voiceInputButtonFill)
                                    )
                                    .overlay(
                                        Circle()
                                            .stroke(voiceInputButtonStroke, lineWidth: 1)
                                    )
                            }
                            .buttonStyle(PressablePlainButtonStyle())
                            .disabled(speech.isTranscribing)
                            .help(voiceInputButtonHelp)
                            .accessibilityLabel(voiceInputButtonHelp)

                            Button {
                                speech.stop()
                                Task { await model.sendWakeMessage() }
                            } label: {
                                Image(systemName: "arrow.up")
                                    .font(.system(size: 15, weight: .bold))
                                    .frame(width: 32, height: 32)
                                    .foregroundStyle(canSend ? Color.white : ElephantTheme.faint)
                                    .background(
                                        Circle()
                                            .fill(canSend ? Color(red: 0.08, green: 0.09, blue: 0.10) : ElephantTheme.line.opacity(0.34))
                                    )
                                    .overlay(
                                        Circle()
                                            .stroke(canSend ? Color.black.opacity(0.10) : ElephantTheme.line.opacity(0.42), lineWidth: 1)
                                    )
                            }
                            .buttonStyle(PressablePlainButtonStyle())
                            .disabled(!canSend)
                            .help(model.text(.send))
                            .accessibilityLabel(model.text(.send))
                        }
                        .padding(.bottom, 1)
                    }
                    .frame(maxWidth: .infinity, minHeight: composerControlHeight, alignment: .topLeading)

                    if speech.isRecording || !speech.statusText.isEmpty {
                        Label(speech.statusText, systemImage: speech.isRecording ? "waveform" : "mic")
                            .font(.caption)
                            .foregroundStyle(speech.isRecording ? ElephantTheme.accent : ElephantTheme.muted)
                            .lineLimit(1)
                    }
                }
                .padding(.horizontal, 18)
                .padding(.top, 12)
                .padding(.bottom, 10)
                .frame(maxWidth: composerMaxWidth, minHeight: composerMinimumHeight, alignment: .topLeading)
                .background(Color(nsColor: .textBackgroundColor).opacity(0.985), in: RoundedRectangle(cornerRadius: 22, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 22, style: .continuous)
                        .stroke(composerFocused ? ElephantTheme.accent.opacity(0.88) : ElephantTheme.line.opacity(0.72), lineWidth: composerFocused ? 2 : 1)
                )
                .shadow(color: Color.black.opacity(0.050), radius: 14, y: 6)
                .frame(maxWidth: .infinity, alignment: .center)
                .padding(.top, model.wakeQueue.isEmpty ? 12 : 8)
                }
                .frame(minHeight: 620, maxHeight: .infinity)

                if let todoBoard = activeTodoBoard {
                    ChatTodoFloatingPanel(board: todoBoard)
                        .frame(width: 304, height: 218)
                        .padding(.top, 42)
                        .padding(.trailing, 18)
                        .transition(.opacity.combined(with: .scale(scale: 0.985, anchor: .topTrailing)))
                        .zIndex(4)
                }
                }
                .frame(minHeight: 620, maxHeight: .infinity)

                if let previewEvent = activeFilePreviewEvent {
                    ChatToolFilePreviewSidebar(event: previewEvent) {
                        dismissedFilePreviewKey = filePreviewKey(previewEvent)
                    }
                    .frame(width: historyVisible ? 330 : 370)
                    .frame(maxHeight: .infinity)
                    .transition(.move(edge: .trailing).combined(with: .opacity))
                }
                }

                if voiceCaptureVisible {
                    VoiceListeningOverlay(
                        isRecording: speech.isRecording,
                        isTranscribing: speech.isTranscribing,
                        statusText: speech.statusText,
                        recognizedText: speech.recognizedText,
                        startedAt: speech.recordingStartedAt,
                        capturedDuration: speech.capturedDuration,
                        canSend: canSendVoice,
                        send: sendVoiceCapture,
                        stop: stopVoiceCapture,
                        cancel: cancelVoiceCapture
                    )
                    .transition(.opacity.combined(with: .scale(scale: 0.985)))
                    .zIndex(5)
                }
            }
            .animation(reduceMotion ? nil : .easeOut(duration: 0.18), value: voiceCaptureVisible)
        }
        .onAppear { composerFocused = true }
        .onChange(of: model.composerFocusToken) { _ in
            composerFocused = true
        }
        .onDisappear {
            speech.resetCapture()
            voiceRecognizedDraft = ""
        }
    }

    private func startVoiceCapture() {
        guard !speech.isRecording && !speech.isTranscribing else {
            voiceCaptureVisible = true
            return
        }
        model.stopVoiceReply()
        voiceDraftSourceText = model.wakeDraft
        voiceRecognizedDraft = model.wakeDraft
        voiceCaptureVisible = true
        composerFocused = false
        speech.start(
            startingWith: model.wakeDraft,
            language: model.appLanguage,
            recognitionEngine: model.voiceInputEngine
        ) { text in
            voiceRecognizedDraft = text
        }
    }

    private func stopVoiceCapture() {
        speech.stop()
    }

    private func cancelVoiceCapture() {
        speech.resetCapture()
        model.wakeDraft = voiceDraftSourceText
        voiceDraftSourceText = ""
        voiceRecognizedDraft = ""
        voiceCaptureVisible = false
        focusComposerAfterVoiceCapture()
    }

    private func sendVoiceCapture() {
        guard canSendVoice else { return }
        let duration = currentVoiceDuration
        let messageText = voiceRecognizedDraft.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !messageText.isEmpty else { return }
        speech.resetCapture()
        model.wakeDraft = ""
        voiceDraftSourceText = ""
        voiceRecognizedDraft = ""
        voiceCaptureVisible = false
        Task {
            await model.sendVoiceWakeMessage(text: messageText, duration: duration)
        }
    }

    private func focusComposerAfterVoiceCapture() {
        DispatchQueue.main.async {
            composerFocused = true
        }
    }

    private var providerTint: Color {
        let value = model.snapshot.providerStatus.lowercased()
        return value == "unknown" || value.contains("setup") || value.contains("missing")
            ? ElephantTheme.orange
            : ElephantTheme.green
    }

    private var canSend: Bool {
        !model.wakeDraft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty || !model.wakeAttachments.isEmpty
    }

    private var canSendVoice: Bool {
        !speech.recognizedText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var voiceInputButtonSymbol: String {
        if speech.isTranscribing {
            return "text.bubble"
        }
        return speech.isRecording ? "waveform" : "mic.fill"
    }

    private var voiceInputButtonForeground: Color {
        speech.isRecording ? Color.white : ElephantTheme.muted
    }

    private var voiceInputButtonFill: Color {
        speech.isRecording ? ElephantTheme.accent : ElephantTheme.panel.opacity(0.72)
    }

    private var voiceInputButtonStroke: Color {
        speech.isRecording ? ElephantTheme.accent.opacity(0.18) : ElephantTheme.line.opacity(0.50)
    }

    private var voiceInputButtonHelp: String {
        if speech.isTranscribing {
            return localizedYouText(model.appLanguage, en: "Voice is transcribing", zh: "正在识别语音", fr: "Transcription vocale", de: "Sprache wird transkribiert")
        }
        return speech.isRecording ? model.text(.stopVoiceInput) : model.text(.voiceInput)
    }

    private var currentVoiceDuration: TimeInterval {
        if let startedAt = speech.recordingStartedAt {
            return max(speech.capturedDuration, Date().timeIntervalSince(startedAt))
        }
        return speech.capturedDuration
    }

    private var composerControlHeight: CGFloat {
        max(48, composerTextHeight + 4)
    }

    private var composerMinimumHeight: CGFloat {
        composerControlHeight + (model.wakeAttachments.isEmpty ? 28 : 70)
    }

    private var composerMaxWidth: CGFloat {
        historyVisible ? 900 : 1088
    }

    private var queueMaxWidth: CGFloat {
        historyVisible ? 780 : 940
    }

    private var providerLabel: String {
        if !model.snapshot.providerModelID.isEmpty {
            return model.snapshot.providerModelID
        }
        return model.snapshot.providerStatus == "unknown" ? model.text(.providerSetup) : model.snapshot.providerStatus
    }

    private var providerActionHelp: String {
        localizedYouText(
            model.appLanguage,
            en: "Open model provider settings",
            zh: "打开模型服务设置",
            fr: "Ouvrir les réglages du fournisseur de modèle",
            de: "Modellanbieter-Einstellungen öffnen"
        )
    }

    private var visibleMessages: [ChatMessage] {
        model.messages.filter { $0.role != .system }
    }

    private var activeFilePreviewEvent: ToolUseEvent? {
        guard let event = visibleMessages
            .flatMap(\.toolEvents)
            .reversed()
            .first(where: { ToolFileChangePreview(event: $0) != nil }) else {
            return nil
        }
        return dismissedFilePreviewKey == filePreviewKey(event) ? nil : event
    }

    private var activeTodoBoard: ChatTodoBoard? {
        ChatTodoBoard(
            events: visibleMessages.flatMap(\.toolEvents),
            statusOverrides: model.todoStatusOverrides
        )
    }

    private func filePreviewKey(_ event: ToolUseEvent) -> String {
        event.id.uuidString
    }

    private func responseRunway(in transcriptHeight: CGFloat) -> CGFloat {
        guard model.isWakeRunning else { return 14 }
        return min(max(transcriptHeight * 0.20, 88), 168)
    }

    private func scrollToTranscriptBottom(proxy: ScrollViewProxy, animated: Bool) {
        let action = {
            proxy.scrollTo(chatBottomSpacerID, anchor: .bottom)
        }
        guard animated && !reduceMotion else {
            action()
            return
        }
        withAnimation(.easeOut(duration: 0.16), action)
    }
}

private enum MacPrivacySettings {
    static func openVoiceRecognition(statusText: String) {
        if shouldOpenSpeechRecognition(statusText: statusText) {
            openSpeechRecognition()
            return
        }
        openMicrophone()
    }

    static func openMicrophone() {
        open("x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone")
    }

    static func openSpeechRecognition() {
        open("x-apple.systempreferences:com.apple.preference.security?Privacy_SpeechRecognition")
    }

    private static func shouldOpenSpeechRecognition(statusText: String) -> Bool {
        let lowerStatus = statusText.lowercased()
        return lowerStatus.contains("speech recognition")
            || lowerStatus.contains("speech recognizer")
            || statusText.contains("语音识别")
    }

    private static func open(_ rawValue: String) {
        guard let url = URL(string: rawValue) else { return }
        NSWorkspace.shared.open(url)
    }
}

struct VoiceListeningOverlay: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var isRecording: Bool
    var isTranscribing: Bool
    var statusText: String
    var recognizedText: String
    var startedAt: Date?
    var capturedDuration: TimeInterval
    var canSend: Bool
    var send: () -> Void
    var stop: () -> Void
    var cancel: () -> Void

    var body: some View {
        ZStack {
            background

            VStack(spacing: 18) {
                Spacer(minLength: 24)
                animatedIndicator
                titleAndDetail
                permissionRecoveryAction
                controls
                Spacer(minLength: 24)
            }
            .padding(32)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .accessibilityElement(children: .contain)
    }

    private var background: some View {
        RoundedRectangle(cornerRadius: 18, style: .continuous)
            .fill(Color(nsColor: .textBackgroundColor))
            .overlay(
                MemoryCurrentField(paused: reduceMotion || !isRecording)
                    .opacity(0.12)
                    .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
            )
            .overlay(
                LinearGradient(
                    colors: [
                        Color.white.opacity(0.30),
                        ElephantTheme.accent.opacity(0.035),
                        Color.white.opacity(0.18)
                    ],
                    startPoint: .topLeading,
                    endPoint: .bottomTrailing
                )
                .clipShape(RoundedRectangle(cornerRadius: 18, style: .continuous))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 18, style: .continuous)
                    .stroke(ElephantTheme.accent.opacity(isRecording || isTranscribing ? 0.20 : 0.12), lineWidth: 1)
            )
    }

    private var animatedIndicator: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 30.0, paused: reduceMotion || (!isRecording && !isTranscribing))) { timeline in
            ZStack {
                VoiceListeningWaveform(active: isRecording || isTranscribing, seconds: timeline.date.timeIntervalSinceReferenceDate)
                    .frame(width: 340, height: 112)
                    .opacity(isRecording || isTranscribing ? 0.92 : 0.56)
                Circle()
                    .fill(Color(nsColor: .textBackgroundColor).opacity(0.88))
                    .frame(width: 66, height: 66)
                    .overlay(Circle().stroke(Color.white.opacity(0.62), lineWidth: 1))
                    .shadow(color: ElephantTheme.accent.opacity(isRecording || isTranscribing ? 0.16 : 0.06), radius: 20, y: 8)
                Image(systemName: isTranscribing ? "text.bubble" : isRecording ? "waveform" : "mic.fill")
                    .font(.system(size: 23, weight: .semibold))
                    .foregroundStyle(isRecording || isTranscribing ? ElephantTheme.accent : ElephantTheme.muted)
            }
            .accessibilityHidden(true)
        }
    }

    private var titleAndDetail: some View {
        VStack(spacing: 5) {
            Text(title)
                .font(.system(size: 24, weight: .semibold))
                .foregroundStyle(ElephantTheme.ink)
            TimelineView(.periodic(from: Date(), by: reduceMotion ? 1.0 : 0.25)) { timeline in
                Text(detail(elapsed: elapsedDuration(now: timeline.date)))
                    .font(.system(.callout, design: .rounded).weight(.medium))
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(2)
                    .multilineTextAlignment(.center)
            }
        }
        .frame(maxWidth: 520)
    }

    @ViewBuilder
    private var permissionRecoveryAction: some View {
        if showsPermissionRecoveryAction {
            Button {
                MacPrivacySettings.openVoiceRecognition(statusText: statusText)
            } label: {
                Label(openPrivacySettingsLabel, systemImage: "gearshape")
            }
            .settingsActionButton()
            .help(openPrivacySettingsHelp)
            .accessibilityLabel(openPrivacySettingsLabel)
            .accessibilityHint(openPrivacySettingsHelp)
        }
    }

    private var controls: some View {
        HStack(spacing: 12) {
            overlayButton(symbol: "xmark", tint: ElephantTheme.muted, action: cancel)
                .help(localizedYouText(model.appLanguage, en: "Cancel voice", zh: "取消语音", fr: "Annuler la voix", de: "Sprache abbrechen"))
                .accessibilityLabel(localizedYouText(model.appLanguage, en: "Cancel voice", zh: "取消语音", fr: "Annuler la voix", de: "Sprache abbrechen"))
            overlayButton(symbol: "stop.fill", tint: ElephantTheme.orange, action: stop)
                .disabled(!isRecording)
                .opacity(isRecording ? 1 : 0.42)
                .help(model.text(.stopVoiceInput))
                .accessibilityLabel(model.text(.stopVoiceInput))
            overlayButton(symbol: "arrow.up", tint: canSend ? ElephantTheme.accent : ElephantTheme.faint, action: send)
                .disabled(!canSend)
                .help(model.text(.send))
                .accessibilityLabel(model.text(.send))
        }
    }

    private var showsPermissionRecoveryAction: Bool {
        guard !isRecording && !isTranscribing else { return false }
        let lowerStatus = statusText.lowercased()
        return lowerStatus.contains("requesting microphone")
            || lowerStatus.contains("microphone permission")
            || lowerStatus.contains("speech recognition")
            || lowerStatus.contains("speech recognizer")
            || lowerStatus.contains("not authorized")
            || lowerStatus.contains("permission did not")
            || lowerStatus.contains("could not start microphone")
            || statusText.contains("请求麦克风")
            || statusText.contains("麦克风权限")
            || statusText.contains("语音识别")
            || statusText.contains("权限未开启")
            || statusText.contains("没有完成")
    }

    private var openPrivacySettingsLabel: String {
        localizedYouText(model.appLanguage, en: "Open Privacy Settings", zh: "打开隐私设置", fr: "Ouvrir confidentialité", de: "Datenschutz öffnen")
    }

    private var openPrivacySettingsHelp: String {
        localizedYouText(
            model.appLanguage,
            en: "Open macOS Privacy & Security settings for voice input.",
            zh: "打开 macOS 隐私与安全设置以恢复语音输入。",
            fr: "Ouvrir Confidentialité et sécurité pour la saisie vocale.",
            de: "Öffnet macOS Datenschutz & Sicherheit für Spracheingabe."
        )
    }

    private var title: String {
        let lowerStatus = statusText.lowercased()
        if isRecording {
            return localizedYouText(model.appLanguage, en: "Listening", zh: "正在听", fr: "Écoute", de: "Hört zu")
        }
        if isTranscribing {
            return localizedYouText(model.appLanguage, en: "Transcribing", zh: "正在识别", fr: "Transcription", de: "Transkribiert")
        }
        if lowerStatus.contains("disabled")
            || lowerStatus.contains("not authorized")
            || lowerStatus.contains("unavailable")
            || lowerStatus.contains("could not")
            || lowerStatus.contains("permission did not")
            || statusText.contains("没有完成")
            || statusText.contains("权限未开启") {
            return localizedYouText(model.appLanguage, en: "Voice unavailable", zh: "语音暂不可用", fr: "Voix indisponible", de: "Sprache nicht verfügbar")
        }
        if !recognizedText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return localizedYouText(model.appLanguage, en: "Voice ready", zh: "语音已准备好", fr: "Voix prête", de: "Sprache bereit")
        }
        return localizedYouText(model.appLanguage, en: "Waiting for voice", zh: "等待声音", fr: "En attente de voix", de: "Wartet auf Sprache")
    }

    private func detail(elapsed: TimeInterval) -> String {
        let lowerStatus = statusText.lowercased()
        if lowerStatus.contains("requesting")
            || lowerStatus.contains("disabled")
            || lowerStatus.contains("authorized")
            || lowerStatus.contains("unavailable")
            || lowerStatus.contains("could not")
            || lowerStatus.contains("permission")
            || statusText.contains("请求")
            || statusText.contains("权限") {
            return statusText
        }
        if isRecording {
            let draft = recognizedText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !draft.isEmpty {
                return draft
            }
            return formattedVoiceDuration(elapsed)
        }
        if isTranscribing {
            let draft = recognizedText.trimmingCharacters(in: .whitespacesAndNewlines)
            if !draft.isEmpty {
                return draft
            }
            return statusText
        }
        if canSend {
            return formattedVoiceDuration(max(capturedDuration, elapsed))
        }
        return localizedYouText(model.appLanguage, en: "No speech captured.", zh: "还没有捕捉到声音。", fr: "Aucune parole capturée.", de: "Noch keine Sprache erkannt.")
    }

    private func elapsedDuration(now: Date) -> TimeInterval {
        if let startedAt {
            return max(capturedDuration, now.timeIntervalSince(startedAt))
        }
        return capturedDuration
    }

    private func overlayButton(symbol: String, tint: Color, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: 15, weight: .bold))
                .foregroundStyle(tint)
                .frame(width: 42, height: 42)
                .background(Color(nsColor: .textBackgroundColor).opacity(0.86), in: Circle())
                .overlay(Circle().stroke(Color.white.opacity(0.72), lineWidth: 1))
                .shadow(color: Color.black.opacity(0.045), radius: 10, y: 4)
        }
        .buttonStyle(PressablePlainButtonStyle())
    }
}

struct VoiceListeningWaveform: View {
    var active: Bool
    var seconds: TimeInterval

    var body: some View {
        Canvas { context, size in
            let barCount = 34
            let gap: CGFloat = 4
            let width = max(3, (size.width - CGFloat(barCount - 1) * gap) / CGFloat(barCount))
            let midY = size.height / 2
            for index in 0..<barCount {
                let progress = CGFloat(index) / CGFloat(max(1, barCount - 1))
                let envelope = 0.18 + 0.82 * CGFloat(sin(Double.pi * Double(progress)))
                let wave = active ? abs(sin(seconds * 3.2 + Double(index) * 0.47)) : 0.36
                let height = 8 + CGFloat(wave) * envelope * (size.height - 18)
                let x = CGFloat(index) * (width + gap)
                let rect = CGRect(x: x, y: midY - height / 2, width: width, height: height)
                let opacity = 0.22 + 0.42 * envelope
                context.fill(
                    Path(roundedRect: rect, cornerRadius: width / 2),
                    with: .color(ElephantTheme.accent.opacity(opacity))
                )
            }
        }
    }
}

private func formattedVoiceDuration(_ duration: TimeInterval?) -> String {
    let totalSeconds = max(0, Int((duration ?? 0).rounded()))
    let minutes = totalSeconds / 60
    let seconds = totalSeconds % 60
    return String(format: "%d:%02d", minutes, seconds)
}

private func formattedVoiceBubbleTime(_ date: Date) -> String {
    let formatter = DateFormatter()
    formatter.calendar = Calendar.current
    formatter.locale = Locale.current
    formatter.timeZone = TimeZone.current
    formatter.dateFormat = "HH:mm"
    return formatter.string(from: date)
}

struct MacComposerTextView: NSViewRepresentable {
    @Binding var text: String
    @Binding var isFocused: Bool
    @Binding var measuredHeight: CGFloat
    var onSubmit: () -> Void
    var onPasteImages: () -> Bool

    private let minimumHeight: CGFloat = 26
    private let maxVisibleLines = 10

    func makeCoordinator() -> Coordinator {
        Coordinator(
            text: $text,
            isFocused: $isFocused,
            measuredHeight: $measuredHeight,
            minimumHeight: minimumHeight,
            maxVisibleLines: maxVisibleLines,
            onSubmit: onSubmit,
            onPasteImages: onPasteImages
        )
    }

    func makeNSView(context: Context) -> NSScrollView {
        let scrollView = ComposerTextScrollView()
        scrollView.drawsBackground = false
        scrollView.hasVerticalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.hasHorizontalScroller = false
        scrollView.borderType = .noBorder
        scrollView.verticalScrollElasticity = .none

        let textView = ComposerNSTextView()
        textView.delegate = context.coordinator
        textView.onPaste = context.coordinator.handlePaste
        textView.drawsBackground = false
        textView.isEditable = true
        textView.isSelectable = true
        textView.isRichText = false
        textView.allowsUndo = true
        textView.isAutomaticQuoteSubstitutionEnabled = false
        textView.isAutomaticDashSubstitutionEnabled = false
        textView.isAutomaticTextReplacementEnabled = true
        textView.font = .systemFont(ofSize: 16)
        textView.textColor = .labelColor
        textView.insertionPointColor = .labelColor
        textView.textContainerInset = NSSize(width: 0, height: 0)
        textView.minSize = NSSize(width: 0, height: minimumHeight)
        textView.maxSize = NSSize(width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
        textView.isVerticallyResizable = true
        textView.isHorizontallyResizable = false
        textView.autoresizingMask = [.width]
        textView.textContainer?.containerSize = NSSize(width: CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude)
        textView.textContainer?.widthTracksTextView = true
        textView.textContainer?.lineFragmentPadding = 0
        textView.string = text
        context.coordinator.lastKnownText = text

        scrollView.documentView = textView
        context.coordinator.textView = textView
        context.coordinator.scrollView = scrollView
        scrollView.onLayout = { [weak coordinator = context.coordinator] in
            coordinator?.refreshHeight()
        }
        DispatchQueue.main.async {
            context.coordinator.refreshHeight()
        }
        return scrollView
    }

    func updateNSView(_ scrollView: NSScrollView, context: Context) {
        guard let textView = scrollView.documentView as? NSTextView else { return }
        if textView.string != text, text != context.coordinator.lastKnownText {
            textView.string = text
            context.coordinator.lastKnownText = text
        }
        if isFocused, textView.window?.firstResponder !== textView {
            textView.window?.makeFirstResponder(textView)
        }
        context.coordinator.refreshHeight()
    }

    final class Coordinator: NSObject, NSTextViewDelegate {
        @Binding var text: String
        @Binding var isFocused: Bool
        @Binding var measuredHeight: CGFloat
        weak var textView: NSTextView?
        weak var scrollView: NSScrollView?
        var lastKnownText = ""
        var minimumHeight: CGFloat
        var maxVisibleLines: Int
        var onSubmit: () -> Void
        var onPasteImages: () -> Bool

        init(
            text: Binding<String>,
            isFocused: Binding<Bool>,
            measuredHeight: Binding<CGFloat>,
            minimumHeight: CGFloat,
            maxVisibleLines: Int,
            onSubmit: @escaping () -> Void,
            onPasteImages: @escaping () -> Bool
        ) {
            _text = text
            _isFocused = isFocused
            _measuredHeight = measuredHeight
            self.minimumHeight = minimumHeight
            self.maxVisibleLines = maxVisibleLines
            self.onSubmit = onSubmit
            self.onPasteImages = onPasteImages
        }

        func textDidChange(_ notification: Notification) {
            guard let textView = notification.object as? NSTextView else { return }
            lastKnownText = textView.string
            text = textView.string
            refreshHeight()
        }

        func textDidBeginEditing(_ notification: Notification) {
            isFocused = true
        }

        func textDidEndEditing(_ notification: Notification) {
            isFocused = false
        }

        func textView(_ textView: NSTextView, doCommandBy commandSelector: Selector) -> Bool {
            if commandSelector == #selector(NSResponder.insertNewline(_:)) {
                let modifiers = NSApp.currentEvent?.modifierFlags ?? []
                if modifiers.contains(.shift) || modifiers.contains(.option) {
                    textView.insertText("\n", replacementRange: textView.selectedRange())
                } else {
                    onSubmit()
                }
                return true
            }
            return false
        }

        func handlePaste() -> Bool {
            onPasteImages()
        }

        func refreshHeight() {
            guard let textView, let scrollView, let layoutManager = textView.layoutManager, let textContainer = textView.textContainer else { return }
            let font = textView.font ?? .systemFont(ofSize: 16)
            textContainer.containerSize = NSSize(width: max(textView.bounds.width, 1), height: CGFloat.greatestFiniteMagnitude)
            layoutManager.ensureLayout(for: textContainer)
            let usedHeight = ceil(layoutManager.usedRect(for: textContainer).height)
            let lineHeight = ceil(layoutManager.defaultLineHeight(for: font))
            let maxHeight = max(minimumHeight, lineHeight * CGFloat(maxVisibleLines))
            let targetHeight = min(max(minimumHeight, usedHeight + 2), maxHeight)
            scrollView.hasVerticalScroller = targetHeight >= maxHeight - 0.5 && usedHeight > maxHeight
            if abs(measuredHeight - targetHeight) > 0.5 {
                DispatchQueue.main.async { [weak self] in
                    self?.measuredHeight = targetHeight
                }
            }
        }
    }
}

final class ComposerNSTextView: NSTextView {
    var onPaste: (() -> Bool)?

    override func paste(_ sender: Any?) {
        if onPaste?() == true {
            return
        }
        super.paste(sender)
    }

    override func resetCursorRects() {
        addCursorRect(bounds, cursor: .iBeam)
    }
}

final class ComposerTextScrollView: NSScrollView {
    var onLayout: (() -> Void)?

    override func layout() {
        super.layout()
        onLayout?()
    }

    override func mouseDown(with event: NSEvent) {
        if let textView = documentView as? NSTextView,
           window?.firstResponder !== textView {
            window?.makeFirstResponder(textView)
        }
        super.mouseDown(with: event)
    }

    override func resetCursorRects() {
        addCursorRect(bounds, cursor: .iBeam)
    }
}

