struct WakeQueueRow: View {
    @EnvironmentObject private var model: ElephantAppModel
    var item: WakeQueuedPrompt
    var remove: () -> Void

    var body: some View {
        HStack(spacing: 9) {
            Image(systemName: item.inputModality == .voice ? "waveform" : "arrow.turn.down.right")
                .font(.caption.weight(.semibold))
                .foregroundStyle(ElephantTheme.faint)
                .frame(width: 18)
            Text(previewText)
                .font(.callout.weight(.semibold))
                .foregroundStyle(ElephantTheme.ink.opacity(0.74))
                .lineLimit(1)
            Spacer(minLength: 10)
            Label(localizedYouText(model.appLanguage, en: "Queued", zh: "排队中", fr: "En file", de: "Wartet"), systemImage: item.inputModality == .voice ? "waveform" : "text.line.first.and.arrowtriangle.forward")
                .labelStyle(.titleAndIcon)
                .font(.caption.weight(.semibold))
                .foregroundStyle(ElephantTheme.muted)
            Button {
                remove()
            } label: {
                Image(systemName: "trash")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.faint)
                    .frame(width: 26, height: 26)
            }
            .buttonStyle(PressablePlainButtonStyle())
            .help(localizedYouText(model.appLanguage, en: "Remove from queue", zh: "从队列移除", fr: "Retirer de la file", de: "Aus Warteschlange entfernen"))
            .accessibilityLabel(localizedYouText(model.appLanguage, en: "Remove from queue", zh: "从队列移除", fr: "Retirer de la file", de: "Aus Warteschlange entfernen"))
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 9)
    }

    private var previewText: String {
        if item.inputModality == .voice {
            return localizedYouText(model.appLanguage, en: "Voice message", zh: "语音消息", fr: "Message vocal", de: "Sprachnachricht")
        }
        let trimmed = item.text.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty {
            return trimmed
        }
        if item.attachments.count == 1 {
            return item.attachments[0].displayName
        }
        if item.attachments.count > 1 {
            return localizedFormat(model.appLanguage, en: "%d images", zh: "%d 张图片", fr: "%d images", de: "%d Bilder", item.attachments.count)
        }
        return localizedYouText(model.appLanguage, en: "Image message", zh: "图片消息", fr: "Message image", de: "Bildnachricht")
    }
}

