private struct MarkdownBlock: Identifiable {
    enum Kind {
        case paragraph
        case heading
        case bulletList
        case numberedList
        case taskList
        case quote
        case table
        case rule
        case code
    }

    var id: Int
    var kind: Kind
    var text: String
    var items: [String] = []
    var table: MarkdownTable?
}

private struct MarkdownTable: Equatable {
    var headers: [String]
    var rows: [[String]]
}

private struct MarkdownTaskItem: Identifiable, Equatable {
    var id: String { "\(checked)-\(text)" }
    var checked: Bool
    var text: String
}

struct MarkdownBody: View {
    var text: String
    var font: Font = .body
    var color: Color = ElephantTheme.ink
    var blockSpacing: CGFloat = 5
    var lineSpacing: CGFloat = 2.5
    var selectable = true

    var body: some View {
        VStack(alignment: .leading, spacing: blockSpacing) {
            ForEach(blocks) { block in
                switch block.kind {
                case .heading:
                    InlineMarkdownText(text: block.text, font: .headline, color: color, selectable: selectable, lineSpacing: lineSpacing)
                case .paragraph:
                    InlineMarkdownText(text: block.text, font: font, color: color, selectable: selectable, lineSpacing: lineSpacing)
                case .bulletList:
                    VStack(alignment: .leading, spacing: 5) {
                        ForEach(block.items, id: \.self) { item in
                            HStack(alignment: .top, spacing: 6) {
                                Text("•")
                                    .font(font)
                                    .foregroundStyle(color.opacity(0.72))
                                InlineMarkdownText(text: item, font: font, color: color, selectable: selectable, lineSpacing: lineSpacing)
                            }
                        }
                    }
                case .numberedList:
                    VStack(alignment: .leading, spacing: 5) {
                        ForEach(Array(block.items.enumerated()), id: \.offset) { index, item in
                            HStack(alignment: .top, spacing: 6) {
                                Text("\(index + 1).")
                                    .font(font)
                                    .foregroundStyle(color.opacity(0.72))
                                InlineMarkdownText(text: item, font: font, color: color, selectable: selectable, lineSpacing: lineSpacing)
                            }
                        }
                    }
                case .taskList:
                    VStack(alignment: .leading, spacing: 5) {
                        ForEach(taskItems(from: block.items)) { item in
                            HStack(alignment: .top, spacing: 7) {
                                Image(systemName: item.checked ? "checkmark.square.fill" : "square")
                                    .font(.callout.weight(.semibold))
                                    .foregroundStyle(item.checked ? ElephantTheme.accent : color.opacity(0.56))
                                    .frame(width: 18)
                                InlineMarkdownText(text: item.text, font: font, color: color, selectable: selectable, lineSpacing: lineSpacing)
                            }
                        }
                    }
                case .quote:
                    HStack(alignment: .top, spacing: 10) {
                        RoundedRectangle(cornerRadius: 2, style: .continuous)
                            .fill(ElephantTheme.ember.opacity(0.42))
                            .frame(width: 3)
                        InlineMarkdownText(
                            text: block.text,
                            font: font,
                            color: color.opacity(0.90),
                            selectable: selectable,
                            lineSpacing: lineSpacing
                        )
                    }
                    .padding(.horizontal, 12)
                    .padding(.vertical, 10)
                    .background(ElephantTheme.gold.opacity(0.075), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
                    .overlay {
                        RoundedRectangle(cornerRadius: 10, style: .continuous)
                            .stroke(ElephantTheme.gold.opacity(0.18), lineWidth: 1)
                    }
                    .overlay(alignment: .topLeading) {
                        Circle()
                            .fill(ElephantTheme.ember.opacity(0.34))
                            .frame(width: 5, height: 5)
                            .offset(x: 8, y: 8)
                    }
                    .accessibilityElement(children: .combine)
                case .table:
                    if let table = block.table {
                        MarkdownTableView(table: table, font: font, color: color)
                    }
                case .rule:
                    Rectangle()
                        .fill(ElephantTheme.line.opacity(0.78))
                        .frame(height: 1)
                        .padding(.vertical, 5)
                case .code:
                    Text(block.text)
                        .font(.system(.callout, design: .monospaced))
                        .foregroundStyle(color)
                        .lineSpacing(2)
                        .textSelection(.enabled)
                        .padding(8)
                        .frame(maxWidth: .infinity, alignment: .leading)
                        .background(Color(nsColor: .textBackgroundColor), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
                }
            }
        }
        .fixedSize(horizontal: false, vertical: true)
    }

    private func taskItems(from values: [String]) -> [MarkdownTaskItem] {
        values.map { value in
            let checked = value.hasPrefix("[x] ") || value.hasPrefix("[X] ")
            let text = value.replacingOccurrences(of: #"^\[[ xX]\]\s+"#, with: "", options: .regularExpression)
            return MarkdownTaskItem(checked: checked, text: text)
        }
    }

    private var blocks: [MarkdownBlock] {
        var result: [MarkdownBlock] = []
        var paragraph: [String] = []
        var bullets: [String] = []
        var numbers: [String] = []
        var tasks: [String] = []
        var quotes: [String] = []
        var code: [String] = []
        var inCode = false

        func flushInlineBlocks() {
            flushParagraph()
            flushBullets()
            flushNumbers()
            flushTasks()
            flushQuotes()
        }

        func flushParagraph() {
            guard !paragraph.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .paragraph, text: paragraph.joined(separator: "\n")))
            paragraph.removeAll()
        }

        func flushBullets() {
            guard !bullets.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .bulletList, text: "", items: bullets))
            bullets.removeAll()
        }

        func flushNumbers() {
            guard !numbers.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .numberedList, text: "", items: numbers))
            numbers.removeAll()
        }

        func flushTasks() {
            guard !tasks.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .taskList, text: "", items: tasks))
            tasks.removeAll()
        }

        func flushQuotes() {
            guard !quotes.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .quote, text: quotes.joined(separator: "\n")))
            quotes.removeAll()
        }

        func flushCode() {
            guard !code.isEmpty else { return }
            result.append(MarkdownBlock(id: result.count, kind: .code, text: code.joined(separator: "\n")))
            code.removeAll()
        }

        let lines = text.components(separatedBy: .newlines)
        var index = 0
        while index < lines.count {
            let rawLine = lines[index]
            let line = rawLine.trimmingCharacters(in: .whitespaces)
            if line.hasPrefix("```") {
                if inCode {
                    inCode = false
                    flushCode()
                } else {
                    flushInlineBlocks()
                    inCode = true
                }
                index += 1
                continue
            }
            if inCode {
                code.append(rawLine)
                index += 1
                continue
            }
            if line.isEmpty {
                flushInlineBlocks()
                index += 1
                continue
            }
            if isMarkdownRule(line) {
                flushInlineBlocks()
                result.append(MarkdownBlock(id: result.count, kind: .rule, text: ""))
                index += 1
                continue
            }
            if let table = parseTable(startingAt: index, lines: lines) {
                flushInlineBlocks()
                result.append(MarkdownBlock(id: result.count, kind: .table, text: "", table: table.value))
                index = table.nextIndex
                continue
            }
            if line.hasPrefix("### ") || line.hasPrefix("## ") || line.hasPrefix("# ") {
                flushInlineBlocks()
                result.append(MarkdownBlock(id: result.count, kind: .heading, text: line.replacingOccurrences(of: #"^#{1,3}\s+"#, with: "", options: .regularExpression)))
                index += 1
                continue
            }
            if line.hasPrefix(">") {
                flushParagraph()
                flushBullets()
                flushNumbers()
                flushTasks()
                quotes.append(line.replacingOccurrences(of: #"^>\s?"#, with: "", options: .regularExpression))
                index += 1
                continue
            }
            if let range = line.range(of: #"^[-*]\s+\[[ xX]\]\s+"#, options: .regularExpression) {
                flushParagraph()
                flushBullets()
                flushNumbers()
                flushQuotes()
                let checkedPrefix = line.range(of: #"^[-*]\s+\[[xX]\]"#, options: .regularExpression) == nil ? "[ ] " : "[x] "
                tasks.append(checkedPrefix + String(line[range.upperBound...]))
                index += 1
                continue
            }
            if line.hasPrefix("- ") || line.hasPrefix("* ") {
                flushParagraph()
                flushNumbers()
                flushTasks()
                flushQuotes()
                bullets.append(String(line.dropFirst(2)))
                index += 1
                continue
            }
            if let range = line.range(of: #"^\d+\.\s+"#, options: .regularExpression) {
                flushParagraph()
                flushBullets()
                flushTasks()
                flushQuotes()
                numbers.append(String(line[range.upperBound...]))
                index += 1
                continue
            }
            flushBullets()
            flushNumbers()
            flushTasks()
            flushQuotes()
            paragraph.append(rawLine)
            index += 1
        }

        flushInlineBlocks()
        flushCode()
        return result.isEmpty ? [MarkdownBlock(id: 0, kind: .paragraph, text: text)] : result
    }

    private func isMarkdownRule(_ line: String) -> Bool {
        line.range(of: #"^(\*\s*){3,}$|^(-\s*){3,}$|^(_\s*){3,}$"#, options: .regularExpression) != nil
    }

    private func parseTable(startingAt index: Int, lines: [String]) -> (value: MarkdownTable, nextIndex: Int)? {
        guard index + 1 < lines.count else { return nil }
        let headerLine = lines[index].trimmingCharacters(in: .whitespaces)
        let separatorLine = lines[index + 1].trimmingCharacters(in: .whitespaces)
        guard headerLine.contains("|"), isMarkdownTableSeparator(separatorLine) else { return nil }
        let headers = splitMarkdownTableRow(headerLine)
        guard headers.count > 1 else { return nil }
        var rows: [[String]] = []
        var cursor = index + 2
        while cursor < lines.count {
            let candidate = lines[cursor].trimmingCharacters(in: .whitespaces)
            guard candidate.contains("|"), !candidate.isEmpty else { break }
            let row = splitMarkdownTableRow(candidate)
            guard !row.isEmpty else { break }
            rows.append(row)
            cursor += 1
        }
        return (MarkdownTable(headers: headers, rows: rows), cursor)
    }

    private func isMarkdownTableSeparator(_ line: String) -> Bool {
        let cells = splitMarkdownTableRow(line)
        guard cells.count > 1 else { return false }
        return cells.allSatisfy { cell in
            cell.range(of: #"^:?-{3,}:?$"#, options: .regularExpression) != nil
        }
    }

    private func splitMarkdownTableRow(_ line: String) -> [String] {
        var trimmed = line.trimmingCharacters(in: .whitespaces)
        if trimmed.hasPrefix("|") { trimmed.removeFirst() }
        if trimmed.hasSuffix("|") { trimmed.removeLast() }
        return trimmed.split(separator: "|", omittingEmptySubsequences: false)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    }
}

private struct MarkdownTableView: View {
    var table: MarkdownTable
    var font: Font
    var color: Color

    var body: some View {
        ScrollView(.horizontal, showsIndicators: true) {
            VStack(alignment: .leading, spacing: 0) {
                markdownRow(table.headers, header: true)
                ForEach(Array(table.rows.enumerated()), id: \.offset) { index, row in
                    markdownRow(normalized(row), header: false)
                        .background(index.isMultiple(of: 2) ? Color.clear : ElephantTheme.line.opacity(0.08))
                }
            }
            .fixedSize(horizontal: true, vertical: false)
            .background(Color(nsColor: .textBackgroundColor).opacity(0.46))
            .overlay(Rectangle().stroke(ElephantTheme.line.opacity(0.78), lineWidth: 1))
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func markdownRow(_ values: [String], header: Bool) -> some View {
        HStack(alignment: .top, spacing: 0) {
            ForEach(Array(normalized(values).enumerated()), id: \.offset) { index, value in
                MarkdownTableCell(
                    value: displayValue(value, at: index, header: header),
                    font: header ? .callout.weight(.semibold) : font,
                    color: header ? color : color.opacity(0.94),
                    width: columnWidth(at: index),
                    header: header
                )
                    .overlay(alignment: .trailing) {
                        if index < columnCount - 1 {
                            Rectangle()
                                .fill(ElephantTheme.line.opacity(0.64))
                                .frame(width: 1)
                        }
                    }
            }
        }
        .background(header ? Color(nsColor: .controlBackgroundColor).opacity(0.72) : Color.clear)
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(ElephantTheme.line.opacity(header ? 0.72 : 0.34))
                .frame(height: 1)
        }
    }

    private func normalized(_ values: [String]) -> [String] {
        let count = columnCount
        if values.count >= count { return values }
        return values + Array(repeating: "", count: count - values.count)
    }

    private var columnCount: Int {
        max(table.headers.count, table.rows.map(\.count).max() ?? 0)
    }

    private func displayValue(_ value: String, at index: Int, header: Bool) -> String {
        if header && value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty && isIndexColumn(index) {
            return "#"
        }
        return value
    }

    private func columnWidth(at index: Int) -> CGFloat {
        if isIndexColumn(index) {
            return 46
        }
        let header = normalizedHeader(at: index)
        if header.contains("result")
            || header.contains("output")
            || header.contains("return")
            || header.contains("detail")
            || header.contains("结果")
            || header.contains("返回")
            || header.contains("详情")
            || header.contains("résultat")
            || header.contains("ergebnis") {
            return 420
        }
        if header.contains("query")
            || header.contains("mode")
            || header.contains("查询")
            || header.contains("模式") {
            return 300
        }
        let maxLength = maxContentLength(at: index)
        if maxLength > 80 {
            return 360
        }
        if maxLength > 40 {
            return 300
        }
        if maxLength > 20 {
            return 240
        }
        if header.count <= 3 {
            return 150
        }
        return 210
    }

    private func isIndexColumn(_ index: Int) -> Bool {
        guard index == 0 else {
            return false
        }
        let header = normalizedHeader(at: index)
        let headerLooksLikeIndex = header.isEmpty || ["#", "no", "number", "index", "序号", "编号"].contains(header)
        guard headerLooksLikeIndex else { return false }
        return table.rows.allSatisfy { row in
            guard let value = row.first.map(normalizedTableText), !value.isEmpty else {
                return true
            }
            return Int(value) != nil
        }
    }

    private func normalizedHeader(at index: Int) -> String {
        guard index < table.headers.count else { return "" }
        return normalizedTableText(table.headers[index]).lowercased()
    }

    private func normalizedTableText(_ value: String) -> String {
        value
            .replacingOccurrences(of: "\u{00A0}", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func maxContentLength(at index: Int) -> Int {
        let headerLength = index < table.headers.count ? normalizedTableText(table.headers[index]).count : 0
        let rowLength = table.rows
            .map { row in index < row.count ? normalizedTableText(row[index]).count : 0 }
            .max() ?? 0
        return max(headerLength, rowLength)
    }
}

private struct MarkdownTableCell: View {
    var value: String
    var font: Font
    var color: Color
    var width: CGFloat
    var header: Bool

    var body: some View {
        InlineMarkdownText(text: value, font: font, color: color)
            .padding(.horizontal, header ? 12 : 10)
            .padding(.vertical, header ? 9 : 8)
        .frame(width: width, alignment: .leading)
        .frame(minHeight: header ? 38 : 36, alignment: .topLeading)
    }
}

struct InlineMarkdownText: View {
    var text: String
    var font: Font
    var color: Color
    var fixedHorizontal = false
    var lineLimit: Int?
    var selectable = true
    var lineSpacing: CGFloat = 2

    var body: some View {
        if let strongText = strongMarkdownText() {
            styledText(strongText)
        } else if let attributed = try? AttributedString(
            markdown: text,
            options: AttributedString.MarkdownParsingOptions(interpretedSyntax: .inlineOnlyPreservingWhitespace)
        ) {
            styledText(Text(attributed))
        } else {
            styledText(Text(text))
        }
    }

    private func strongMarkdownText() -> Text? {
        let pattern = #"(\*\*|__)(.+?)\1"#
        guard text.range(of: pattern, options: .regularExpression) != nil else { return nil }

        var result = Text("")
        var cursor = text.startIndex
        while let range = text.range(of: pattern, options: .regularExpression, range: cursor..<text.endIndex) {
            if cursor < range.lowerBound {
                result = result + Text(String(text[cursor..<range.lowerBound]))
            }
            let token = String(text[range])
            let inner = String(token.dropFirst(2).dropLast(2))
            result = result + Text(inner).bold()
            cursor = range.upperBound
        }
        if cursor < text.endIndex {
            result = result + Text(String(text[cursor..<text.endIndex]))
        }
        return result
    }

    @ViewBuilder
    private func styledText(_ textView: Text) -> some View {
        if selectable {
            textView
                .font(font)
                .foregroundStyle(color)
                .lineSpacing(lineSpacing)
                .lineLimit(lineLimit)
                .fixedSize(horizontal: fixedHorizontal, vertical: true)
                .textSelection(.enabled)
        } else {
            textView
                .font(font)
                .foregroundStyle(color)
                .lineSpacing(lineSpacing)
                .lineLimit(lineLimit)
                .fixedSize(horizontal: fixedHorizontal, vertical: true)
        }
    }
}

struct MessageBubble: View, Equatable {
    @EnvironmentObject private var model: ElephantAppModel
    var message: ChatMessage

    static func == (lhs: MessageBubble, rhs: MessageBubble) -> Bool {
        lhs.message == rhs.message
    }

    var body: some View {
        Group {
            if message.role == .user {
                HStack(alignment: .top, spacing: 0) {
                    Spacer(minLength: 80)
                    bubbleContent
                }
            } else {
                HStack(alignment: .top, spacing: 0) {
                    bubbleContent
                    Spacer(minLength: 80)
                }
            }
        }
        .frame(maxWidth: .infinity, alignment: message.role == .user ? .trailing : .leading)
    }

    private var bubbleContent: some View {
        Group {
            if message.role == .user {
                bubbleCore
            } else {
                bubbleCore
                    .frame(maxWidth: 760, alignment: .leading)
            }
        }
    }

    private var bubbleCore: some View {
        VStack(alignment: .leading, spacing: 3) {
            if !message.attachments.isEmpty {
                WakeAttachmentStrip(attachments: message.attachments, removable: false)
                    .padding(.bottom, visibleText.isEmpty && !message.isVoiceMessage ? 0 : 4)
            }
            if message.isVoiceMessage {
                VoiceMessageBubbleContent(message: message)
            } else if message.isAssistantVoiceReply {
                AssistantVoiceReplyBubbleContent(
                    message: message,
                    text: visibleText,
                    speechOutput: model.speechOutput
                )
            } else if !visibleText.isEmpty {
                MarkdownBody(
                    text: visibleText,
                    font: message.role == .system ? .callout : .body,
                    color: textColor
                )
                    .transaction { transaction in
                        transaction.animation = nil
                    }
            }
            if !message.isAssistantVoiceReply && !visibleToolEvents.isEmpty {
                ToolUseStack(events: visibleToolEvents, isLive: message.isStreaming)
                    .padding(.top, visibleText.isEmpty ? 0 : 1)
            } else if message.isStreaming && visibleText.isEmpty && message.toolEvents.isEmpty {
                ToolTraceWaitingView()
            }
        }
        .padding(.horizontal, bubbleHorizontalPadding)
        .padding(.vertical, bubbleVerticalPadding)
        .background(background, in: RoundedRectangle(cornerRadius: bubbleCornerRadius, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: bubbleCornerRadius, style: .continuous)
                .stroke(message.role == .user ? ElephantTheme.line.opacity(0.65) : Color.clear, lineWidth: 1)
        )
    }

    private var background: Color {
        switch message.role {
        case .user: return ElephantTheme.accent.opacity(message.isVoiceMessage ? 0.055 : 0.08)
        case .assistant: return message.isAssistantVoiceReply ? ElephantTheme.accent.opacity(0.055) : Color.clear
        case .system: return Color(nsColor: .controlBackgroundColor)
        }
    }

    private var bubbleHorizontalPadding: CGFloat {
        if message.role == .user {
            return message.isVoiceMessage ? 10 : 16
        }
        return message.isAssistantVoiceReply ? 10 : 0
    }

    private var bubbleVerticalPadding: CGFloat {
        if message.role == .user {
            return message.isVoiceMessage ? 7 : 11
        }
        return message.isAssistantVoiceReply ? 8 : 0
    }

    private var bubbleCornerRadius: CGFloat {
        if message.role == .user {
            return message.isVoiceMessage ? 15 : 18
        }
        return message.isAssistantVoiceReply ? 15 : 14
    }

    private var textColor: Color {
        ElephantTheme.ink
    }

    private var visibleText: String {
        guard message.role == .assistant else { return message.text }
        return sanitizedAssistantMessageText(message.text)
    }

    private var visibleToolEvents: [ToolUseEvent] {
        message.toolEvents.filter { !$0.shouldHideInChat }
    }
}

struct VoiceMessageBubbleContent: View {
    @EnvironmentObject private var model: ElephantAppModel
    var message: ChatMessage

    var body: some View {
        HStack(spacing: 8) {
            Image(systemName: "waveform")
                .font(.system(size: 12, weight: .semibold))
                .foregroundStyle(ElephantTheme.accent)
                .frame(width: 22, height: 22)
                .background(ElephantTheme.accent.opacity(0.12), in: Circle())

            VoiceMessageMiniWaveform()
                .frame(width: 64, height: 18)
                .accessibilityHidden(true)

            Text(formattedVoiceDuration(message.voiceDuration))
                .font(.system(.caption2, design: .rounded).weight(.semibold))
                .monospacedDigit()
                .foregroundStyle(ElephantTheme.ink.opacity(0.82))

            Text(formattedVoiceBubbleTime(message.date))
                .font(.system(.caption2, design: .rounded).weight(.medium))
                .monospacedDigit()
                .foregroundStyle(ElephantTheme.faint)
        }
        .frame(width: 170, height: 24, alignment: .leading)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel(
            localizedYouText(
                model.appLanguage,
                en: "Voice message, \(formattedVoiceDuration(message.voiceDuration)), sent at \(formattedVoiceBubbleTime(message.date))",
                zh: "语音消息，\(formattedVoiceDuration(message.voiceDuration))，发送于 \(formattedVoiceBubbleTime(message.date))",
                fr: "Message vocal, \(formattedVoiceDuration(message.voiceDuration)), envoyé à \(formattedVoiceBubbleTime(message.date))",
                de: "Sprachnachricht, \(formattedVoiceDuration(message.voiceDuration)), gesendet um \(formattedVoiceBubbleTime(message.date))"
            )
        )
    }
}

struct AssistantVoiceReplyBubbleContent: View {
    @EnvironmentObject private var model: ElephantAppModel
    var message: ChatMessage
    var text: String
    @ObservedObject var speechOutput: LocalSpeechOutputController
    @State private var transcriptExpanded = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Button {
                    speechOutput.toggle(
                        messageID: message.id,
                        text: text,
                        language: model.appLanguage,
                        engine: model.voiceReplyEngine,
                        systemVoiceIdentifier: model.voiceReplyVoiceIdentifier,
                        edgeVoiceIdentifier: model.effectiveEdgeVoiceIdentifier
                    )
                } label: {
                    Image(systemName: playbackSymbol)
                        .font(.system(size: 12, weight: .bold))
                        .foregroundStyle(playbackTint)
                        .frame(width: 26, height: 26)
                        .background(playbackTint.opacity(0.12), in: Circle())
                }
                .buttonStyle(PressablePlainButtonStyle())
                .help(playbackHelp)
                .accessibilityLabel(playbackHelp)

                VoiceMessageMiniWaveform(active: isPlaying)
                    .frame(width: 62, height: 18)
                    .accessibilityHidden(true)

                Text(formattedVoiceBubbleTime(message.date))
                    .font(.system(.caption2, design: .rounded).weight(.medium))
                    .monospacedDigit()
                    .foregroundStyle(hasPlaybackError ? ElephantTheme.orange : ElephantTheme.faint)
                    .frame(width: 34, alignment: .leading)

                Button {
                    withAnimation(.easeOut(duration: 0.16)) {
                        transcriptExpanded.toggle()
                    }
                } label: {
                    Image(systemName: transcriptExpanded ? "doc.text.fill" : "doc.text")
                        .font(.system(size: 12, weight: .semibold))
                        .foregroundStyle(transcriptExpanded ? ElephantTheme.accent : ElephantTheme.muted)
                        .frame(width: 24, height: 24)
                        .background(
                            Color(nsColor: .controlBackgroundColor).opacity(transcriptExpanded ? 0.80 : 0.56),
                            in: RoundedRectangle(cornerRadius: 7, style: .continuous)
                        )
                }
                .buttonStyle(PressablePlainButtonStyle())
                .help(transcriptHelp)
                .accessibilityLabel(transcriptHelp)
            }
            .frame(width: 172, height: 28, alignment: .leading)

            if transcriptExpanded {
                MarkdownBody(text: text, font: .body, color: ElephantTheme.ink)
                    .padding(.top, 1)
                    .frame(maxWidth: 520, alignment: .leading)
                    .transition(.opacity)
                    .transaction { transaction in
                        transaction.animation = nil
                    }
            }
        }
        .accessibilityElement(children: .contain)
    }

    private var isActive: Bool {
        speechOutput.activeMessageID == message.id && (speechOutput.isSpeaking || speechOutput.isPreparing)
    }

    private var isPreparing: Bool {
        speechOutput.activeMessageID == message.id && speechOutput.isPreparing
    }

    private var isPlaying: Bool {
        speechOutput.activeMessageID == message.id && speechOutput.isSpeaking
    }

    private var playbackSymbol: String {
        if isPlaying {
            return "stop.fill"
        }
        if isPreparing {
            return "hourglass"
        }
        return "play.fill"
    }

    private var hasPlaybackError: Bool {
        speechOutput.lastFailedMessageID == message.id
    }

    private var playbackTint: Color {
        hasPlaybackError ? ElephantTheme.orange : ElephantTheme.accent
    }

    private var playbackHelp: String {
        if hasPlaybackError, !speechOutput.lastError.isEmpty {
            return speechOutput.lastError
        }
        if isPlaying {
            return localizedYouText(
                model.appLanguage,
                en: "Stop voice reply",
                zh: "停止语音回复",
                fr: "Arrêter la réponse vocale",
                de: "Sprachantwort stoppen"
            )
        }
        if isPreparing {
            return localizedYouText(
                model.appLanguage,
                en: "Preparing voice reply",
                zh: "正在准备语音回复",
                fr: "Préparation de la réponse vocale",
                de: "Sprachantwort wird vorbereitet"
            )
        }
        return localizedYouText(
            model.appLanguage,
            en: "Play voice reply",
            zh: "播放语音回复",
            fr: "Lire la réponse vocale",
            de: "Sprachantwort abspielen"
        )
    }

    private var transcriptHelp: String {
        transcriptExpanded
            ? localizedYouText(
                model.appLanguage,
                en: "Hide reply text",
                zh: "收起回复文本",
                fr: "Masquer le texte",
                de: "Antworttext ausblenden"
            )
            : localizedYouText(
                model.appLanguage,
                en: "Show reply text",
                zh: "展开回复文本",
                fr: "Afficher le texte",
                de: "Antworttext anzeigen"
            )
    }
}

struct VoiceMessageMiniWaveform: View {
    var active = false
    private let levels: [CGFloat] = [0.34, 0.58, 0.78, 0.46, 0.68, 0.88, 0.54, 0.38, 0.72, 0.50, 0.62]

    var body: some View {
        GeometryReader { geometry in
            HStack(alignment: .center, spacing: 2.4) {
                ForEach(Array(levels.enumerated()), id: \.offset) { _, level in
                    RoundedRectangle(cornerRadius: 2, style: .continuous)
                        .fill(ElephantTheme.accent.opacity(active ? 0.78 : 0.48))
                        .frame(width: 3, height: max(5, geometry.size.height * level))
                }
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .center)
        }
    }
}

private func sanitizedAssistantMessageText(_ text: String) -> String {
    text
        .replacingOccurrences(of: #"(?s)<think>.*?</think>"#, with: "", options: .regularExpression)
        .replacingOccurrences(of: #"(?s)<think>.*"#, with: "", options: .regularExpression)
        .replacingOccurrences(of: #"</think>"#, with: "", options: .regularExpression)
        .trimmingCharacters(in: .whitespacesAndNewlines)
}

struct WakeAttachmentStrip: View {
    var attachments: [WakeAttachment]
    var removable = false
    var remove: (WakeAttachment) -> Void = { _ in }

    var body: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(attachments) { attachment in
                    WakeAttachmentChip(attachment: attachment, removable: removable) {
                        remove(attachment)
                    }
                }
            }
            .padding(.vertical, 1)
        }
    }
}

struct WakeAttachmentChip: View {
    @EnvironmentObject private var model: ElephantAppModel
    var attachment: WakeAttachment
    var removable = false
    var remove: () -> Void = {}

    var body: some View {
        HStack(spacing: 7) {
            Group {
                if let image = NSImage(contentsOf: attachment.url) {
                    Image(nsImage: image)
                        .resizable()
                        .aspectRatio(contentMode: .fill)
                } else {
                    Image(systemName: "photo")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(ElephantTheme.muted)
                }
            }
            .frame(width: 28, height: 28)
            .clipShape(RoundedRectangle(cornerRadius: 6, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 6, style: .continuous)
                    .stroke(ElephantTheme.line.opacity(0.62), lineWidth: 1)
            )

            Text(attachment.displayName)
                .font(.caption.weight(.semibold))
                .foregroundStyle(ElephantTheme.ink.opacity(0.74))
                .lineLimit(1)

            if removable {
                Button {
                    remove()
                } label: {
                    Image(systemName: "xmark")
                        .font(.caption2.weight(.bold))
                        .frame(width: 18, height: 18)
                        .foregroundStyle(ElephantTheme.faint)
                }
                .buttonStyle(PressablePlainButtonStyle())
                .help(localizedYouText(model.appLanguage, en: "Remove image", zh: "移除图片", fr: "Retirer l'image", de: "Bild entfernen"))
                .accessibilityLabel(localizedYouText(model.appLanguage, en: "Remove image", zh: "移除图片", fr: "Retirer l'image", de: "Bild entfernen"))
            }
        }
        .padding(.leading, 4)
        .padding(.trailing, removable ? 5 : 8)
        .padding(.vertical, 4)
        .background(ElephantTheme.panel.opacity(0.72), in: RoundedRectangle(cornerRadius: 10, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 10, style: .continuous)
                .stroke(ElephantTheme.line.opacity(0.58), lineWidth: 1)
        )
        .accessibilityLabel(attachment.displayName)
    }
}

struct ToolUseStack: View {
    @EnvironmentObject private var model: ElephantAppModel
    var events: [ToolUseEvent]
    var isLive = false

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            ForEach(childAgentEvents.suffix(3)) { event in
                ChildAgentRunCard(event: event, isLive: isLive)
            }

            if !regularEvents.isEmpty {
                regularToolStack
            }
        }
        .frame(maxWidth: 440, alignment: .leading)
    }

    private var regularToolStack: some View {
        VStack(alignment: .leading, spacing: 5) {
            HStack(spacing: 6) {
                Image(systemName: "wrench.and.screwdriver")
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(ElephantTheme.accent)
                    .frame(width: 15, height: 15)
                    .background(ElephantTheme.accent.opacity(0.09), in: RoundedRectangle(cornerRadius: 4, style: .continuous))
                Text(model.text(.toolActivity))
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink.opacity(0.72))
                Text("\(regularEvents.count)")
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(ElephantTheme.muted)
                    .padding(.horizontal, 4)
                    .padding(.vertical, 1)
                    .background(Color(nsColor: .controlBackgroundColor).opacity(0.74), in: Capsule())
                if isLive && hasRunningEvent {
                    Circle()
                        .fill(ElephantTheme.accent)
                        .frame(width: 5, height: 5)
                    Text(model.text(.live))
                        .font(.caption2.weight(.semibold))
                        .foregroundStyle(ElephantTheme.accent)
                }
                Spacer(minLength: 0)
            }

            ForEach(visibleRegularEvents) { event in
                if let clarifyRequest = ClarifyToolRequest(event: event) {
                    ClarifyToolCard(request: clarifyRequest)
                } else {
                    ToolUseEventRow(event: event)
                }
            }

            if hiddenRegularEventCount > 0 {
                Text(hiddenEventText)
                    .font(.caption2.weight(.medium))
                    .foregroundStyle(ElephantTheme.faint)
                    .padding(.leading, 21)
                    .lineLimit(1)
            }
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 7)
        .frame(maxWidth: 420, alignment: .leading)
        .background(Color(nsColor: .textBackgroundColor).opacity(0.54), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 8, style: .continuous)
                .stroke(ElephantTheme.line.opacity(0.58), lineWidth: 1)
        )
    }

    private var childAgentEvents: [ToolUseEvent] {
        events.filter { $0.isChildAgentRun && !$0.shouldHideInChat }
    }

    private var regularEvents: [ToolUseEvent] {
        events.filter { !$0.isChildAgentRun && !$0.shouldHideInChat }
    }

    private var visibleRegularEvents: [ToolUseEvent] {
        Array(regularEvents.suffix(3))
    }

    private var hiddenRegularEventCount: Int {
        max(0, regularEvents.count - visibleRegularEvents.count)
    }

    private var hiddenEventText: String {
        localizedYouText(
            model.appLanguage,
            en: "+\(hiddenRegularEventCount) earlier action",
            zh: "+\(hiddenRegularEventCount) 个更早动作",
            fr: "+\(hiddenRegularEventCount) action précédente",
            de: "+\(hiddenRegularEventCount) frühere Aktion"
        )
    }

    private var hasRunningEvent: Bool {
        regularEvents.contains { event in
            let status = event.status.lowercased()
            return status.contains("running")
                || status.contains("preparing")
                || status.contains("approved")
                || status.contains("requested")
                || status.contains("classified")
        }
    }
}

struct ChildAgentRunCard: View {
    @EnvironmentObject private var model: ElephantAppModel
    var event: ToolUseEvent
    var isLive = false
    @State private var expanded = false
    @State private var hovering = false

    var body: some View {
        Button {
            withAnimation(.easeInOut(duration: 0.16)) {
                expanded.toggle()
            }
        } label: {
            VStack(alignment: .leading, spacing: 8) {
                HStack(alignment: .center, spacing: 9) {
                    ZStack(alignment: .bottomTrailing) {
                        ProviderLogoView(providerID: event.providerID, displayName: providerLabel, size: 32)
                        if isRunning {
                            ChildAgentPulse(tint: statusTint)
                                .offset(x: 3, y: 3)
                        }
                    }

                    VStack(alignment: .leading, spacing: 3) {
                        Text(titleText)
                            .font(.callout.weight(.semibold))
                            .foregroundStyle(ElephantTheme.ink)
                            .lineLimit(1)
                        Text(subtitleText)
                            .font(.caption)
                            .foregroundStyle(ElephantTheme.muted)
                            .lineLimit(1)
                    }

                    Spacer(minLength: 8)

                    Pill(text: statusText, symbol: statusSymbol, tint: statusTint)

                    Image(systemName: "chevron.right")
                        .font(.caption.weight(.bold))
                        .foregroundStyle(ElephantTheme.faint)
                        .rotationEffect(.degrees(expanded ? 90 : 0))
                }

                if expanded {
                    VStack(alignment: .leading, spacing: 8) {
                        if !taskText.isEmpty {
                            ChildAgentDetailLine(label: localizedYouText(model.appLanguage, en: "Task", zh: "任务", fr: "Tâche", de: "Aufgabe"), value: taskText)
                        }
                        if !summaryText.isEmpty {
                            ChildAgentDetailLine(label: localizedYouText(model.appLanguage, en: "Update", zh: "进展", fr: "Mise à jour", de: "Update"), value: summaryText)
                        }
                        HStack(spacing: 8) {
                            if !runtimeLabel.isEmpty {
                                Pill(text: runtimeLabel, symbol: "terminal", tint: ElephantTheme.accent)
                            }
                            if !event.childEpisodeID.isEmpty {
                                Pill(text: "child \(event.childEpisodeID.prefix(8))", symbol: "rectangle.stack", tint: ElephantTheme.faint)
                            }
                        }
                    }
                    .transition(.opacity)
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 9)
            .frame(maxWidth: 440, alignment: .leading)
            .background(cardFill, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(statusTint.opacity(isRunning ? 0.34 : 0.22), lineWidth: 1)
            )
            .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(PressablePlainButtonStyle())
        .onHover { hovering = $0 }
        .help(expanded ? model.text(.hideToolDetails) : model.text(.showToolDetails))
        .accessibilityLabel("\(titleText), \(statusText)")
    }

    private var titleText: String {
        localizedYouText(
            model.appLanguage,
            en: "\(babyName) is working",
            zh: "\(babyName) 正在工作",
            fr: "\(babyName) travaille",
            de: "\(babyName) arbeitet"
        )
    }

    private var subtitleText: String {
        let provider = providerLabel
        let role = event.babyRole.trimmingCharacters(in: .whitespacesAndNewlines)
        if !role.isEmpty {
            return localizedYouText(
                model.appLanguage,
                en: "Mother delegated to \(role) through \(provider).",
                zh: "母象把任务交给 \(role)，运行时是 \(provider)。",
                fr: "Mother délègue à \(role) via \(provider).",
                de: "Mother delegiert an \(role) über \(provider)."
            )
        }
        return localizedYouText(
            model.appLanguage,
            en: "Mother delegated this to \(provider).",
            zh: "母象把这一步交给 \(provider)。",
            fr: "Mother délègue ceci à \(provider).",
            de: "Mother delegiert das an \(provider)."
        )
    }

    private var babyName: String {
        let value = [event.babyName, event.babyRole, cleanedToolName].first { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty } ?? ""
        if !value.isEmpty { return value }
        return localizedYouText(model.appLanguage, en: "Baby elephant", zh: "小象", fr: "Baby elephant", de: "Baby Elephant")
    }

    private var cleanedToolName: String {
        let value = event.name.trimmingCharacters(in: .whitespacesAndNewlines)
        if value == "tool.sub_agents" || value == "sub_agents" || value == "tool" { return "" }
        return value
    }

    private var providerLabel: String {
        let candidates = [event.runtimeName, event.providerID, event.backend].map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let raw = candidates.first { !$0.isEmpty } ?? "local CLI"
        let lower = raw.lowercased()
        if lower.contains("copilot") { return "GitHub Copilot" }
        if lower.contains("gemini") { return "Gemini CLI" }
        if lower.contains("claude") { return "Claude Code" }
        if lower.contains("cursor") { return "Cursor Agent" }
        if lower.contains("codex") || lower.contains("openai") { return "Codex" }
        if lower == "local_cli" { return "local CLI" }
        return raw
    }

    private var statusText: String {
        localizedToolStatus(event.status, language: model.appLanguage)
    }

    private var statusSymbol: String {
        if isFailure { return "exclamationmark.triangle.fill" }
        if isRunning { return "arrow.triangle.2.circlepath" }
        return "checkmark.circle.fill"
    }

    private var statusTint: Color {
        if isFailure {
            return ElephantTheme.orange
        }
        if isComplete {
            return ElephantTheme.green
        }
        return ElephantTheme.accent
    }

    private var isFailure: Bool {
        let value = event.status.lowercased()
        return value.contains("fail") || value.contains("error") || value.contains("blocked")
    }

    private var isComplete: Bool {
        let value = event.status.lowercased()
        return value.contains("complete") || value.contains("success") || value.contains("done")
    }

    private var isRunning: Bool {
        let value = event.status.lowercased() + " " + event.phase.lowercased()
        return isLive && (
            value.contains("running")
                || value.contains("start")
                || value.contains("preparing")
                || value.contains("requested")
                || value.contains("planned")
        )
    }

    private var taskText: String {
        let value = event.task.trimmingCharacters(in: .whitespacesAndNewlines)
        if !value.isEmpty { return value }
        return event.arguments.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var summaryText: String {
        let value = event.result.trimmingCharacters(in: .whitespacesAndNewlines)
        if !value.isEmpty { return value }
        return event.detail.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private var runtimeLabel: String {
        let modelName = event.runtimeModel.trimmingCharacters(in: .whitespacesAndNewlines)
        if !modelName.isEmpty {
            return "\(providerLabel) · \(modelName)"
        }
        return providerLabel
    }

    private var cardFill: Color {
        let base = statusTint.opacity(isRunning ? 0.095 : 0.065)
        return hovering ? base.opacity(1.30) : base
    }
}

private struct ChildAgentPulse: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var tint: Color

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 20.0, paused: reduceMotion)) { timeline in
            let phase = reduceMotion ? 0.0 : timeline.date.timeIntervalSinceReferenceDate
            let wave = reduceMotion ? 0.0 : (sin(phase * 5.0) + 1.0) / 2.0
            Circle()
                .fill(tint)
                .frame(width: 8, height: 8)
                .overlay(
                    Circle()
                        .stroke(tint.opacity(0.32), lineWidth: 2)
                        .scaleEffect(1.0 + wave * 0.85)
                        .opacity(reduceMotion ? 0 : 0.55 - wave * 0.34)
                )
        }
        .frame(width: 12, height: 12)
    }
}

