private func localizedYouText(_ language: AppLanguage, en: String, zh: String, fr: String, de: String) -> String {
    switch language {
    case .zh: return zh
    case .fr: return fr
    case .de: return de
    case .en: return en
    }
}

private func localizedFormat(_ language: AppLanguage, en: String, zh: String, fr: String, de: String, _ arguments: CVarArg...) -> String {
    String(format: localizedYouText(language, en: en, zh: zh, fr: fr, de: de), arguments: arguments)
}

private func onboardingLetterTitle(_ language: AppLanguage) -> String {
    localizedYouText(
        language,
        en: "A letter from Elephant: we evolve together",
        zh: "来自 Elephant 的一封信：别怕，我们一同进化",
        fr: "Une lettre d'Elephant : nous évoluons ensemble",
        de: "Ein Brief von Elephant: wir wachsen gemeinsam"
    )
}

private func displayedOnboardingLetterContent(_ content: String, language: AppLanguage) -> String {
    var lines = content
        .replacingOccurrences(of: "\r\n", with: "\n")
        .replacingOccurrences(of: "\r", with: "\n")
        .components(separatedBy: "\n")
    guard let titleIndex = lines.firstIndex(where: { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }) else {
        return content
    }
    if isLegacyOnboardingLetterTitle(lines[titleIndex]) {
        lines.remove(at: titleIndex)
        while let first = lines.first, first.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            lines.removeFirst()
        }
    }
    return lines.joined(separator: "\n")
}

private func isLegacyOnboardingLetterTitle(_ line: String) -> Bool {
    let normalized = line
        .replacingOccurrences(of: "#", with: "")
        .trimmingCharacters(in: .whitespacesAndNewlines)
        .lowercased()
    guard normalized.contains("elephant") else { return false }
    return (normalized.contains("first") && normalized.contains("letter"))
        || (normalized.contains("letter") && normalized.contains("from"))
        || normalized.contains("一封信")
        || normalized.contains("第一封信")
        || normalized.contains("première lettre")
        || normalized.contains("erster brief")
}

private func localizedLearningToken(_ rawValue: String, language: AppLanguage) -> String {
    let raw = rawValue.trimmingCharacters(in: .whitespacesAndNewlines)
    let value = raw
        .replacingOccurrences(of: "-", with: "_")
        .replacingOccurrences(of: " ", with: "_")
        .lowercased()
    if value.isEmpty { return "" }
    if value.contains("onboarding_letter") || (value.contains("onboarding") && value.contains("letter")) {
        return localizedYouText(language, en: "first letter", zh: "第一封信", fr: "première lettre", de: "erster Brief")
    }
    if value.contains("paths_learn") {
        return localizedYouText(language, en: "paths learn", zh: "路径学习", fr: "apprentissage parcours", de: "Pfade lernen")
    }
    if value.contains("onboarding_paths") || value == "path_planning" || value.contains("path_planning") {
        return localizedYouText(language, en: "first paths", zh: "第一批路径", fr: "premiers parcours", de: "erste Pfade")
    }
    if value == "letter" || value == "letters" {
        return localizedYouText(language, en: "letter", zh: "信件", fr: "lettre", de: "Brief")
    }
    if value.contains("init_setup") || value.contains("first_setup") || value == "init" {
        return localizedYouText(language, en: "first setup", zh: "首次设置", fr: "première configuration", de: "Ersteinrichtung")
    }
    if value == "pm" || value.contains("personal_model") {
        return localizedYouText(language, en: "personal model", zh: "个人模型", fr: "modèle personnel", de: "persönliches Modell")
    }
    if value == "questions" {
        return localizedYouText(language, en: "questions", zh: "问题", fr: "questions", de: "Fragen")
    }
    if value == "skills" || value == "skill_affinity" {
        return localizedYouText(language, en: "skill affinity", zh: "技能匹配", fr: "affinité compétences", de: "Fähigkeitsabgleich")
    }
    if value == "skill_evolution" || value == "skill_optimization" || value == "skill_creation" {
        return localizedYouText(language, en: "skill drafts", zh: "技能草稿", fr: "brouillons de compétences", de: "Fähigkeitsentwürfe")
    }
    if value == "diary" || value.contains("diary_reflection") {
        return localizedYouText(language, en: "diary", zh: "日记", fr: "journal", de: "Tagebuch")
    }
    if value == "dream" {
        return localizedYouText(language, en: "patterns", zh: "模式", fr: "motifs", de: "Muster")
    }
    if value == "init_links" {
        return localizedYouText(language, en: "public links", zh: "公开链接", fr: "liens publics", de: "öffentliche Links")
    }
    return raw.replacingOccurrences(of: "_", with: " ")
}

private func localizedRuntimeRoleTitle(_ runtime: LocalAgentRuntimeItem, language: AppLanguage) -> String {
    let provider = runtime.providerID.lowercased()
    let rawTitle = runtime.roleTitle.trimmingCharacters(in: .whitespacesAndNewlines)
    if language == .en, !rawTitle.isEmpty {
        return rawTitle
    }
    if provider.contains("codex") {
