private func companionDayText(snapshot: DashboardSnapshot, language: AppLanguage) -> String? {
    guard let days = companionDayCount(snapshot: snapshot) else { return nil }
    return localizedFormat(
        language,
        en: "Day %d together",
        zh: "共同陪伴第 %d 天",
        fr: "Jour %d ensemble",
        de: "Tag %d zusammen",
        days
    )
}

private func companionDayCount(snapshot: DashboardSnapshot) -> Int? {
    guard let startDate = companionStartDate(snapshot: snapshot) else { return nil }
    let calendar = Calendar.current
    let start = calendar.startOfDay(for: startDate)
    let today = calendar.startOfDay(for: Date())
    let dayDelta = calendar.dateComponents([.day], from: start, to: today).day ?? 0
    return max(1, dayDelta + 1)
}

private func companionStartDate(snapshot: DashboardSnapshot) -> Date? {
    let currentStateID = snapshot.currentStateID.replacingOccurrences(of: "state:", with: "")
    let current = snapshot.herdItems.first { item in
        let itemID = item.id.replacingOccurrences(of: "state:", with: "")
        let elephantID = item.elephantID.replacingOccurrences(of: "state:", with: "")
        return item.current || (!currentStateID.isEmpty && (itemID == currentStateID || elephantID == currentStateID))
    }
    let currentCreatedAt = current?.createdAt.trimmingCharacters(in: .whitespacesAndNewlines)
    let rawDate = currentCreatedAt?.isEmpty == false ? currentCreatedAt : snapshot.herdItems.compactMap { item in
        MacLocalDateTime.parse(item.createdAt).map { (date: $0, raw: item.createdAt) }
    }
    .min { $0.date < $1.date }?
    .raw
    guard let rawDate else { return nil }
    return MacLocalDateTime.parse(rawDate)
}

private func formattedTokenWindow(_ tokens: Int) -> String {
    guard tokens > 0 else { return "" }
    if tokens >= 1_000_000 {
        let value = Double(tokens) / 1_000_000.0
        return value >= 10 ? "\(Int(value.rounded()))M" : String(format: "%.1fM", value)
    }
    if tokens >= 1_000 {
        let value = Double(tokens) / 1_000.0
        return value >= 100 ? "\(Int(value.rounded()))k" : String(format: "%.1fk", value)
    }
    return "\(tokens)"
}

private enum MacLocalDateTime {
    static func formatted(_ raw: String, language: AppLanguage, fallback: String = "n/a") -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return fallback }
        guard let date = parse(trimmed) else { return trimmed }
        return formatted(date, language: language)
    }

    static func formattedRange(_ raw: String, language: AppLanguage) -> String {
        let parts = raw.components(separatedBy: " → ")
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        guard !parts.isEmpty else { return "" }
        return parts.map { formatted($0, language: language, fallback: "") }
            .filter { !$0.isEmpty }
            .joined(separator: " → ")
    }

    static func formattedDate(_ raw: String, language: AppLanguage, fallback: String = "n/a") -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { return fallback }
        guard let date = parse(trimmed) else {
            return String(trimmed.prefix(10))
        }
        return formattedDate(date, language: language)
    }

    static func formatted(_ date: Date, language: AppLanguage) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: language.localeIdentifier)
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd HH:mm:ss"
        return formatter.string(from: date)
    }

    static func formattedDate(_ date: Date, language: AppLanguage) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: language.localeIdentifier)
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }

    static func time(_ date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale.current
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "HH:mm:ss"
        return formatter.string(from: date)
    }

    static func parse(_ raw: String) -> Date? {
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return nil }

        let candidates = [
            text,
            text.replacingOccurrences(
                of: #"(\.\d{3})\d+(?=Z|[+-]\d{2}:?\d{2})"#,
                with: "$1",
                options: .regularExpression
            )
        ]

        for candidate in candidates {
            let fractional = ISO8601DateFormatter()
            fractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            if let date = fractional.date(from: candidate) { return date }

            let plain = ISO8601DateFormatter()
            plain.formatOptions = [.withInternetDateTime]
            if let date = plain.date(from: candidate) { return date }
        }

        for pattern in ["yyyy-MM-dd HH:mm:ss", "yyyy-MM-dd'T'HH:mm:ss", "yyyy-MM-dd"] {
            let formatter = DateFormatter()
            formatter.calendar = Calendar.current
            formatter.locale = Locale(identifier: "en_US_POSIX")
            formatter.timeZone = TimeZone.current
            formatter.dateFormat = pattern
            if let date = formatter.date(from: text) { return date }
        }
        return nil
    }
}

private func localizedLensTitle(_ lens: String, language: AppLanguage) -> String {
    switch lens {
    case "world":
        return localizedYouText(language, en: "World", zh: "世界", fr: "Monde", de: "Welt")
    case "pulse":
