        return localizedYouText(language, en: "Ready", zh: "可回答", fr: "Prête", de: "Bereit")
    case "asked":
        return localizedYouText(language, en: "Asked", zh: "已问过", fr: "Posée", de: "Gefragt")
    case "answered":
