private func pathStatusTitle(_ status: String, language: AppLanguage) -> String {
    switch status {
    case "later": return localizedYouText(language, en: "Later", zh: "稍后", fr: "Plus tard", de: "Später")
    case "next": return localizedYouText(language, en: "Next", zh: "下一步", fr: "Suivant", de: "Nächster")
    case "moving": return localizedYouText(language, en: "Working", zh: "工作中", fr: "En travail", de: "In Arbeit")
    case "checking": return localizedYouText(language, en: "Reviewing", zh: "回看中", fr: "En revue", de: "In Prüfung")
    case "done": return localizedYouText(language, en: "Done", zh: "完成", fr: "Terminé", de: "Fertig")
    case "stuck": return localizedYouText(language, en: "Stuck", zh: "卡住", fr: "Bloqué", de: "Blockiert")
    case "dropped": return localizedYouText(language, en: "Dropped", zh: "放下", fr: "Mis de côté", de: "Abgelegt")
    default: return status.capitalized
    }
}

private func pathStatusSymbol(_ status: String) -> String {
    switch status {
    case "later": return "clock"
    case "next": return "circle"
    case "moving": return "arrow.triangle.2.circlepath"
    case "checking": return "checkmark.seal"
    case "done": return "checkmark.circle.fill"
    case "stuck": return "exclamationmark.octagon"
    case "dropped": return "minus.circle"
    default: return "circle"
    }
}

private func pathStatusTint(_ status: String) -> Color {
    switch status {
    case "later": return ElephantTheme.faint
    case "next": return ElephantTheme.accent
    case "moving": return ElephantTheme.orange
    case "checking": return ElephantTheme.green
    case "done": return ElephantTheme.green
    case "stuck", "dropped": return ElephantTheme.ember
    default: return ElephantTheme.accent
    }
}

private func pathStatusProgressValue(_ status: String) -> Double {
    switch status {
    case "later": return 0.08
    case "next": return 0.24
    case "moving": return 0.58
    case "checking": return 0.78
    case "done": return 1.0
    case "stuck": return 0.50
    case "dropped": return 0.0
    default: return 0.0
    }
}

private func pathRunStatusTitle(_ status: String, language: AppLanguage) -> String {
    switch status {
    case "queued": return localizedYouText(language, en: "Queued", zh: "排队中", fr: "En file", de: "Wartet")
    case "dispatched": return localizedYouText(language, en: "Dispatched", zh: "已派发", fr: "Envoyé", de: "Gestartet")
    case "running": return localizedYouText(language, en: "Running", zh: "运行中", fr: "En cours", de: "Läuft")
    case "completed", "succeeded", "success", "done": return localizedYouText(language, en: "Completed", zh: "已完成", fr: "Terminé", de: "Abgeschlossen")
    case "failed": return localizedYouText(language, en: "Failed", zh: "失败", fr: "Échec", de: "Fehlgeschlagen")
    case "cancelled", "canceled": return localizedYouText(language, en: "Cancelled", zh: "已取消", fr: "Annulé", de: "Abgebrochen")
    default: return status.capitalized
    }
}

private func pathRunStatusSymbol(_ status: String) -> String {
    switch status {
    case "queued": return "clock"
    case "dispatched": return "paperplane.fill"
    case "running": return "arrow.triangle.2.circlepath"
    case "completed", "succeeded", "success", "done": return "checkmark.circle.fill"
    case "failed": return "exclamationmark.triangle.fill"
    case "cancelled", "canceled": return "xmark.circle"
    default: return "circle"
    }
}

private func pathRunStatusTint(_ status: String) -> Color {
    switch status {
    case "queued": return ElephantTheme.faint
    case "dispatched", "running": return ElephantTheme.accent
    case "completed", "succeeded", "success", "done": return ElephantTheme.green
    case "failed", "cancelled", "canceled": return ElephantTheme.orange
    default: return ElephantTheme.accent
    }
}

private func pathRunUserFacingText(_ text: String, language: AppLanguage) -> String {
    let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.lowercased().contains("not claim-owned") {
        return localizedYouText(
            language,
            en: "Run lease moved to another worker; this attempt is being recovered.",
            zh: "运行租约已被其他 worker 接管；这次尝试会自动恢复。",
            fr: "Le bail d'exécution a été repris par un autre worker.",
            de: "Der Lauf-Lease wurde von einem anderen Worker übernommen."
        )
    }
    if trimmed == "runtime_claim_changed" {
        return localizedYouText(
            language,
            en: "Run lease changed; another worker is handling it.",
            zh: "运行租约已变化；另一个 worker 正在处理。",
            fr: "Le bail d'exécution a changé.",
            de: "Der Lauf-Lease hat gewechselt."
        )
    }
    return trimmed
}

private func assigneeName(_ elephantID: String, herd: [HerdItem]) -> String {
    herd.first { $0.elephantID == elephantID || $0.id == elephantID }?.title ?? elephantID
}

struct DiaryPanel: View {
    @EnvironmentObject private var model: ElephantAppModel

    var body: some View {
        NativePanel {
            VStack(alignment: .leading, spacing: 16) {
                SectionLabel(
                    title: localizedYouText(model.appLanguage, en: "Diary", zh: "日记", fr: "Journal", de: "Tagebuch"),
                    subtitle: localizedFormat(model.appLanguage, en: "%d entries", zh: "%d 篇", fr: "%d entrées", de: "%d Einträge", model.snapshot.diaryEntries.count)
                )
                if model.snapshot.diaryEntries.isEmpty {
                    EmptyLine(
                        symbol: "book.closed",
                        text: localizedYouText(
                            model.appLanguage,
                            en: "No diary entries yet. Run Reflect with diary enabled after there is enough context.",
                            zh: "还没有日记。等上下文足够后，可以运行带日记的 Reflect。",
                            fr: "Aucune entrée pour l'instant. Lancez Reflect avec le journal quand il y a assez de contexte.",
                            de: "Noch keine Tagebucheinträge. Starte Reflect mit Tagebuch, sobald genug Kontext da ist."
                        )
                    )
                } else {
                    ForEach(model.snapshot.diaryEntries) { entry in
                        VStack(alignment: .leading, spacing: 10) {
                            HStack {
                                Label(
                                    entry.isOnboardingLetter
                                        ? onboardingLetterTitle(model.appLanguage)
                                        : (entry.date.isEmpty ? localizedYouText(model.appLanguage, en: "Diary entry", zh: "日记", fr: "Entrée de journal", de: "Tagebucheintrag") : entry.date),
                                    systemImage: entry.isOnboardingLetter ? "heart.text.square" : "book.closed"
                                )
                                    .font(.headline)
                                    .foregroundStyle(entry.isOnboardingLetter ? ElephantTheme.ember : ElephantTheme.ink)
                                Spacer()
                                if entry.isOnboardingLetter {
                                    Button {
                                        model.openOnboardingLetter(entry)
                                    } label: {
                                        Label(localizedYouText(model.appLanguage, en: "Open letter", zh: "打开信", fr: "Ouvrir", de: "Öffnen"), systemImage: "heart.fill")
                                            .labelStyle(.titleAndIcon)
                                            .font(.caption.weight(.semibold))
                                            .foregroundStyle(ElephantTheme.ember)
                                            .padding(.horizontal, 12)
                                            .padding(.vertical, 7)
                                            .background(Color.white.opacity(0.58), in: Capsule())
                                            .overlay(Capsule().stroke(ElephantTheme.ember.opacity(0.24), lineWidth: 1))
                                    }
                                    .buttonStyle(PressablePlainButtonStyle())
                                }
                                if entry.sourceCount > 0 {
                                    Label(
                                        localizedFormat(model.appLanguage, en: "%d sources", zh: "%d 个来源", fr: "%d sources", de: "%d Quellen", entry.sourceCount),
                                        systemImage: "link"
                                    )
                                    .font(.caption2.weight(.semibold))
                                    .foregroundStyle(ElephantTheme.muted)
                                    .lineLimit(1)
                                    .padding(.horizontal, 8)
                                    .padding(.vertical, 4)
                                    .background(ElephantTheme.panel.opacity(0.66), in: Capsule())
                                    .overlay(Capsule().stroke(ElephantTheme.line.opacity(0.50), lineWidth: 1))
                                    .help(localizedYouText(model.appLanguage, en: "Source Episodes", zh: "来源对话", fr: "Épisodes sources", de: "Quell-Episoden"))
                                    .accessibilityLabel(localizedFormat(model.appLanguage, en: "%d source Episodes", zh: "%d 个来源对话", fr: "%d épisodes sources", de: "%d Quell-Episoden", entry.sourceCount))
                                }
                                if !entry.generatedAt.isEmpty {
                                    Text(MacLocalDateTime.formattedDate(entry.generatedAt, language: model.appLanguage))
                                        .font(.caption)
                                        .foregroundStyle(ElephantTheme.muted)
                                }
                            }
                            MarkdownBody(text: entry.isOnboardingLetter ? displayedOnboardingLetterContent(entry.content, language: model.appLanguage) : entry.content, font: .callout, color: ElephantTheme.ink)
                        }
                        .padding(.vertical, entry.isOnboardingLetter ? 14 : 6)
                        .padding(.horizontal, entry.isOnboardingLetter ? 14 : 0)
                        .background {
                            if entry.isOnboardingLetter {
                                RoundedRectangle(cornerRadius: 14, style: .continuous)
                                    .fill(
                                        LinearGradient(
                                            colors: [
                                                ElephantTheme.ember.opacity(0.060),
                                                ElephantTheme.gold.opacity(0.080),
                                                Color.white.opacity(0.20)
                                            ],
                                            startPoint: .topLeading,
                                            endPoint: .bottomTrailing
                                        )
                                    )
                            }
                        }
                        .overlay {
                            if entry.isOnboardingLetter {
                                RoundedRectangle(cornerRadius: 14, style: .continuous)
                                    .stroke(ElephantTheme.gold.opacity(0.20), lineWidth: 1)
                            }
                        }
                        if entry.id != model.snapshot.diaryEntries.last?.id {
                            Divider()
                                .padding(.top, entry.isOnboardingLetter ? 2 : 0)
                        }
                    }
                }
            }
        }
    }
}

struct DiaryView: View {
    @EnvironmentObject private var model: ElephantAppModel
    @State private var targetDate = Self.defaultDiaryDate()
    @State private var showsDatePicker = false

    var body: some View {
        let writeDisabled = model.learningLaunchDisabled
        VStack(alignment: .leading, spacing: 18) {
            PageHeader(
                title: AppSection.diary.title(language: model.appLanguage),
                subtitle: model.text(.diaryPageSubtitle),
                actionTitle: model.isReflecting ? model.text(.writing) : model.hasActiveLearningJobs ? model.text(.learning) : model.text(.writeDiary),
                actionSymbol: "square.and.pencil",
                actionIconOnly: true,
                actionDisabled: writeDisabled
            ) {
                writeDiaryForSelectedDate()
            }

            NativePanel {
                VStack(alignment: .leading, spacing: 16) {
                    HStack(alignment: .top, spacing: 12) {
                        Image(systemName: "calendar.badge.clock")
                            .font(.title3)
                            .foregroundStyle(ElephantTheme.accent)
                            .frame(width: 28, height: 28)
                            .accessibilityHidden(true)
                        VStack(alignment: .leading, spacing: 3) {
                            SectionLabel(
                                title: model.text(.writeDiary),
                                subtitle: localizedYouText(
                                    model.appLanguage,
                                    en: "Pick a day with reviewed episodes. Yesterday is selected by default.",
                                    zh: "选择有已回看 episodes 的日期。默认选昨天。",
                                    fr: "Choisissez un jour avec des épisodes revus. Hier est sélectionné par défaut.",
                                    de: "Wähle einen Tag mit geprüften Episoden. Gestern ist vorausgewählt."
                                )
                            )
                            Text(selectedDateDisplay)
                                .font(.caption.weight(.medium))
                                .foregroundStyle(ElephantTheme.faint)
                        }
                        Spacer(minLength: 16)
                        diaryStatus
                    }

                    ViewThatFits(in: .horizontal) {
                        HStack(alignment: .center, spacing: 14) {
                            diaryDateControls
                            Spacer(minLength: 16)
                            writeDiaryButton
                        }

                        VStack(alignment: .leading, spacing: 12) {
                            diaryDateControls
                            writeDiaryButton
                        }
                    }
                }
            }

            DiaryPanel()
        }
    }

    private var diaryDateControls: some View {
        HStack(spacing: 8) {
            DiaryStepButton(
                symbol: "chevron.left",
                title: localizedYouText(model.appLanguage, en: "Previous diary day", zh: "前一天日记", fr: "Jour de journal précédent", de: "Vorheriger Tagebuchtag")
            ) {
                moveTargetDate(by: -1)
            }
            .help(localizedYouText(model.appLanguage, en: "Previous day", zh: "前一天", fr: "Jour précédent", de: "Vorheriger Tag"))

            DiaryDateSelectorButton(
                title: compactDateTitle,
                subtitle: compactDateSubtitle,
                isPresented: showsDatePicker
            ) {
                showsDatePicker.toggle()
            }
            .popover(isPresented: $showsDatePicker, arrowEdge: .bottom) {
                VStack(alignment: .leading, spacing: 12) {
                    DatePicker(localizedYouText(model.appLanguage, en: "Diary day", zh: "日记日期", fr: "Jour du journal", de: "Tagebuchtag"), selection: $targetDate, displayedComponents: .date)
                        .datePickerStyle(.graphical)
                        .labelsHidden()
                        .frame(width: 300)
                    HStack(spacing: 8) {
                        DiaryQuickDateButton(
                            title: localizedYouText(model.appLanguage, en: "Yesterday", zh: "昨天", fr: "Hier", de: "Gestern"),
                            symbol: "arrow.counterclockwise",
                            isSelected: isTargetDate(relativeToTodayBy: -1)
                        ) {
                            setTargetDate(relativeToTodayBy: -1)
                        }
                        DiaryQuickDateButton(
                            title: localizedYouText(model.appLanguage, en: "Today", zh: "今天", fr: "Aujourd'hui", de: "Heute"),
                            symbol: "sun.max",
                            isSelected: isTargetDate(relativeToTodayBy: 0)
                        ) {
                            setTargetDate(relativeToTodayBy: 0)
                        }
                        Spacer()
                        Button(localizedYouText(model.appLanguage, en: "Done", zh: "完成", fr: "Terminé", de: "Fertig")) {
                            showsDatePicker = false
                        }
                        .keyboardShortcut(.defaultAction)
                    }
                }
                .padding(14)
                .environment(\.locale, Locale(identifier: model.appLanguage.localeIdentifier))
            }
            .help(localizedYouText(model.appLanguage, en: "Choose diary day", zh: "选择日记日期", fr: "Choisir le jour du journal", de: "Tagebuchtag wählen"))
            .accessibilityLabel(localizedYouText(model.appLanguage, en: "Diary day", zh: "日记日期", fr: "Jour du journal", de: "Tagebuchtag"))

            DiaryStepButton(
                symbol: "chevron.right",
                title: localizedYouText(model.appLanguage, en: "Next diary day", zh: "后一天日记", fr: "Jour de journal suivant", de: "Nächster Tagebuchtag")
            ) {
                moveTargetDate(by: 1)
            }
            .help(localizedYouText(model.appLanguage, en: "Next day", zh: "后一天", fr: "Jour suivant", de: "Nächster Tag"))

            Divider()
                .frame(height: 24)

            DiaryQuickDateButton(
                title: localizedYouText(model.appLanguage, en: "Yesterday", zh: "昨天", fr: "Hier", de: "Gestern"),
                symbol: "arrow.counterclockwise",
                isSelected: isTargetDate(relativeToTodayBy: -1)
            ) {
                setTargetDate(relativeToTodayBy: -1)
            }
            .help(localizedYouText(model.appLanguage, en: "Select yesterday", zh: "选择昨天", fr: "Sélectionner hier", de: "Gestern auswählen"))

            DiaryQuickDateButton(
                title: localizedYouText(model.appLanguage, en: "Today", zh: "今天", fr: "Aujourd'hui", de: "Heute"),
                symbol: "sun.max",
                isSelected: isTargetDate(relativeToTodayBy: 0)
            ) {
                setTargetDate(relativeToTodayBy: 0)
            }
            .help(localizedYouText(model.appLanguage, en: "Select today", zh: "选择今天", fr: "Sélectionner aujourd'hui", de: "Heute auswählen"))
        }
    }

    private var writeDiaryButton: some View {
        DiaryWriteActionButton(
            title: model.isReflecting ? model.text(.writing) : model.hasActiveLearningJobs ? model.text(.learning) : model.text(.writeDiary),
            subtitle: localizedFormat(model.appLanguage, en: "For %@", zh: "日期：%@", fr: "Pour %@", de: "Für %@", selectedDateDisplay),
            isDisabled: model.learningLaunchDisabled
        ) {
            writeDiaryForSelectedDate()
        }
        .help(localizedFormat(model.appLanguage, en: "Write diary for %@", zh: "写 %@ 的日记", fr: "Écrire le journal pour %@", de: "Tagebuch für %@ schreiben", selectedDateDisplay))
    }

    @ViewBuilder
    private var diaryStatus: some View {
        if model.isReflecting {
            HStack(spacing: 8) {
                ProgressView()
                    .controlSize(.small)
                Text(localizedYouText(model.appLanguage, en: "Writing diary", zh: "正在写日记", fr: "Écriture du journal", de: "Tagebuch wird geschrieben"))
                    .font(.callout)
                    .foregroundStyle(ElephantTheme.muted)
            }
        } else if model.hasActiveLearningJobs {
            Label(localizedYouText(model.appLanguage, en: "A learning job is already running.", zh: "已有学习任务正在运行。", fr: "Une tâche d'apprentissage est déjà en cours.", de: "Ein Lernjob läuft bereits."), systemImage: "arrow.triangle.2.circlepath")
                .font(.callout)
                .foregroundStyle(ElephantTheme.muted)
                .lineLimit(2)
                .multilineTextAlignment(.trailing)
        } else if !model.diaryActionResult.isEmpty {
            Label(model.diaryActionResult, systemImage: "checkmark.circle.fill")
                .font(.callout)
                .foregroundStyle(ElephantTheme.green)
                .lineLimit(2)
                .multilineTextAlignment(.trailing)
        }
    }

    private var requestDateString: String {
        Self.requestDateFormatter.string(from: targetDate)
    }

    private var selectedDateDisplay: String {
        Self.localizedDate(targetDate, language: model.appLanguage, dateStyle: .full)
    }

    private var compactDateTitle: String {
        Self.localizedDate(targetDate, language: model.appLanguage, template: "EEE MMM d")
    }

    private var compactDateSubtitle: String {
        Self.localizedDate(targetDate, language: model.appLanguage, template: "yyyy")
    }

    private func writeDiaryForSelectedDate() {
        let date = requestDateString
        Task { await model.writeDiary(targetDate: date) }
    }

    private func moveTargetDate(by dayDelta: Int) {
        targetDate = Calendar.current.date(byAdding: .day, value: dayDelta, to: targetDate) ?? targetDate
    }

    private func setTargetDate(relativeToTodayBy dayDelta: Int) {
        targetDate = Calendar.current.date(byAdding: .day, value: dayDelta, to: Date()) ?? Date()
    }

    private func isTargetDate(relativeToTodayBy dayDelta: Int) -> Bool {
        let referenceDate = Calendar.current.date(byAdding: .day, value: dayDelta, to: Date()) ?? Date()
        return Calendar.current.isDate(targetDate, inSameDayAs: referenceDate)
    }

    private static func defaultDiaryDate() -> Date {
        Calendar.current.date(byAdding: .day, value: -1, to: Date()) ?? Date()
    }

    private static let requestDateFormatter: DateFormatter = {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter
    }()

    private static func localizedDate(_ date: Date, language: AppLanguage, dateStyle: DateFormatter.Style) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: language.localeIdentifier)
        formatter.timeZone = TimeZone.current
        formatter.dateStyle = dateStyle
        formatter.timeStyle = .none
        return formatter.string(from: date)
    }

    private static func localizedDate(_ date: Date, language: AppLanguage, template: String) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: language.localeIdentifier)
        formatter.timeZone = TimeZone.current
        formatter.setLocalizedDateFormatFromTemplate(template)
        return formatter.string(from: date)
    }
}

private struct DiaryStepButton: View {
    var symbol: String
    var title: String
    var action: () -> Void
    @State private var hovering = false

    var body: some View {
        Button(action: action) {
            Image(systemName: symbol)
                .font(.system(size: 13, weight: .semibold))
                .foregroundStyle(hovering ? ElephantTheme.accent : ElephantTheme.muted)
                .frame(width: 30, height: 30)
                .background(
                    (hovering ? ElephantTheme.accent.opacity(0.10) : Color(nsColor: .controlBackgroundColor).opacity(0.58)),
                    in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(hovering ? ElephantTheme.accent.opacity(0.28) : ElephantTheme.line.opacity(0.62), lineWidth: 1)
                )
                .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(PressablePlainButtonStyle())
        .onHover { hovering = $0 }
        .accessibilityLabel(title)
    }
}

private struct DiaryDateSelectorButton: View {
    var title: String
    var subtitle: String
    var isPresented: Bool
    var action: () -> Void
    @State private var hovering = false

    var body: some View {
        Button(action: action) {
            HStack(spacing: 10) {
                Image(systemName: "calendar")
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(ElephantTheme.accent)
                    .frame(width: 20, height: 20)
                    .background(ElephantTheme.accent.opacity(0.10), in: RoundedRectangle(cornerRadius: 6, style: .continuous))

                VStack(alignment: .leading, spacing: 1) {
                    Text(title)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                        .minimumScaleFactor(0.82)
                    Text(subtitle)
                        .font(.caption2)
                        .foregroundStyle(ElephantTheme.muted)
                        .lineLimit(1)
                }

                Image(systemName: "chevron.down")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.faint)
                    .rotationEffect(.degrees(isPresented ? 180 : 0))
            }
            .padding(.horizontal, 12)
            .padding(.vertical, 8)
            .frame(minWidth: 184, minHeight: 44, alignment: .leading)
            .background(background, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(border, lineWidth: 1)
            )
            .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(PressablePlainButtonStyle())
        .onHover { hovering = $0 }
        .animation(.easeOut(duration: 0.14), value: isPresented)
    }

    private var background: Color {
        isPresented || hovering
            ? Color(nsColor: .controlBackgroundColor).opacity(0.96)
            : Color(nsColor: .controlBackgroundColor).opacity(0.72)
    }

    private var border: Color {
        isPresented
            ? ElephantTheme.accent.opacity(0.46)
            : hovering ? ElephantTheme.accent.opacity(0.30) : ElephantTheme.line.opacity(0.68)
    }
}

private struct DiaryQuickDateButton: View {
    var title: String
    var symbol: String
    var isSelected: Bool
    var action: () -> Void
    @State private var hovering = false

    var body: some View {
        Button(action: action) {
            Label(title, systemImage: symbol)
                .font(.callout.weight(.semibold))
                .foregroundStyle(foreground)
                .lineLimit(1)
                .padding(.horizontal, 11)
                .frame(height: 32)
                .background(background, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(border, lineWidth: 1)
                )
                .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(PressablePlainButtonStyle())
        .onHover { hovering = $0 }
        .accessibilityLabel(title)
    }

    private var foreground: Color {
        if isSelected { return .white }
        return hovering ? ElephantTheme.accent : ElephantTheme.ink
    }

    private var background: Color {
        if isSelected { return ElephantTheme.accent }
        return hovering
            ? ElephantTheme.accent.opacity(0.10)
            : Color(nsColor: .controlBackgroundColor).opacity(0.68)
    }

    private var border: Color {
        if isSelected { return Color.white.opacity(0.20) }
        return hovering ? ElephantTheme.accent.opacity(0.30) : ElephantTheme.line.opacity(0.62)
    }
}

private struct DiaryWriteActionButton: View {
    var title: String
    var subtitle: String
    var isDisabled: Bool
    var action: () -> Void
    @State private var hovering = false

    var body: some View {
        Button {
            guard !isDisabled else { return }
            action()
        } label: {
            HStack(spacing: 11) {
                Image(systemName: isDisabled ? "hourglass" : "square.and.pencil")
                    .font(.system(size: 15, weight: .semibold))
                    .foregroundStyle(isDisabled ? ElephantTheme.faint : ElephantTheme.accent)
                    .frame(width: 32, height: 32)
                    .background(iconBackground, in: RoundedRectangle(cornerRadius: 8, style: .continuous))

                VStack(alignment: .leading, spacing: 2) {
                    Text(title)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(isDisabled ? ElephantTheme.faint : ElephantTheme.ink)
                        .lineLimit(1)
                    Text(subtitle)
                        .font(.caption2)
                        .foregroundStyle(isDisabled ? ElephantTheme.faint : ElephantTheme.muted)
                        .lineLimit(1)
                        .minimumScaleFactor(0.86)
                }
            }
            .padding(.horizontal, 13)
            .padding(.vertical, 8)
            .frame(minHeight: 48, alignment: .leading)
            .background(background, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(border, lineWidth: 1)
            )
            .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .buttonStyle(PressablePlainButtonStyle())
        .disabled(isDisabled)
        .opacity(isDisabled ? 0.68 : 1)
        .onHover { hovering = $0 }
        .accessibilityLabel("\(title), \(subtitle)")
    }

    private var iconBackground: Color {
        isDisabled ? ElephantTheme.faint.opacity(0.10) : ElephantTheme.accent.opacity(0.12)
    }

    private var background: Color {
        if isDisabled { return Color(nsColor: .controlBackgroundColor).opacity(0.58) }
        return hovering
            ? ElephantTheme.accent.opacity(0.13)
            : ElephantTheme.accent.opacity(0.08)
    }

    private var border: Color {
        if isDisabled { return ElephantTheme.line.opacity(0.52) }
        return hovering ? ElephantTheme.accent.opacity(0.44) : ElephantTheme.accent.opacity(0.22)
    }
}

struct SkillsView: View {
    @EnvironmentObject private var model: ElephantAppModel

    var body: some View {
        VStack(alignment: .leading, spacing: 18) {
            PageHeader(
                title: AppSection.skills.title(language: model.appLanguage),
                subtitle: model.text(.skillsPageSubtitle),
                actionTitle: model.text(.refresh),
                actionSymbol: "arrow.clockwise"
            ) {
                Task { try? await model.refreshDashboard() }
            }

            HStack(spacing: 12) {
                MetricTile(label: localizedYouText(model.appLanguage, en: "Installed", zh: "已安装", fr: "Installés", de: "Installiert"), value: "\(model.snapshot.skills)", symbol: "wand.and.stars")
                MetricTile(label: localizedYouText(model.appLanguage, en: "For you", zh: "适合你的技能", fr: "Pour vous", de: "Für dich"), value: "\(model.snapshot.skillAffinities)", symbol: "sparkles", tint: ElephantTheme.orange)
                MetricTile(label: localizedYouText(model.appLanguage, en: "Drafts", zh: "草稿", fr: "Brouillons", de: "Entwürfe"), value: "\(pendingDrafts)", symbol: "sparkles", tint: ElephantTheme.evolution)
                MetricTile(label: localizedYouText(model.appLanguage, en: "Enabled", zh: "已启用", fr: "Activés", de: "Aktiviert"), value: "\(enabledSkills)", symbol: "checkmark.seal", tint: ElephantTheme.green)
            }

            SkillAffinityPanel()
            SkillLibraryPanel()
        }
    }

    private var enabledSkills: Int {
        let enabled = model.snapshot.skillItems.filter(\.enabled).count
        if enabled > 0 || !model.snapshot.skillItems.isEmpty {
            return enabled
        }
        return model.snapshot.skills
    }

    private var pendingDrafts: Int {
        model.snapshot.skillItems.filter {
            $0.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() == "pending" && !$0.enabled
        }.count
    }
}

