private struct GatewayServiceLogo: View {
    var service: GatewayServiceItem

    var body: some View {
        ZStack(alignment: .bottomTrailing) {
            RoundedRectangle(cornerRadius: 8, style: .continuous)
                .fill(spec.tint.opacity(0.11))
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(spec.tint.opacity(0.22), lineWidth: 1)
                )
            Image(systemName: spec.symbol)
                .font(.system(size: 18, weight: .semibold))
                .foregroundStyle(spec.tint)
            Circle()
                .fill(statusTint)
                .frame(width: 9, height: 9)
                .overlay(Circle().stroke(Color(nsColor: .textBackgroundColor), lineWidth: 1.5))
                .offset(x: 2, y: 2)
        }
        .frame(width: 42, height: 42)
        .accessibilityHidden(true)
    }

    private var spec: GatewayLogoSpec {
        GatewayLogoSpec.forService(service)
    }

    private var statusTint: Color {
        if service.running { return ElephantTheme.green }
        if service.starting { return ElephantTheme.accent }
        if service.configured { return ElephantTheme.green }
        return ElephantTheme.faint
    }
}

private struct GatewayLogoSpec {
    var symbol: String
    var tint: Color

    static func forService(_ service: GatewayServiceItem) -> GatewayLogoSpec {
        let raw = "\(service.id) \(service.title)".lowercased()
        if raw.contains("wechat") || raw.contains("weixin") || raw.contains("微信") {
            return GatewayLogoSpec(symbol: "message.circle.fill", tint: ElephantTheme.green)
        }
        if raw.contains("feishu") || raw.contains("lark") {
            return GatewayLogoSpec(symbol: "paperplane.fill", tint: ElephantTheme.accent)
        }
        if raw.contains("discord") {
            return GatewayLogoSpec(symbol: "gamecontroller.fill", tint: ElephantTheme.accent)
        }
        if raw.contains("ding") {
            return GatewayLogoSpec(symbol: "bell.and.waves.left.and.right.fill", tint: ElephantTheme.orange)
        }
        if raw.contains("wecom") || raw.contains("work") {
            return GatewayLogoSpec(symbol: "building.2.crop.circle.fill", tint: ElephantTheme.green)
        }
        return GatewayLogoSpec(symbol: "message.badge.fill", tint: ElephantTheme.accent)
    }
}

struct GatewaySecretEditor: View {
    @EnvironmentObject private var model: ElephantAppModel
    var service: GatewayServiceItem

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ForEach(service.secretFields) { field in
                LabeledContent(field.label) {
                    SecureField(
                        field.hasValue
                            ? localizedYouText(model.appLanguage, en: "stored locally", zh: "已保存在本机", fr: "stocké localement", de: "lokal gespeichert")
                            : localizedYouText(model.appLanguage, en: "paste once", zh: "粘贴一次即可", fr: "coller une fois", de: "einmal einfügen"),
                        text: binding(for: field.key)
                    )
                        .textFieldStyle(.roundedBorder)
                }
            }
        }
    }

    private func binding(for key: String) -> Binding<String> {
        Binding(
            get: { model.gatewaySecretDrafts[service.id]?[key] ?? "" },
            set: { value in
                var serviceDraft = model.gatewaySecretDrafts[service.id] ?? [:]
                serviceDraft[key] = value
                model.gatewaySecretDrafts[service.id] = serviceDraft
            }
        )
    }
}

struct WeixinQRPanel: View {
    @EnvironmentObject private var model: ElephantAppModel
    var service: GatewayServiceItem

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            MessagingServiceActionButton(
                title: startButtonTitle,
                subtitle: actionSubtitle,
                symbol: "qrcode.viewfinder",
                tint: ElephantTheme.green,
                isWorking: model.gatewayActionInFlight || model.gatewayQRPolling || model.gatewayQRAutoPolling,
                isDisabled: model.gatewayActionInFlight
            ) {
                Task { await model.startWeixinQR() }
            }

            if !model.gatewayQR.matrix.isEmpty {
                HStack(alignment: .center, spacing: 14) {
                    GatewayQRMatrixView(matrix: model.gatewayQR.matrix)
                        .frame(width: 148, height: 148)
                    VStack(alignment: .leading, spacing: 8) {
                        Text(localizedYouText(model.appLanguage, en: "Scan with WeChat", zh: "用微信扫码", fr: "Scanner avec WeChat", de: "Mit WeChat scannen"))
                            .font(.headline)
                            .foregroundStyle(ElephantTheme.ink)
                        Text(qrInstruction)
                            .font(.callout)
                            .foregroundStyle(ElephantTheme.muted)
                            .fixedSize(horizontal: false, vertical: true)
                        HStack(spacing: 8) {
                            if !model.gatewayQR.status.isEmpty {
                                Pill(text: qrStatusLabel, symbol: "qrcode.viewfinder", tint: qrTint)
                            }
                            if model.gatewayQRAutoPolling {
                                Label(localizedYouText(model.appLanguage, en: "Checking automatically", zh: "正在自动检查", fr: "Vérification automatique", de: "Prüft automatisch"), systemImage: "dot.radiowaves.left.and.right")
                                    .font(.caption.weight(.semibold))
                                    .foregroundStyle(ElephantTheme.accent)
                            }
                        }
                    }
                }
                .padding(12)
                .background(Color(nsColor: .textBackgroundColor).opacity(0.76), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line.opacity(0.78), lineWidth: 1))
            } else {
                EmptyLine(
                    symbol: "qrcode.viewfinder",
                    text: localizedYouText(
                        model.appLanguage,
                        en: "No QR code yet. Click connect to generate one.",
                        zh: "还没有二维码。点击连接后会生成并自动等待扫码。",
                        fr: "Aucun QR pour le moment. Cliquez sur connecter pour en créer un.",
                        de: "Noch kein QR-Code. Verbinden erstellt einen neuen."
                    )
                )
            }
        }
    }

    private var startButtonTitle: String {
        if !model.gatewayQR.sessionID.isEmpty {
            return localizedYouText(model.appLanguage, en: "Regenerate QR", zh: "重新生成二维码", fr: "Regénérer le QR", de: "QR neu erstellen")
        }
        if service.configured || service.running {
            return localizedYouText(model.appLanguage, en: "Reconnect WeChat", zh: "重新连接微信", fr: "Reconnecter WeChat", de: "WeChat neu verbinden")
        }
        return localizedYouText(model.appLanguage, en: "Connect WeChat", zh: "连接微信", fr: "Connecter WeChat", de: "WeChat verbinden")
    }

    private var actionSubtitle: String {
        if !model.gatewayQR.sessionID.isEmpty {
            return localizedYouText(model.appLanguage, en: "Use this only if the current QR expired or you want another account.", zh: "只有当前二维码过期或想换账号时，才需要重新生成。", fr: "À utiliser si le QR a expiré ou pour changer de compte.", de: "Nur nutzen, wenn der QR abgelaufen ist oder ein anderes Konto gewünscht ist.")
        }
        return localizedYouText(model.appLanguage, en: "Scan once and confirm on your phone. It connects automatically.", zh: "扫码一次并在手机上确认，之后会自动连接。", fr: "Scannez une fois et confirmez sur le téléphone. La connexion est automatique.", de: "Einmal scannen und am Telefon bestaetigen. Danach verbindet es automatisch.")
    }

    private var qrInstruction: String {
        switch normalizedQRStatus {
        case "confirmed":
            return localizedYouText(model.appLanguage, en: "Confirmed. Connecting WeChat now.", zh: "微信已确认，正在连接聊天服务。", fr: "Confirmé. Connexion à WeChat en cours.", de: "Bestätigt. WeChat wird verbunden.")
        case "need_verifycode":
            return localizedYouText(model.appLanguage, en: "Scanned. Confirm the verification code on your phone.", zh: "已扫描，请在手机上确认验证码。", fr: "QR scanné. Confirmez le code sur votre téléphone.", de: "QR gescannt. Bitte Code am Telefon bestätigen.")
        case "scaned_but_redirect":
            return localizedYouText(model.appLanguage, en: "Scanned. Switching verification channel.", zh: "已扫描，正在切换校验通道。", fr: "QR scanné. Changement du canal de vérification.", de: "QR gescannt. Prüfkanal wird gewechselt.")
        default:
            if normalizedQRStatus.contains("expire") {
                return localizedYouText(model.appLanguage, en: "This QR code expired. Generate a new one.", zh: "二维码已过期，请重新生成。", fr: "Ce QR a expiré. Générez-en un nouveau.", de: "Dieser QR ist abgelaufen. Bitte neu erstellen.")
            }
            return localizedYouText(model.appLanguage, en: "Scan and confirm on your phone. The app checks the result automatically.", zh: "扫码并在手机上确认，Mac 会自动检查结果。", fr: "Scannez et confirmez sur le téléphone. L'app vérifie automatiquement.", de: "Scannen und am Telefon bestätigen. Die App prüft automatisch.")
        }
    }

    private var qrStatusLabel: String {
        switch normalizedQRStatus {
        case "confirmed":
            return localizedYouText(model.appLanguage, en: "confirmed", zh: "已确认", fr: "confirmé", de: "bestätigt")
        case "need_verifycode":
            return localizedYouText(model.appLanguage, en: "confirm on phone", zh: "手机确认", fr: "confirmer", de: "bestätigen")
        case "scaned_but_redirect":
            return localizedYouText(model.appLanguage, en: "scanned", zh: "已扫描", fr: "scanné", de: "gescannt")
        default:
            if normalizedQRStatus.contains("expire") {
                return localizedYouText(model.appLanguage, en: "expired", zh: "已过期", fr: "expiré", de: "abgelaufen")
            }
            if normalizedQRStatus.contains("fail") || normalizedQRStatus.contains("error") || normalizedQRStatus.contains("reject") {
                return localizedYouText(model.appLanguage, en: "failed", zh: "失败", fr: "échec", de: "fehlgeschlagen")
            }
            return localizedYouText(model.appLanguage, en: "waiting", zh: "等待扫码", fr: "attente", de: "wartet")
        }
    }

    private var qrTint: Color {
        if normalizedQRStatus == "confirmed" { return ElephantTheme.green }
        if normalizedQRStatus.contains("expire") || normalizedQRStatus.contains("fail") || normalizedQRStatus.contains("error") || normalizedQRStatus.contains("reject") {
            return ElephantTheme.orange
        }
        return ElephantTheme.accent
    }

    private var normalizedQRStatus: String {
        model.gatewayQR.status.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    }

}

struct GatewayQRMatrixView: View {
    var matrix: [[Int]]

    var body: some View {
        GeometryReader { proxy in
            Canvas { context, size in
                let rows = max(matrix.count, 1)
                let cols = max(matrix.first?.count ?? rows, 1)
                let cell = min(size.width / CGFloat(cols), size.height / CGFloat(rows))
                let origin = CGPoint(
                    x: (size.width - CGFloat(cols) * cell) / 2,
                    y: (size.height - CGFloat(rows) * cell) / 2
                )
                for row in 0..<rows {
                    let values = row < matrix.count ? matrix[row] : []
                    for col in 0..<cols where col < values.count && values[col] != 0 {
                        let rect = CGRect(x: origin.x + CGFloat(col) * cell, y: origin.y + CGFloat(row) * cell, width: cell, height: cell)
                        context.fill(Path(rect), with: .color(ElephantTheme.ink))
                    }
                }
            }
        }
        .padding(10)
        .background(.white, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
    }
}

struct HerdView: View {
    @EnvironmentObject private var model: ElephantAppModel
    @State private var showingCreate = false
    @State private var selectedKind = "mother"
    @State private var selectedID = ""

    private var motherItems: [HerdItem] {
        let mothers = model.snapshot.herdItems.filter { $0.herdKind == "mother" || $0.elephantID == "mother-elephant" }
        if !mothers.isEmpty { return mothers }
        return model.snapshot.herdItems.filter { !$0.herdKind.elementsEqual("baby") }.prefix(1).map { $0 }
    }

    private var babyItems: [HerdItem] {
        model.snapshot.herdItems.filter { $0.herdKind == "baby" }
    }

    private var discoveredCandidates: [LocalAgentRuntimeItem] {
        let adoptedRuntimeIDs = Set(model.snapshot.herdItems.map(\.runtimeID).filter { !$0.isEmpty })
        return model.snapshot.localAgentRuntimes.filter { !adoptedRuntimeIDs.contains($0.runtimeID) }
    }

    var body: some View {
        GeometryReader { proxy in
            let panelHeight = max(760, proxy.size.height - 42)

            VStack(alignment: .leading, spacing: 18) {
                PageHeader(
                    title: AppSection.herd.title(language: model.appLanguage),
                    subtitle: localizedYouText(model.appLanguage, en: "Mother keeps context. Baby elephants bring local CLI skills when she delegates.", zh: "母象守住上下文，小象在需要时带着本地 CLI 技能加入。", fr: "Mother garde le contexte; les babies apportent les CLI locaux.", de: "Mother hält Kontext; Babies bringen lokale CLI-Fähigkeiten."),
                    actionTitle: localizedYouText(model.appLanguage, en: "Rescan", zh: "重新扫描", fr: "Réanalyser", de: "Neu scannen"),
                    actionSymbol: "arrow.clockwise"
                ) {
                    Task { await model.scanLocalAgentsForHerd() }
                }

                NativePanel {
                    VStack(alignment: .leading, spacing: 0) {
                        HerdEngineShelf(
                            runtimes: model.snapshot.localAgentRuntimes,
                            babyItems: babyItems,
                            selectedKind: $selectedKind,
                            selectedID: $selectedID,
                            showingCreate: $showingCreate
                        )
                        .padding(14)

                        Divider()

                        HStack(alignment: .top, spacing: 0) {
                            HerdRosterPane(
                                motherItems: motherItems,
                                babyItems: babyItems,
                                candidates: discoveredCandidates,
                                selectedKind: $selectedKind,
                                selectedID: $selectedID
                            )
                            .frame(width: 350)

                            Divider()

                            HerdDetailPane(
                                selectedKind: selectedKind,
                                selectedID: selectedID,
                                motherItems: motherItems,
                                babyItems: babyItems,
                                candidates: discoveredCandidates,
                                detailHeight: panelHeight,
                                showingCreate: $showingCreate
                            )
                            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                        }
                        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
                    }
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
                }
                .frame(maxWidth: .infinity, minHeight: panelHeight, maxHeight: panelHeight, alignment: .top)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        }
        .sheet(isPresented: $showingCreate) {
            HerdAgentEditorSheet(isPresented: $showingCreate, item: nil)
                .environmentObject(model)
        }
        .onAppear {
            if selectedID.isEmpty {
                if let mother = motherItems.first {
                    selectedKind = "mother"
                    selectedID = mother.id
                } else if let baby = babyItems.first {
                    selectedKind = "baby"
                    selectedID = baby.id
                } else if let candidate = discoveredCandidates.first {
                    selectedKind = "candidate"
                    selectedID = candidate.runtimeID
                }
            }
        }
    }
}

struct HerdEngineShelf: View {
    @EnvironmentObject private var model: ElephantAppModel
    var runtimes: [LocalAgentRuntimeItem]
    var babyItems: [HerdItem]
    @Binding var selectedKind: String
    @Binding var selectedID: String
    @Binding var showingCreate: Bool

    var body: some View {
        HStack(alignment: .center, spacing: 12) {
            VStack(alignment: .leading, spacing: 3) {
                Text(localizedYouText(model.appLanguage, en: "Engines", zh: "引擎", fr: "Moteurs", de: "Antriebe"))
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(localizedYouText(model.appLanguage, en: "Provider and local CLI runtimes. Agents bind to one of these engines.", zh: "模型服务与本地 CLI 运行时；小象会绑定其中一个引擎。", fr: "Fournisseurs et runtimes CLI locaux. Les agents se rattachent à l'un de ces moteurs.", de: "Modellanbieter und lokale CLI-Laufzeiten. Agents werden an einen davon gebunden."))
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
            }
            .frame(width: 240, alignment: .leading)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    ForEach(engineItems) { runtime in
                        HerdEngineChip(
                            runtime: runtime,
                            selected: isSelected(runtime)
                        ) {
                            select(runtime)
                        }
                    }
                    if engineItems.isEmpty {
                        EmptyLine(symbol: "cpu", text: localizedYouText(model.appLanguage, en: "No provider or local CLI engines found yet.", zh: "还没有发现模型服务或本地 CLI 引擎。", fr: "Aucun fournisseur ni moteur CLI local.", de: "Noch keine Modellanbieter oder lokalen CLI-Laufzeiten gefunden."))
                            .frame(height: 46)
                    }
                }
            }

            Button {
                showingCreate = true
            } label: {
                Label(localizedYouText(model.appLanguage, en: "Create Agent", zh: "创建小象", fr: "Créer agent", de: "Agent erstellen"), systemImage: "plus")
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(Color.white)
                    .padding(.horizontal, 13)
                    .frame(height: 34)
                    .background(ElephantTheme.accent, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                    .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
            }
            .buttonStyle(PressablePlainButtonStyle())
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private var engineItems: [HerdEngineDisplayItem] {
        var rows: [HerdEngineDisplayItem] = []
        if let provider = activeProviderEngine {
            rows.append(provider)
        }
        for runtime in runtimes.sorted(by: runtimeSort) {
            let bound = babyItems.first { baby in
                baby.runtimeID == runtime.runtimeID
                    || (!runtime.providerID.isEmpty && baby.providerID == runtime.providerID && !baby.runtimeID.isEmpty)
            }
            rows.append(
                HerdEngineDisplayItem(
                    id: "local:\(runtime.runtimeID)",
                    providerID: runtime.providerID,
                    title: runtime.displayName,
                    subtitle: [runtime.providerID, runtime.defaultModel.isEmpty ? runtime.command : runtime.defaultModel]
                        .filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }
                        .joined(separator: " · "),
                    badge: bound == nil
                        ? localizedYouText(model.appLanguage, en: "ready", zh: "可用", fr: "prêt", de: "bereit")
                        : localizedYouText(model.appLanguage, en: "bound", zh: "已绑定", fr: "lié", de: "gebunden"),
                    ready: runtime.canExecute,
                    targetKind: bound == nil ? "candidate" : "baby",
                    targetID: bound?.id ?? runtime.runtimeID
                )
            )
        }
        return rows
    }

    private var activeProviderEngine: HerdEngineDisplayItem? {
        let providerID = model.snapshot.providerID.trimmingCharacters(in: .whitespacesAndNewlines)
        let modelID = model.snapshot.providerModelID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !providerID.isEmpty || !modelID.isEmpty else { return nil }
        let option = model.snapshot.providerOptions.first { $0.id == providerID }
            ?? model.snapshot.providerOptions.first { $0.active }
        let displayName = option?.displayName ?? (providerID.isEmpty ? localizedYouText(model.appLanguage, en: "Provider", zh: "模型服务", fr: "Fournisseur", de: "Anbieter") : providerID)
        let bound = babyItems.first { baby in
            let babyProvider = baby.providerID.trimmingCharacters(in: .whitespacesAndNewlines)
            let babyModel = baby.providerModel.trimmingCharacters(in: .whitespacesAndNewlines)
            return babyProvider == providerID && (modelID.isEmpty || babyModel.isEmpty || babyModel == modelID)
        }
        return HerdEngineDisplayItem(
            id: "provider:\(providerID):\(modelID)",
            providerID: providerID,
            title: displayName,
            subtitle: [providerID, modelID].filter { !$0.isEmpty }.joined(separator: " · "),
            badge: bound == nil
                ? localizedYouText(model.appLanguage, en: "active", zh: "当前", fr: "actif", de: "aktiv")
                : localizedYouText(model.appLanguage, en: "bound", zh: "已绑定", fr: "lié", de: "gebunden"),
            ready: model.snapshot.providerReady || option?.connected == true || option?.active == true,
            targetKind: bound == nil ? "provider" : "baby",
            targetID: bound?.id ?? providerID
        )
    }

    private func runtimeSort(_ lhs: LocalAgentRuntimeItem, _ rhs: LocalAgentRuntimeItem) -> Bool {
        let leftBound = babyItems.contains { $0.runtimeID == lhs.runtimeID }
        let rightBound = babyItems.contains { $0.runtimeID == rhs.runtimeID }
        if leftBound != rightBound { return leftBound && !rightBound }
        if lhs.canExecute != rhs.canExecute { return lhs.canExecute && !rhs.canExecute }
        return lhs.displayName.localizedCaseInsensitiveCompare(rhs.displayName) == .orderedAscending
    }

    private func isSelected(_ engine: HerdEngineDisplayItem) -> Bool {
        selectedKind == engine.targetKind && selectedID == engine.targetID
    }

    private func select(_ engine: HerdEngineDisplayItem) {
        if engine.targetKind == "provider" {
            showingCreate = true
            return
        }
        selectedKind = engine.targetKind
        selectedID = engine.targetID
    }
}

private struct HerdEngineDisplayItem: Identifiable {
    var id: String
    var providerID: String
    var title: String
    var subtitle: String
    var badge: String
