                    )
                    HerdEditTextField(
                        label: localizedYouText(model.appLanguage, en: "Role", zh: "角色", fr: "Rôle", de: "Rolle"),
                        placeholder: localizedYouText(model.appLanguage, en: "research baby elephant", zh: "研究小象", fr: "baby recherche", de: "Research Baby"),
