                MetricTile(label: localizedYouText(model.appLanguage, en: "Prompt", zh: "输入", fr: "Entrée", de: "Eingabe"), value: abbreviatedCount(model.snapshot.usagePromptTokens), symbol: "arrow.down.doc", tint: ElephantTheme.accent)
