struct LearningJobSection: View {
    var title: String
    var items: [LearningJobItem]

    var body: some View {
        if !items.isEmpty {
            VStack(alignment: .leading, spacing: 6) {
                Text(title)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.muted)
                    .textCase(.uppercase)
                ForEach(items) { item in
                    LearningJobRow(item: item)
                    if item.id != items.last?.id {
                        Divider()
                    }
                }
            }
        }
    }
}

struct LearningJobRow: View {
    @EnvironmentObject private var model: ElephantAppModel
    var item: LearningJobItem

    var body: some View {
        DisclosureGroup {
            VStack(alignment: .leading, spacing: 10) {
                LearningJobRuntimeStrip(item: item)
                if !detailMarkdown.isEmpty {
                    MarkdownBody(
                        text: detailMarkdown,
                        font: .caption,
                        color: ElephantTheme.ink.opacity(0.92),
                        blockSpacing: 7,
                        lineSpacing: 3
                    )
                    .frame(maxWidth: .infinity, alignment: .leading)
                }
                if !supplementalProgressDetail.isEmpty {
                    if progressLooksLikeMarkdown(supplementalProgressDetail) {
                        MarkdownBody(
                            text: supplementalProgressDetail,
                            font: .caption2,
                            color: ElephantTheme.muted,
                            blockSpacing: 6,
                            lineSpacing: 2.5
                        )
                        .frame(maxWidth: .infinity, alignment: .leading)
                    } else {
                        Text(supplementalProgressDetail)
                            .font(.caption2)
                            .foregroundStyle(ElephantTheme.muted)
                            .fixedSize(horizontal: false, vertical: true)
                            .textSelection(.enabled)
                    }
                }
            }
            .padding(.top, 6)
        } label: {
            HStack(alignment: .top, spacing: 12) {
                StatusDot(tint: statusTint)
                    .padding(.top, 6)
                VStack(alignment: .leading, spacing: 3) {
                    Text(displayTitle)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                    Text(subtitleText)
                        .font(.caption)
                        .foregroundStyle(ElephantTheme.muted)
                        .lineLimit(2)
                }
                Spacer()
                Pill(text: localizedRuntimeStatus(item.status, language: model.appLanguage), tint: statusTint)
            }
        }
        .padding(.vertical, 7)
    }

    private var displayTitle: String {
        let raw = item.title.trimmingCharacters(in: .whitespacesAndNewlines)
        let value = raw.lowercased()
        if normalizedFeatures.contains("onboarding_letter") || (value.contains("onboarding") && value.contains("letter")) {
            return onboardingLetterTitle(model.appLanguage)
        }
        if normalizedFeatures.contains("path_planning") || value.contains("onboarding_paths") || value.contains("paths_learn") {
            return localizedYouText(model.appLanguage, en: "First Paths", zh: "第一批路径", fr: "Premiers parcours", de: "Erste Pfade")
        }
        if normalizedFeatures.contains("skill_evolution") {
            return localizedYouText(model.appLanguage, en: "Skill Evolution", zh: "技能进化", fr: "Évolution des compétences", de: "Fähigkeitsentwicklung")
        }
        if normalizedFeatures.contains("dream") || value.contains("nightly") {
            return localizedYouText(model.appLanguage, en: "Dream Review", zh: "综合 Dream", fr: "Revue Dream", de: "Dream-Prüfung")
        }
        if normalizedFeatures == Set(["diary"]) || value.contains("diary") {
            return localizedYouText(model.appLanguage, en: "Diary Reflection", zh: "日记反思", fr: "Réflexion journal", de: "Tagebuchreflexion")
        }
        if normalizedFeatures == Set(["skill_affinity"]) {
            return localizedYouText(model.appLanguage, en: "Skill Matching", zh: "技能匹配", fr: "Affinité compétences", de: "Fähigkeitsabgleich")
        }
        if normalizedFeatures == Set(["questions"]) {
            return localizedYouText(model.appLanguage, en: "Question Review", zh: "问题整理", fr: "Revue questions", de: "Fragenprüfung")
        }
        if normalizedFeatures.intersection(["pm", "questions", "skill_affinity"]).isEmpty == false || value.contains("reflect job") {
            return localizedYouText(model.appLanguage, en: "Memory Review", zh: "记忆整理", fr: "Revue mémoire", de: "Gedächtnisprüfung")
        }
        if normalizedFeatures.contains("compress") {
            return localizedYouText(model.appLanguage, en: "Context Compaction", zh: "上下文压缩", fr: "Compression contexte", de: "Kontextkomprimierung")
        }
        return raw.isEmpty ? localizedYouText(model.appLanguage, en: "Evolution job", zh: "自我进化任务", fr: "Tâche d'évolution", de: "Evolutionsjob") : raw
    }

    private var triggerLabel: String {
        let value = item.trigger.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if value.isEmpty { return "" }
        if value.contains("onboarding_letter") || (value.contains("onboarding") && value.contains("letter")) {
            return localizedLearningToken(value, language: model.appLanguage)
        }
        if value.contains("onboarding_paths") || value.contains("path_planning") || value.contains("paths_learn") {
            return localizedLearningToken(value, language: model.appLanguage)
        }
        if value.contains("night") {
            return localizedYouText(model.appLanguage, en: "nightly", zh: "夜间", fr: "nocturne", de: "nächtlich")
        }
        if value.contains("init") {
            return localizedYouText(model.appLanguage, en: "first setup", zh: "首次设置", fr: "première configuration", de: "Ersteinrichtung")
        }
        if value.contains("dream") {
            return localizedYouText(model.appLanguage, en: "dream", zh: "Dream", fr: "dream", de: "Dream")
        }
        if value.contains("skill_review") {
            return localizedYouText(model.appLanguage, en: "skill review", zh: "技能审核", fr: "revue des compétences", de: "Fähigkeitsprüfung")
        }
        if value.contains("diary") {
            return localizedYouText(model.appLanguage, en: "diary", zh: "日记", fr: "journal", de: "Tagebuch")
        }
        return item.trigger
    }

    private var normalizedFeatures: Set<String> {
        Set(item.resolvedFeatures.map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }.filter { !$0.isEmpty })
    }

    private var statusTint: Color {
        let status = item.status.lowercased()
        if status.contains("completed") { return ElephantTheme.green }
        if status.contains("failed") || status.contains("cancel") { return ElephantTheme.orange }
        return ElephantTheme.accent
    }

    private var formattedDetail: String {
        MacLocalDateTime.formattedRange(item.detail, language: model.appLanguage)
    }

    private var subtitleText: String {
        var seen = Set<String>()
        let parts = [triggerLabel, featureSummary, formattedDetail].compactMap { value -> String? in
            let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
            let key = trimmed.lowercased()
            guard !trimmed.isEmpty, !seen.contains(key) else { return nil }
            seen.insert(key)
            return trimmed
        }
        return parts.joined(separator: " · ")
    }

    private var featureSummary: String {
        item.resolvedFeatures.isEmpty ? "" : item.resolvedFeatures.map(localizedFeatureName).joined(separator: ", ")
    }

    private var detailMarkdown: String {
        let markdown = cleanProgressDetail(item.markdown)
        let progress = cleanProgressDetail(item.progressDetail)
        if progressLooksLikeMarkdown(progress) && progress.count > markdown.count {
            return progress
        }
        if !markdown.isEmpty {
            return markdown
        }
        if progressLooksLikeMarkdown(progress) {
            return progress
        }
        return cleanProgressDetail(progress)
    }

    private var supplementalProgressDetail: String {
        guard !sanitizedLearningDetail(item.markdown).trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return "" }
        let progress = sanitizedLearningDetail(item.progressDetail).trimmingCharacters(in: .whitespacesAndNewlines)
        guard !progress.isEmpty else { return "" }
        if normalizedDetail(progress) == normalizedDetail(sanitizedLearningDetail(item.markdown)) {
            return ""
        }
        if normalizedDetail(progress) == normalizedDetail(detailMarkdown) {
            return ""
        }
        if progressLooksLikeMarkdown(progress) {
            return progress
        }
        let cleaned = cleanProgressDetail(progress)
        if normalizedDetail(cleaned) == normalizedDetail(item.markdown) {
            return ""
        }
        if normalizedDetail(cleaned) == normalizedDetail(detailMarkdown) {
            return ""
        }
        return cleaned
    }

    private func localizedFeatureName(_ feature: String) -> String {
        localizedLearningToken(feature, language: model.appLanguage)
    }

    private func cleanProgressDetail(_ detail: String) -> String {
        sanitizedLearningDetail(detail)
            .replacingOccurrences(of: "tool_diary_list", with: localizedYouText(model.appLanguage, en: "read diary", zh: "读取日记", fr: "lecture journal", de: "Tagebuch lesen"))
            .replacingOccurrences(of: "tool_personal_model_search", with: localizedYouText(model.appLanguage, en: "search Personal Model", zh: "检索个人模型", fr: "recherche du modèle personnel", de: "persönliches Modell durchsuchen"))
            .replacingOccurrences(of: "tool_diary_write", with: localizedYouText(model.appLanguage, en: "write diary", zh: "写入日记", fr: "écriture journal", de: "Tagebuch schreiben"))
            .replacingOccurrences(of: "(result=)", with: "")
            .replacingOccurrences(of: "tool.", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .replacingOccurrences(of: "completed:", with: "")
            .replacingOccurrences(of: "completed：", with: "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func sanitizedLearningDetail(_ detail: String) -> String {
        detail
            .replacingOccurrences(of: #"(?s)<think>.*?</think>"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"(?s)<think>.*"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"</think>"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"(?im)^\s*completed:\s*"#, with: "", options: .regularExpression)
            .replacingOccurrences(of: #"(?im)^\s*completed：\s*"#, with: "", options: .regularExpression)
    }

    private func progressLooksLikeMarkdown(_ detail: String) -> Bool {
        detail.contains("\n")
            || detail.hasPrefix("#")
            || detail.hasPrefix("|")
            || detail.hasPrefix(">")
            || detail.contains("**")
            || detail.contains("```")
    }

    private func normalizedDetail(_ detail: String) -> String {
        detail
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .replacingOccurrences(of: "\r\n", with: "\n")
            .replacingOccurrences(of: "\r", with: "\n")
    }
}

private struct LearningJobRuntimeStrip: View {
    @EnvironmentObject private var model: ElephantAppModel
    var item: LearningJobItem

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 8) {
                    RuntimeChip(
                        text: stageLabel,
                        symbol: "waveform.path.ecg",
                        tint: statusTint
                    )
                    ForEach(item.resolvedFeatures, id: \.self) { feature in
                        RuntimeChip(
                            text: localizedLearningToken(feature, language: model.appLanguage),
                            symbol: "tag.fill",
                            tint: ElephantTheme.accent
                        )
                    }
                }
                .frame(maxWidth: .infinity, alignment: .leading)
            }
            if item.resolvedFeatures.isEmpty {
                RuntimeChip(
                    text: localizedYouText(model.appLanguage, en: "features pending", zh: "等待 feature", fr: "features en attente", de: "Features ausstehend"),
                    symbol: "tag",
                    tint: ElephantTheme.muted
                )
            }
            if !item.resolvedTools.isEmpty {
                Text(toolSummary)
                    .font(.caption2.monospaced())
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(2)
                    .textSelection(.enabled)
            }
        }
        .padding(10)
        .background(ElephantTheme.canvas.opacity(0.66), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line.opacity(0.66), lineWidth: 1))
    }

    private var toolSummary: String {
        let visible = item.resolvedTools.prefix(6).map {
            localizedLearningToolName($0)
        }
        let suffix = item.resolvedTools.count > visible.count ? " +\(item.resolvedTools.count - visible.count)" : ""
        return "\(localizedYouText(model.appLanguage, en: "Tools", zh: "工具", fr: "Outils", de: "Werkzeuge")): \(visible.joined(separator: ", "))\(suffix)"
    }

    private var stageLabel: String {
        let stage = item.progressStage.trimmingCharacters(in: .whitespacesAndNewlines)
        if stage.isEmpty {
            return localizedRuntimeStatus(item.status, language: model.appLanguage)
        }
        let normalized = stage.lowercased()
        if normalized.contains("complete")
            || normalized.contains("fail")
            || normalized.contains("run")
            || normalized.contains("queue")
            || normalized.contains("pending") {
            return localizedRuntimeStatus(stage, language: model.appLanguage)
        }
        return localizedLearningToken(stage, language: model.appLanguage)
    }

    private func localizedLearningToolName(_ tool: String) -> String {
        let raw = tool.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if raw.contains("diary.list") {
            return localizedYouText(model.appLanguage, en: "read diary", zh: "读取日记", fr: "lecture journal", de: "Tagebuch lesen")
        }
        if raw.contains("diary.write") {
            return localizedYouText(model.appLanguage, en: "write diary", zh: "写入日记", fr: "écriture journal", de: "Tagebuch schreiben")
        }
        if raw.contains("personal_model") || raw.contains("personal model") {
            return localizedYouText(model.appLanguage, en: "personal model", zh: "个人模型", fr: "modèle personnel", de: "persönliches Modell")
        }
        let cleaned = tool
            .replacingOccurrences(of: "tool.", with: "")
            .replacingOccurrences(of: "_", with: " ")
        return localizedLearningToken(cleaned, language: model.appLanguage)
    }

    private var statusTint: Color {
        let status = item.status.lowercased()
        if status.contains("completed") { return ElephantTheme.green }
        if status.contains("failed") || status.contains("cancel") { return ElephantTheme.orange }
        return ElephantTheme.accent
    }
}

