struct SettingsControlStrip: View {
    @EnvironmentObject private var model: ElephantAppModel

    var body: some View {
        HStack(spacing: 12) {
            ZStack {
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .fill(statusTint.opacity(0.12))
                Image(systemName: statusSymbol)
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(statusTint)
            }
            .frame(width: 34, height: 34)

            VStack(alignment: .leading, spacing: 3) {
                Text(model.text(.advancedRuntime))
                    .font(.headline.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(runtimeLine)
                    .font(.callout)
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(1)
                    .truncationMode(.middle)
            }

            Spacer(minLength: 0)

            Button {
                Task { await model.restartCore() }
            } label: {
                Label(model.text(.restartCore), systemImage: "arrow.clockwise")
            }
            .settingsActionButton(.primary)
            .help(model.text(.restartCore))
        }
        .frame(maxWidth: .infinity, minHeight: 46, alignment: .center)
    }

    private var runtimeLine: String {
        if !model.snapshot.apiURL.isEmpty {
            return model.snapshot.apiURL
        }
        return model.corePhase.label
    }

    private var statusSymbol: String {
        switch model.corePhase {
        case .ready:
            return "checkmark.seal.fill"
        case .starting:
            return "arrow.triangle.2.circlepath"
        case .failed:
            return "exclamationmark.triangle.fill"
        case .idle:
            return "power"
        }
    }

    private var statusTint: Color {
        switch model.corePhase {
        case .ready:
            return ElephantTheme.green
        case .starting:
            return ElephantTheme.accent
        case .failed:
            return ElephantTheme.orange
        case .idle:
            return ElephantTheme.faint
        }
    }
}

struct ExpandableSettingsRow<Content: View>: View {
    var symbol: String
    var title: String
    var subtitle: String
    var content: Content
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @Binding private var expanded: Bool
    @State private var hovering = false

    init(
        symbol: String,
        title: String,
        subtitle: String,
        expanded: Binding<Bool>,
        @ViewBuilder content: () -> Content
    ) {
        self.symbol = symbol
        self.title = title
        self.subtitle = subtitle
        self._expanded = expanded
        self.content = content()
    }

    var body: some View {
        VStack(spacing: 0) {
            Button {
                toggleExpanded()
            } label: {
                HStack(spacing: 14) {
                    ZStack {
                        RoundedRectangle(cornerRadius: 8, style: .continuous)
                            .fill(iconBackground)
                        Image(systemName: symbol)
                            .font(.callout.weight(.semibold))
                            .foregroundStyle(iconColor)
                    }
                    .frame(width: 36, height: 36)

                    VStack(alignment: .leading, spacing: 3) {
                        Text(title)
                            .font(.headline.weight(.semibold))
                            .foregroundStyle(ElephantTheme.ink)
                        Text(subtitle)
                            .font(.callout)
                            .foregroundStyle(ElephantTheme.muted)
                            .lineLimit(1)
                            .truncationMode(.middle)
                    }

                    Spacer(minLength: 0)

                    ZStack {
                        RoundedRectangle(cornerRadius: 8, style: .continuous)
                            .fill(expanded ? ElephantTheme.accent.opacity(0.14) : hovering ? ElephantTheme.accent.opacity(0.08) : Color(nsColor: .controlBackgroundColor).opacity(0.42))
                        Image(systemName: "chevron.down")
                            .font(.callout.weight(.semibold))
                            .foregroundStyle(expanded || hovering ? ElephantTheme.accent : ElephantTheme.faint)
                            .rotationEffect(.degrees(expanded ? 0 : -90))
                    }
                    .frame(width: 32, height: 32)
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 11)
                .frame(maxWidth: .infinity, minHeight: 64, alignment: .leading)
                .background(rowBackground, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(rowBorder, lineWidth: expanded ? 1.2 : 1)
                )
                .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
            }
            .buttonStyle(PressablePlainButtonStyle())
            .onHover { hovering = $0 }
            .help("\(title): \(subtitle)")
            .accessibilityLabel("\(title), \(subtitle)")

            if expanded {
                VStack(alignment: .leading, spacing: 0) {
                    content
                        .padding(16)
                        .frame(maxWidth: .infinity, alignment: .topLeading)
                }
                .background(
                    Color(nsColor: .controlBackgroundColor).opacity(0.54),
                    in: RoundedRectangle(cornerRadius: 8, style: .continuous)
                )
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(ElephantTheme.line.opacity(0.56), lineWidth: 1)
                )
                .padding(.horizontal, 12)
                .padding(.bottom, 12)
                .transition(.asymmetric(
                    insertion: .opacity.combined(with: .move(edge: .top)),
                    removal: .opacity
                ))
            }
        }
        .animation(.easeOut(duration: 0.14), value: hovering)
    }

    private func toggleExpanded() {
        if reduceMotion {
            expanded.toggle()
        } else {
            withAnimation(settingsDisclosureAnimation) {
                expanded.toggle()
            }
        }
    }

    private var settingsDisclosureAnimation: Animation? {
        reduceMotion ? nil : .easeInOut(duration: 0.16)
    }

    private var iconColor: Color {
        if expanded || hovering { return ElephantTheme.accent }
        return ElephantTheme.muted
    }

    private var iconBackground: Color {
        if expanded { return ElephantTheme.accent.opacity(0.10) }
        if hovering { return ElephantTheme.accent.opacity(0.08) }
        return ElephantTheme.faint.opacity(0.10)
    }

    private var rowBackground: Color {
        if expanded { return ElephantTheme.accent.opacity(0.055) }
        if hovering { return Color(nsColor: .controlBackgroundColor).opacity(0.64) }
        return Color(nsColor: .controlBackgroundColor).opacity(0.34)
    }

    private var rowBorder: Color {
        if expanded { return ElephantTheme.accent.opacity(0.28) }
        if hovering { return ElephantTheme.line.opacity(0.74) }
        return ElephantTheme.line.opacity(0.28)
    }
}

enum SettingsActionKind {
    case primary
    case secondary
    case destructive
}

struct SettingsActionBar<Leading: View, Actions: View>: View {
    var leading: Leading
    var actions: Actions

    init(@ViewBuilder actions: () -> Actions) where Leading == EmptyView {
        self.leading = EmptyView()
        self.actions = actions()
    }

    init(@ViewBuilder leading: () -> Leading, @ViewBuilder actions: () -> Actions) {
        self.leading = leading()
        self.actions = actions()
    }

    var body: some View {
        HStack(alignment: .center, spacing: 10) {
            leading
            Spacer(minLength: 16)
            actions
        }
        .frame(maxWidth: .infinity, minHeight: 38, alignment: .trailing)
        .padding(.top, 10)
    }
}

private struct SettingsActionButtonModifier: ViewModifier {
    var kind: SettingsActionKind

    @ViewBuilder
    func body(content: Content) -> some View {
        content
            .font(.callout.weight(kind == .primary ? .semibold : .medium))
            .labelStyle(.titleAndIcon)
            .buttonStyle(PressablePlainButtonStyle())
            .foregroundStyle(foreground)
            .padding(.horizontal, 12)
            .frame(minWidth: kind == .secondary ? 86 : 104, minHeight: 34)
            .background(fill, in: RoundedRectangle(cornerRadius: 7, style: .continuous))
            .overlay(
                RoundedRectangle(cornerRadius: 7, style: .continuous)
                    .stroke(stroke, lineWidth: 1)
            )
            .contentShape(RoundedRectangle(cornerRadius: 7, style: .continuous))
    }

    private var foreground: Color {
        switch kind {
        case .primary:
            return Color.white
        case .secondary:
            return ElephantTheme.ink.opacity(0.88)
        case .destructive:
            return ElephantTheme.orange
        }
    }

    private var fill: Color {
        switch kind {
        case .primary:
            return ElephantTheme.accent
        case .secondary:
            return Color(nsColor: .controlBackgroundColor).opacity(0.72)
        case .destructive:
            return ElephantTheme.orange.opacity(0.08)
        }
    }

    private var stroke: Color {
        switch kind {
        case .primary:
            return ElephantTheme.accent.opacity(0.80)
        case .secondary:
            return ElephantTheme.line.opacity(0.78)
        case .destructive:
            return ElephantTheme.orange.opacity(0.30)
        }
    }
}

extension View {
    func settingsActionButton(_ kind: SettingsActionKind = .secondary) -> some View {
        modifier(SettingsActionButtonModifier(kind: kind))
    }
}

