private struct CachedRemoteLogoImage<Placeholder: View>: View {
    var url: URL
    var padding: CGFloat
    var placeholder: Placeholder
    @State private var image: NSImage?

    init(url: URL, padding: CGFloat, @ViewBuilder placeholder: () -> Placeholder) {
        self.url = url
        self.padding = padding
        self.placeholder = placeholder()
    }

    var body: some View {
        Group {
            if let image {
                Image(nsImage: image)
                    .resizable()
                    .scaledToFit()
                    .padding(padding)
            } else {
                placeholder
            }
        }
        .task(id: url.absoluteString) {
            image = nil
            image = await RemoteLogoCache.shared.image(for: url)
        }
    }
}

@MainActor
private final class RemoteLogoCache {
    static let shared = RemoteLogoCache()

    private var memory: [String: NSImage] = [:]
    private var inflight: [String: Task<Data?, Never>] = [:]
    private let fileManager = FileManager.default
    private lazy var directory: URL = {
        let base = fileManager.urls(for: .cachesDirectory, in: .userDomainMask).first
            ?? URL(fileURLWithPath: NSTemporaryDirectory(), isDirectory: true)
        return base.appendingPathComponent("ElephantAgent/RemoteLogos", isDirectory: true)
    }()

    func preload(_ urls: [URL]) async {
        for url in Array(Set(urls.map(\.absoluteString))).compactMap({ URL(string: $0) }).prefix(80) {
            _ = await image(for: url)
        }
    }

    func image(for url: URL) async -> NSImage? {
        let key = url.absoluteString
        if let image = memory[key] {
            return image
        }
        if let image = imageFromDisk(for: key) {
            memory[key] = image
            return image
        }
        let data: Data?
        if let task = inflight[key] {
            data = await task.value
        } else {
            let task = Task.detached(priority: .utility) { () -> Data? in
                var request = URLRequest(url: url)
                request.cachePolicy = .returnCacheDataElseLoad
                request.timeoutInterval = 12
                do {
                    let (data, response) = try await URLSession.shared.data(for: request)
                    if let status = (response as? HTTPURLResponse)?.statusCode, !(200...299).contains(status) {
                        return nil
                    }
                    return data
                } catch {
                    return nil
                }
            }
            inflight[key] = task
            data = await task.value
            inflight[key] = nil
        }
        guard let data, let image = NSImage(data: data) else {
            return nil
        }
        memory[key] = image
        write(data, for: key)
        return image
    }

    private func imageFromDisk(for key: String) -> NSImage? {
        let fileURL = cacheFileURL(for: key)
        guard fileManager.fileExists(atPath: fileURL.path),
              let image = NSImage(contentsOf: fileURL) else {
            return nil
        }
        return image
    }

    private func write(_ data: Data, for key: String) {
        do {
            try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
            try data.write(to: cacheFileURL(for: key), options: [.atomic])
        } catch {
            return
        }
    }

    private func cacheFileURL(for key: String) -> URL {
        let encoded = Data(key.utf8)
            .base64EncodedString()
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "=", with: "")
        return directory.appendingPathComponent(String(encoded.prefix(160))).appendingPathExtension("png")
    }
}

struct ModelOptionPicker: View {
    @EnvironmentObject private var model: ElephantAppModel
    var options: [ProviderModelOption]
    @Binding var selectedID: String
    var loading: Bool
    var activeModelID: String

    var body: some View {
        if options.isEmpty {
            EmptyLine(
                symbol: loading ? "arrow.clockwise" : "sparkles",
                text: loading
                    ? localizedYouText(model.appLanguage, en: "Fetching models from the provider...", zh: "正在从模型服务拉取列表...", fr: "Chargement des modèles depuis le fournisseur...", de: "Modelle werden vom Anbieter geladen...")
                    : localizedYouText(model.appLanguage, en: "No model list yet. Use Fetch models or type a custom model ID.", zh: "还没有模型列表。可以刷新模型列表，或手动填写模型 ID。", fr: "Aucune liste de modèles. Chargez les modèles ou saisissez un ID personnalisé.", de: "Noch keine Modellliste. Modelle laden oder eigene Modell-ID eingeben.")
            )
        } else {
            LazyVGrid(columns: columns, spacing: 8) {
                ForEach(options.prefix(12)) { option in
                    Button {
                        selectedID = option.id
                    } label: {
                        ModelOptionCard(
                            option: option,
                            selected: selectedID == option.id,
                            active: activeModelID == option.id
                        )
                    }
                    .buttonStyle(PressablePlainButtonStyle())
                }
            }
        }
    }

    private var columns: [GridItem] {
        [
            GridItem(.adaptive(minimum: 220, maximum: 320), spacing: 8, alignment: .topLeading)
        ]
    }
}

struct ModelOptionCard: View {
    @EnvironmentObject private var model: ElephantAppModel
    var option: ProviderModelOption
    var selected: Bool
    var active: Bool

    var body: some View {
        HStack(spacing: 10) {
            Image(systemName: selected ? "checkmark.circle.fill" : active ? "bolt.horizontal.circle.fill" : "sparkles")
                .font(.system(size: 15, weight: .semibold))
                .foregroundStyle(active ? ElephantTheme.green : selected ? ElephantTheme.accent : ElephantTheme.muted)
                .frame(width: 20)
            VStack(alignment: .leading, spacing: 4) {
                Text(option.label)
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                    .lineLimit(1)
                    .truncationMode(.middle)
                HStack(spacing: 6) {
                    Text(option.source)
                    if option.contextWindowTokens > 0 {
                        Text(localizedFormat(model.appLanguage, en: "context %@", zh: "上下文 %@", fr: "contexte %@", de: "Kontext %@", formattedTokenWindow(option.contextWindowTokens)))
                    }
                    if active {
                        Text(localizedProviderState("active", language: model.appLanguage))
                    }
                }
                .font(.caption.weight(.semibold))
                .foregroundStyle(active ? ElephantTheme.green : ElephantTheme.muted)
                .lineLimit(1)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 11)
        .padding(.vertical, 10)
        .frame(maxWidth: .infinity, minHeight: 58, alignment: .leading)
        .background(cardBackground, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(
            RoundedRectangle(cornerRadius: 8, style: .continuous)
                .stroke(cardBorder, lineWidth: active || selected ? 1.4 : 1)
        )
    }

    private var cardBackground: Color {
        if active { return ElephantTheme.green.opacity(0.10) }
        if selected { return ElephantTheme.accent.opacity(0.10) }
        return Color(nsColor: .textBackgroundColor).opacity(0.76)
    }

    private var cardBorder: Color {
        if active { return ElephantTheme.green.opacity(0.68) }
        if selected { return ElephantTheme.accent.opacity(0.48) }
        return ElephantTheme.line
    }
}

