            localizedFormat(model.appLanguage, en: "%d args", zh: "%d 个参数", fr: "%d arguments", de: "%d Argumente", server.args.count),
            localizedFormat(model.appLanguage, en: "%d env", zh: "%d 个环境变量", fr: "%d variables d'environnement", de: "%d Umgebungsvariablen", server.envKeys.count),
            localizedFormat(model.appLanguage, en: "%d headers", zh: "%d 个请求头", fr: "%d en-têtes", de: "%d Header", server.headerKeys.count)
        ]
        .joined(separator: " · ")
    }
}

private struct MCPToolToggleRow: View {
    @EnvironmentObject private var model: ElephantAppModel
    var tool: MCPToolItem

    var body: some View {
        HStack(alignment: .top, spacing: 11) {
            Image(systemName: "wrench.and.screwdriver")
                .font(.callout.weight(.semibold))
                .foregroundStyle(statusTint)
                .frame(width: 32, height: 32)
                .background(statusTint.opacity(0.10), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(statusTint.opacity(0.20), lineWidth: 1)
                )
            VStack(alignment: .leading, spacing: 4) {
                HStack(spacing: 7) {
                    Text(tool.displayName)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                    Text(tool.toolName)
                        .font(.caption2.weight(.semibold))
                        .foregroundStyle(ElephantTheme.faint)
                        .lineLimit(1)
                }
                Text(descriptionText)
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(3)
                HStack(spacing: 6) {
                    Pill(text: statusText, symbol: statusSymbol, tint: statusTint)
                    if !tool.requiredFields.isEmpty {
                        Pill(text: "\(localizedYouText(model.appLanguage, en: "required", zh: "必填", fr: "obligatoire", de: "erforderlich")) · \(tool.requiredFields.joined(separator: ", "))", symbol: "text.badge.checkmark", tint: ElephantTheme.faint)
                    }
                    if !tool.availabilityReason.isEmpty, !tool.available {
                        Pill(text: tool.availabilityReason, symbol: "exclamationmark.triangle", tint: ElephantTheme.orange)
                    }
                }
            }
            Spacer(minLength: 10)
            Toggle("", isOn: Binding(
                get: { tool.enabled },
                set: { enabled in Task { await model.setMCPToolEnabled(tool, enabled: enabled) } }
            ))
            .labelsHidden()
            .toggleStyle(.switch)
            .tint(ElephantTheme.green)
            .disabled(model.mcpActionInFlight)
            .help(toggleHelp)
        }
        .padding(.horizontal, 10)
        .padding(.vertical, 9)
    }

    private var descriptionText: String {
        let raw = tool.description.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !raw.isEmpty else {
            return localizedYouText(model.appLanguage, en: "No description returned.", zh: "没有返回工具说明。", fr: "Aucune description.", de: "Keine Beschreibung.")
        }
        let normalized = raw
            .replacingOccurrences(of: "\\\\n", with: "\n")
            .replacingOccurrences(of: "\\n", with: "\n")
            .replacingOccurrences(of: "\\\\t", with: " ")
            .replacingOccurrences(of: "\\t", with: " ")
        return normalized
            .components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: " ")
            .replacingOccurrences(of: "\\s+", with: " ", options: .regularExpression)
    }

    private var statusText: String {
        if !tool.available {
            return localizedYouText(model.appLanguage, en: "Unavailable", zh: "不可用", fr: "Indisponible", de: "Nicht verfügbar")
        }
        if tool.enabled {
            return localizedYouText(model.appLanguage, en: "Enabled", zh: "已启用", fr: "Activé", de: "Aktiv")
        }
        return localizedYouText(model.appLanguage, en: "Disabled", zh: "已停用", fr: "Désactivé", de: "Inaktiv")
    }

    private var statusSymbol: String {
        if !tool.available { return "exclamationmark.triangle.fill" }
        return tool.enabled ? "checkmark.circle.fill" : "pause.circle"
    }

    private var statusTint: Color {
        if !tool.available { return ElephantTheme.orange }
        return tool.enabled ? ElephantTheme.green : ElephantTheme.muted
    }

    private var toggleHelp: String {
        tool.enabled
            ? localizedYouText(model.appLanguage, en: "Disable this tool for Chat", zh: "在 Chat 中停用这个工具", fr: "Désactiver cet outil pour Chat", de: "Dieses Tool für Chat deaktivieren")
            : localizedYouText(model.appLanguage, en: "Enable this tool for Chat", zh: "在 Chat 中启用这个工具", fr: "Activer cet outil pour Chat", de: "Dieses Tool für Chat aktivieren")
    }
}

private enum MCPEditorMode: String, CaseIterable, Identifiable {
    case form
    case json

    var id: String { rawValue }
}

private struct MCPServerEditorSheet: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Binding var isPresented: Bool
    @Binding var draft: MCPServerDraft
    @Binding var rawJSON: String
    @Binding var discovery: MCPDiscoveryResult?
    @Binding var enabledToolNames: Set<String>
    @State private var mode: MCPEditorMode = .form
    @State private var localError = ""

    var body: some View {
        VStack(spacing: 0) {
            HStack(alignment: .center, spacing: 12) {
                OperatorCatalogLogo(symbol: "server.rack", tint: ElephantTheme.green, brandSlug: draft.serverID.lowercased().contains("minimax") ? "minimax" : nil)
                VStack(alignment: .leading, spacing: 3) {
                    Text(draft.serverID.isEmpty ? localizedYouText(model.appLanguage, en: "Add MCP Server", zh: "新增 MCP 服务", fr: "Ajouter un serveur MCP", de: "MCP-Server hinzufügen") : draft.serverID)
                        .font(.headline.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                    Text(targetLabel)
                        .font(.caption)
                        .foregroundStyle(ElephantTheme.muted)
                        .lineLimit(1)
                        .truncationMode(.middle)
                }
                Spacer(minLength: 0)
                Picker("", selection: modeBinding) {
                    Text(localizedYouText(model.appLanguage, en: "Form", zh: "表单", fr: "Formulaire", de: "Formular")).tag(MCPEditorMode.form)
                    Text("JSON").tag(MCPEditorMode.json)
                }
                .pickerStyle(.segmented)
                .frame(width: 164)
            }
            .padding(.horizontal, 20)
            .padding(.vertical, 16)

            Divider()

            HStack(alignment: .top, spacing: 14) {
                VStack(alignment: .leading, spacing: 12) {
                    if mode == .form {
                        MCPServerForm(draft: $draft)
                    } else {
                        VStack(alignment: .leading, spacing: 8) {
                            HStack {
                                Text(localizedYouText(model.appLanguage, en: "MCP JSON", zh: "MCP JSON 配置", fr: "JSON MCP", de: "MCP JSON"))
                                    .font(.caption.weight(.semibold))
                                    .foregroundStyle(ElephantTheme.muted)
                                Spacer(minLength: 0)
                                Button {
                                    loadJSONIntoForm()
                                } label: {
                                    Label(localizedYouText(model.appLanguage, en: "Convert", zh: "转换", fr: "Convertir", de: "Konvertieren"), systemImage: "arrow.triangle.2.circlepath")
                                }
                                .controlSize(.small)
                            }
                            TextEditor(text: $rawJSON)
                                .font(.system(.callout, design: .monospaced))
                                .scrollContentBackground(.hidden)
                                .padding(10)
                                .frame(minHeight: 330)
                                .background(Color(nsColor: .controlBackgroundColor), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                                .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
                        }
                    }

                    if !localError.isEmpty {
                        Label(localError, systemImage: "exclamationmark.triangle.fill")
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(ElephantTheme.orange)
                            .fixedSize(horizontal: false, vertical: true)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .topLeading)

                MCPDiscoveryPreview(
                    discovery: discovery,
                    enabledToolNames: $enabledToolNames
                )
                .frame(width: 295, alignment: .topLeading)
            }
            .padding(20)

            Divider()
            HStack(spacing: 10) {
                Spacer(minLength: 0)
                Button(localizedYouText(model.appLanguage, en: "Cancel", zh: "取消", fr: "Annuler", de: "Abbrechen")) {
                    isPresented = false
                }
                .settingsActionButton()
                Button {
                    Task { await test() }
                } label: {
                    Label(localizedYouText(model.appLanguage, en: "Test", zh: "测试", fr: "Tester", de: "Testen"), systemImage: "checkmark.seal")
                }
                .settingsActionButton()
                Button {
                    Task { await save() }
                } label: {
                    Label(localizedYouText(model.appLanguage, en: "Save & Sync", zh: "保存并同步", fr: "Enregistrer et sync", de: "Speichern & sync"), systemImage: "square.and.arrow.down")
                }
                .settingsActionButton(.primary)
            }
            .disabled(model.mcpActionInFlight)
            .padding(.horizontal, 20)
            .padding(.vertical, 14)
        }
        .frame(width: 820)
        .background(Color(nsColor: .windowBackgroundColor))
        .onChange(of: draft) { next in
            if mode == .form {
                rawJSON = next.jsonText()
            }
        }
        .onChange(of: rawJSON) { next in
            autoConvertJSONIfPossible(next)
        }
    }

    private var targetLabel: String {
        let target = draft.transport == "stdio" || draft.transport.isEmpty ? draft.command : draft.url
        if target.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return draft.transport.isEmpty ? "stdio" : draft.transport
        }
        return target
    }

    private var modeBinding: Binding<MCPEditorMode> {
        Binding(
            get: { mode },
            set: { nextMode in
                if nextMode == .form, mode == .json {
                    loadJSONIntoForm()
                } else {
                    if nextMode == .json {
                        rawJSON = draft.jsonText()
                        localError = ""
                    }
                    mode = nextMode
                }
            }
        )
    }

    private func loadJSONIntoForm() {
        do {
            draft = try MCPServerDraft.from(jsonText: rawJSON)
            rawJSON = draft.jsonText()
            localError = ""
            mode = .form
        } catch {
            localError = error.localizedDescription
            mode = .json
        }
    }

    private func autoConvertJSONIfPossible(_ text: String) {
        guard mode == .json else { return }
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard trimmed.first == "{" else { return }
        guard let nextDraft = try? MCPServerDraft.from(jsonText: text) else { return }
        mode = .form
        draft = nextDraft
        rawJSON = nextDraft.jsonText()
        discovery = nil
        enabledToolNames = []
        localError = ""
    }

    private func effectiveDraft() throws -> MCPServerDraft {
        if mode == .json {
            return try MCPServerDraft.from(jsonText: rawJSON)
        }
        return draft
    }

    private func test() async {
        do {
            let nextDraft = try effectiveDraft()
            if mode == .json { draft = nextDraft }
            guard let result = await model.discoverMCPServer(draft: nextDraft) else { return }
            discovery = result
            enabledToolNames = Set(result.tools.filter(\.enabled).map(\.name))
            localError = ""
        } catch {
            localError = error.localizedDescription
        }
    }

    private func save() async {
        do {
            let nextDraft = try effectiveDraft()
            if mode == .json { draft = nextDraft }
            var result = discovery
            if result?.ok != true {
                result = await model.discoverMCPServer(draft: nextDraft)
                discovery = result
                enabledToolNames = Set(result?.tools.filter(\.enabled).map(\.name) ?? [])
            }
            guard let result, result.ok, !result.tools.isEmpty else {
                localError = localizedYouText(model.appLanguage, en: "Test the MCP server successfully before saving.", zh: "需要先成功测试 MCP 服务再保存。", fr: "Testez le serveur MCP avec succès avant d'enregistrer.", de: "MCP-Server vor dem Speichern erfolgreich testen.")
                return
            }
            let saved = await model.syncMCPServer(
                draft: nextDraft,
                discoveredTools: result.tools,
                enabledToolNames: enabledToolNames
            )
            if saved {
                isPresented = false
            }
        } catch {
            localError = error.localizedDescription
        }
    }
}

