private struct OperatorCatalogRow: View {
    @EnvironmentObject private var model: ElephantAppModel
    var kind: String
    var item: OperationItem
    var onOpen: () -> Void

    var body: some View {
        HStack(alignment: .center, spacing: 12) {
            OperatorCatalogLogo(symbol: logo.symbol, tint: logo.tint, brandSlug: logo.brandSlug)

            VStack(alignment: .leading, spacing: 4) {
                HStack(spacing: 7) {
                    Text(item.title)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                    if !item.id.isEmpty, item.id != item.title {
                        Text(item.id)
                            .font(.caption2.weight(.semibold))
                            .foregroundStyle(ElephantTheme.faint)
                            .lineLimit(1)
                            .truncationMode(.middle)
                    }
                }
                Text(
                    item.detail.isEmpty
                        ? localizedYouText(model.appLanguage, en: "No description returned by the local runtime.", zh: "本地运行时没有提供说明。", fr: "Aucune description retournée par le runtime local.", de: "Keine Beschreibung von der lokalen Runtime.")
                        : item.detail
                )
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(2)
                    .fixedSize(horizontal: false, vertical: true)
            }

            Spacer(minLength: 12)

            HStack(spacing: 8) {
                Pill(
                    text: statusText,
                    symbol: statusSymbol,
                    tint: statusTint
                )
                Button(action: onOpen) {
                    Image(systemName: "info.circle")
                        .font(.system(size: 13, weight: .semibold))
                        .foregroundStyle(isEvolutionDraft ? ElephantTheme.evolution : ElephantTheme.muted)
                        .frame(width: 26, height: 24)
                }
                .buttonStyle(PressablePlainButtonStyle())
                .help(localizedYouText(model.appLanguage, en: "View details", zh: "查看详情", fr: "Voir les détails", de: "Details anzeigen"))
                Button(
                    actionText
                ) {
                    Task { await model.setConsoleItem(kind: kind, id: item.id, enabled: !item.enabled) }
                }
                .controlSize(.small)
                .frame(width: 86)
                .disabled(!item.toggleable)
            }
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 11)
        .contentShape(Rectangle())
        .onTapGesture(perform: onOpen)
    }

    private var logo: OperatorLogoSpec {
        OperatorLogoSpec.forItem(item, kind: kind)
    }

    private var normalizedReviewStatus: String {
        item.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    }

    private var isEvolutionDraft: Bool {
        kind == "skills" && (
            normalizedReviewStatus == "pending"
                || item.sourceKind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased().contains("draft")
        )
    }

    private var statusText: String {
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled {
            return localizedYouText(model.appLanguage, en: "pending", zh: "待审核", fr: "en attente", de: "wartet")
        }
        if item.enabled {
            return localizedYouText(model.appLanguage, en: "enabled", zh: "已启用", fr: "activé", de: "aktiv")
        }
        return localizedYouText(model.appLanguage, en: "available", zh: "可启用", fr: "disponible", de: "verfügbar")
    }

    private var statusSymbol: String {
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled { return "sparkles" }
        return item.enabled ? "checkmark" : "circle"
    }

    private var statusTint: Color {
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled { return ElephantTheme.evolution }
        return item.enabled ? ElephantTheme.green : ElephantTheme.faint
    }

    private var actionText: String {
        if item.enabled {
            return localizedYouText(model.appLanguage, en: "Disable", zh: "停用", fr: "Désactiver", de: "Deaktivieren")
        }
        if kind == "skills", normalizedReviewStatus == "pending" {
            return localizedYouText(model.appLanguage, en: "Approve", zh: "通过", fr: "Approuver", de: "Freigeben")
        }
        return localizedYouText(model.appLanguage, en: "Enable", zh: "启用", fr: "Activer", de: "Aktivieren")
    }
}

private struct OperatorItemDetailSheet: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.dismiss) private var dismiss
    var kind: String
    var item: OperationItem

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            detailHeader

            overviewPanel

            VStack(alignment: .leading, spacing: 10) {
                Text(detailTitle)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.muted)
                    .textCase(.uppercase)
                ScrollView {
                    MarkdownBody(
                        text: bodyText,
                        font: .callout,
                        color: ElephantTheme.ink,
                        blockSpacing: 8
                    )
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .padding(.trailing, 10)
                    .padding(.bottom, 2)
                }
            }
            .frame(maxHeight: .infinity, alignment: .topLeading)

            Divider()

            HStack(spacing: 10) {
                Text(footerText)
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(1)
                    .truncationMode(.tail)
                Spacer(minLength: 12)
                Button(localizedYouText(model.appLanguage, en: "Close", zh: "关闭", fr: "Fermer", de: "Schließen")) {
                    dismiss()
                }
                Button(item.enabled ? localizedYouText(model.appLanguage, en: "Disable", zh: "停用", fr: "Désactiver", de: "Deaktivieren") : approveText) {
                    Task { await model.setConsoleItem(kind: kind, id: item.id, enabled: !item.enabled) }
                }
                .buttonStyle(.borderedProminent)
                .tint(isEvolutionDraft ? ElephantTheme.evolution : ElephantTheme.accent)
                .disabled(!item.toggleable)
            }
        }
        .padding(22)
        .frame(width: 920, height: 640, alignment: .topLeading)
    }

    private var detailHeader: some View {
        HStack(alignment: .center, spacing: 12) {
            OperatorCatalogLogo(symbol: logo.symbol, tint: logo.tint, brandSlug: logo.brandSlug)
            VStack(alignment: .leading, spacing: 5) {
                Text(item.title)
                    .font(.title2.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                    .lineLimit(1)
                    .truncationMode(.tail)
                Text(item.id)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.faint)
                    .lineLimit(1)
                    .truncationMode(.middle)
            }
            Spacer(minLength: 0)
            Pill(text: statusText, symbol: statusSymbol, tint: statusTint)
            Button {
                dismiss()
            } label: {
                Image(systemName: "xmark")
                    .font(.system(size: 12, weight: .bold))
                    .foregroundStyle(ElephantTheme.muted)
                    .frame(width: 28, height: 28)
            }
            .buttonStyle(PressablePlainButtonStyle())
            .help(localizedYouText(model.appLanguage, en: "Close", zh: "关闭", fr: "Fermer", de: "Schließen"))
        }
    }

    @ViewBuilder
    private var overviewPanel: some View {
        if kind == "tools" {
            toolOverviewPanel
        } else {
            skillOverviewPanel
        }
    }

    private var skillOverviewPanel: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                if isEvolutionDraft {
                    Pill(
                        text: localizedYouText(model.appLanguage, en: "Skill Evolution", zh: "技能进化", fr: "Évolution des compétences", de: "Fähigkeitsentwicklung"),
                        symbol: "sparkles",
                        tint: ElephantTheme.evolution
                    )
                }
                Pill(
                    text: promptVisibilityText,
                    symbol: item.promptIndexVisible ? "eye" : "eye.slash",
                    tint: item.promptIndexVisible ? ElephantTheme.green : ElephantTheme.faint
                )
                Pill(
                    text: defaultText,
                    symbol: item.enabled ? "checkmark.seal" : "circle",
                    tint: item.enabled ? ElephantTheme.green : ElephantTheme.faint
                )
            }

            HStack(alignment: .top, spacing: 18) {
                OperatorDetailBlock(
                    label: localizedYouText(model.appLanguage, en: "Summary", zh: "摘要", fr: "Résumé", de: "Zusammenfassung"),
                    value: summaryText,
                    lineLimit: 4
                )
                .frame(maxWidth: .infinity, alignment: .topLeading)

                VStack(alignment: .leading, spacing: 12) {
                    OperatorDetailBlock(
                        label: localizedYouText(model.appLanguage, en: "Source", zh: "来源", fr: "Source", de: "Quelle"),
                        value: sourceText,
                        lineLimit: 2
                    )
                    OperatorDetailBlock(
                        label: localizedYouText(model.appLanguage, en: "Review", zh: "审核", fr: "Revue", de: "Review"),
                        value: reviewText,
                        lineLimit: 1
                    )
                }
                .frame(width: 270, alignment: .topLeading)
            }
        }
        .padding(14)
        .background(Color(nsColor: .controlBackgroundColor).opacity(0.62), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
    }

    private var toolOverviewPanel: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                Pill(text: item.available ? localizedYouText(model.appLanguage, en: "Available", zh: "可用", fr: "Disponible", de: "Verfügbar") : localizedYouText(model.appLanguage, en: "Unavailable", zh: "不可用", fr: "Indisponible", de: "Nicht verfügbar"), symbol: item.available ? "checkmark.circle" : "exclamationmark.triangle", tint: item.available ? ElephantTheme.green : ElephantTheme.orange)
                Pill(text: localizedFormat(model.appLanguage, en: "risk: %@", zh: "风险：%@", fr: "risque : %@", de: "Risiko: %@", normalizedToolRisk), symbol: "shield", tint: toolRiskTint)
                Pill(text: localizedFormat(model.appLanguage, en: "approval: %@", zh: "审批：%@", fr: "approbation : %@", de: "Freigabe: %@", normalizedToolApproval), symbol: "checkmark.seal", tint: ElephantTheme.accent)
                Pill(text: item.defaultEnabled ? localizedYouText(model.appLanguage, en: "Default on", zh: "默认开启", fr: "Activé par défaut", de: "Standard ein") : localizedYouText(model.appLanguage, en: "Default off", zh: "默认关闭", fr: "Désactivé par défaut", de: "Standard aus"), symbol: item.defaultEnabled ? "power.circle.fill" : "power.circle", tint: item.defaultEnabled ? ElephantTheme.green : ElephantTheme.faint)
            }

            HStack(alignment: .top, spacing: 18) {
                OperatorDetailBlock(
                    label: localizedYouText(model.appLanguage, en: "What it does", zh: "用途", fr: "Usage", de: "Zweck"),
                    value: summaryText,
                    lineLimit: 4
                )
                .frame(maxWidth: .infinity, alignment: .topLeading)

                VStack(alignment: .leading, spacing: 12) {
                    OperatorDetailBlock(
                        label: localizedYouText(model.appLanguage, en: "Runtime", zh: "运行时", fr: "Runtime", de: "Runtime"),
                        value: toolRuntimeText,
                        lineLimit: 2
                    )
                    OperatorDetailBlock(
                        label: localizedYouText(model.appLanguage, en: "Required inputs", zh: "必填输入", fr: "Entrées requises", de: "Pflichteingaben"),
                        value: requiredFieldsText,
                        lineLimit: 2
                    )
                }
                .frame(width: 270, alignment: .topLeading)
            }

            if !toolSideEffectLabels.isEmpty {
                HStack(spacing: 8) {
                    ForEach(toolSideEffectLabels, id: \.self) { label in
                        Pill(text: label, symbol: "bolt.horizontal", tint: ElephantTheme.orange)
                    }
                }
            }

            if !item.availabilityReason.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                OperatorDetailBlock(
                    label: localizedYouText(model.appLanguage, en: "Availability note", zh: "可用性说明", fr: "Note de disponibilité", de: "Verfügbarkeit"),
                    value: item.availabilityReason,
                    lineLimit: 2
                )
            }
        }
        .padding(14)
        .background(Color(nsColor: .controlBackgroundColor).opacity(0.62), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
    }

    private var logo: OperatorLogoSpec {
        OperatorLogoSpec.forItem(item, kind: kind)
    }

    private var detailTitle: String {
        if kind == "skills" {
            return localizedYouText(model.appLanguage, en: "Skill instructions", zh: "技能说明", fr: "Instructions de la compétence", de: "Fähigkeitsanweisungen")
        }
        if kind == "tools" {
            return localizedYouText(model.appLanguage, en: "Tool contract", zh: "工具契约", fr: "Contrat outil", de: "Tool-Vertrag")
        }
        return localizedYouText(model.appLanguage, en: "Details", zh: "详情", fr: "Détails", de: "Details")
    }

    private var bodyText: String {
        if kind == "tools" {
            return toolBodyText
        }
        let trimmed = item.instructionText.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty { return trimmed }
        return localizedYouText(
            model.appLanguage,
            en: "No instruction text returned by the local runtime.",
            zh: "本地运行时没有返回说明。",
            fr: "Aucune instruction retournée.",
            de: "Keine Anweisungen zurückgegeben."
        )
    }

    private var summaryText: String {
        let trimmed = item.detail.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty { return trimmed }
        return localizedYouText(
            model.appLanguage,
            en: "No description returned by the local runtime.",
            zh: "本地运行时没有返回摘要。",
            fr: "Aucune description retournée.",
            de: "Keine Beschreibung zurückgegeben."
        )
    }

    private var promptVisibilityText: String {
        item.promptIndexVisible
            ? localizedYouText(model.appLanguage, en: "Prompt visible", zh: "已进入提示索引", fr: "Visible dans le contexte", de: "Im Kontext sichtbar")
            : localizedYouText(model.appLanguage, en: "Not in prompt", zh: "未进入提示索引", fr: "Hors contexte", de: "Nicht im Kontext")
    }

    private var defaultText: String {
        item.enabled
            ? localizedYouText(model.appLanguage, en: "Enabled", zh: "已启用", fr: "Activé", de: "Aktiv")
            : localizedYouText(model.appLanguage, en: "Disabled", zh: "未启用", fr: "Désactivé", de: "Deaktiviert")
    }

    private var reviewText: String {
        if normalizedReviewStatus.isEmpty {
            return localizedYouText(model.appLanguage, en: "n/a", zh: "无", fr: "n/a", de: "n/a")
        }
        return statusText
    }

    private var footerText: String {
        if kind == "tools" {
            return item.toggleable
                ? localizedYouText(model.appLanguage, en: "Enable or disable controls whether this tool is exposed to local agent runs.", zh: "启用或停用会控制本地智能体运行时是否暴露这个工具。", fr: "Activer ou désactiver contrôle l'exposition de cet outil aux agents locaux.", de: "Aktivieren oder Deaktivieren steuert, ob dieses Tool lokalen Agent-Läufen bereitsteht.")
                : localizedYouText(model.appLanguage, en: "This tool is managed by the local runtime.", zh: "这个工具由本地运行时管理。", fr: "Cet outil est géré par le runtime local.", de: "Dieses Tool wird von der lokalen Runtime verwaltet.")
        }
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled {
            return localizedYouText(
                model.appLanguage,
                en: "Approve this skill to make it available for future prompts.",
                zh: "通过后，这个技能才会进入可启用流程并可用于后续提示。",
                fr: "Approuvez cette compétence pour la rendre disponible dans les prochaines consignes.",
                de: "Freigeben, damit diese Fähigkeit für zukünftige Anweisungen verfügbar wird."
            )
        }
        return item.toggleable
            ? localizedYouText(model.appLanguage, en: "Changes apply locally through the runtime.", zh: "更改会通过本地运行时立即生效。", fr: "Les changements s'appliquent via le runtime local.", de: "Änderungen gelten lokal über die Runtime.")
            : localizedYouText(model.appLanguage, en: "This item is managed by the local runtime.", zh: "这个项目由本地运行时管理。", fr: "Cet élément est géré par le runtime local.", de: "Dieses Element wird von der lokalen Runtime verwaltet.")
    }

    private var sourceText: String {
        if kind == "tools" {
            let source = [item.backend, item.family, item.provenance]
                .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
                .filter { !$0.isEmpty }
                .joined(separator: " · ")
            return source.isEmpty ? "local runtime" : source
        }
        let source = [item.sourceID, item.sourceKind]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: " · ")
        return source.isEmpty ? "n/a" : source
    }

    private var normalizedReviewStatus: String {
        item.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    }

    private var isEvolutionDraft: Bool {
        kind == "skills" && (
            normalizedReviewStatus == "pending"
                || item.sourceKind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased().contains("draft")
        )
    }

    private var statusText: String {
        if kind == "tools", !item.available {
            return localizedYouText(model.appLanguage, en: "unavailable", zh: "不可用", fr: "indisponible", de: "nicht verfügbar")
        }
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled {
            return localizedYouText(model.appLanguage, en: "pending review", zh: "待审核", fr: "en attente", de: "wartet")
        }
        if item.enabled {
            return localizedYouText(model.appLanguage, en: "enabled", zh: "已启用", fr: "activé", de: "aktiv")
        }
        return localizedYouText(model.appLanguage, en: "available", zh: "可启用", fr: "disponible", de: "verfügbar")
    }

    private var statusSymbol: String {
        if kind == "tools", !item.available { return "exclamationmark.triangle" }
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled { return "sparkles" }
        return item.enabled ? "checkmark" : "circle"
    }

    private var statusTint: Color {
        if kind == "tools", !item.available { return ElephantTheme.orange }
        if kind == "skills", normalizedReviewStatus == "pending", !item.enabled { return ElephantTheme.evolution }
        return item.enabled ? ElephantTheme.green : ElephantTheme.faint
    }

    private var approveText: String {
        if kind == "skills", normalizedReviewStatus == "pending" {
            return localizedYouText(model.appLanguage, en: "Approve", zh: "通过", fr: "Approuver", de: "Freigeben")
        }
        return localizedYouText(model.appLanguage, en: "Enable", zh: "启用", fr: "Activer", de: "Aktivieren")
    }

    private var normalizedToolRisk: String {
        item.riskClass.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "medium" : item.riskClass
    }

    private var normalizedToolApproval: String {
        item.approvalClass.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "standard" : item.approvalClass
    }

    private var toolRiskTint: Color {
        let value = normalizedToolRisk.lowercased()
        if value.contains("high") || value.contains("risky") { return ElephantTheme.orange }
        if value.contains("low") || value.contains("safe") { return ElephantTheme.green }
        return ElephantTheme.accent
    }

    private var toolRuntimeText: String {
        let parts = [item.family, item.backend]
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        return parts.isEmpty ? "local runtime" : parts.joined(separator: " · ")
    }

    private var requiredFieldsText: String {
        item.requiredFields.isEmpty ? localizedYouText(model.appLanguage, en: "none", zh: "无", fr: "aucune", de: "keine") : item.requiredFields.joined(separator: ", ")
    }

    private var toolSideEffectLabels: [String] {
        var labels: [String] = []
        if item.readsState {
            labels.append(localizedYouText(model.appLanguage, en: "reads state", zh: "读取状态", fr: "lit l'état", de: "liest Zustand"))
        }
        if item.writesState {
            labels.append(localizedYouText(model.appLanguage, en: "writes state", zh: "写入状态", fr: "écrit l'état", de: "schreibt Zustand"))
        }
        if item.touchesNetwork {
            labels.append(localizedYouText(model.appLanguage, en: "network", zh: "网络", fr: "réseau", de: "Netzwerk"))
        }
        if item.touchesSecrets {
            labels.append(localizedYouText(model.appLanguage, en: "secrets", zh: "密钥", fr: "secrets", de: "Secrets"))
        }
        return labels
    }

    private var toolBodyText: String {
        let schema = item.schemaJSON.trimmingCharacters(in: .whitespacesAndNewlines)
        let hasSchema = !schema.isEmpty && schema != "{}"
        let schemaText = hasSchema
            ? "```json\n\(schema)\n```"
            : localizedYouText(model.appLanguage, en: "This tool does not declare an input schema.", zh: "这个工具没有声明输入 schema。", fr: "Cet outil ne déclare pas de schéma d'entrée.", de: "Dieses Tool deklariert kein Eingabeschema.")
        var lines = [
            "## \(localizedYouText(model.appLanguage, en: "Input schema", zh: "输入 schema", fr: "Schéma d'entrée", de: "Eingabeschema"))",
            schemaText,
            "",
            "## \(localizedYouText(model.appLanguage, en: "Runtime metadata", zh: "运行时元数据", fr: "Métadonnées runtime", de: "Runtime-Metadaten"))",
            "- id: \(item.id)",
            "- family: \(item.family.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "n/a" : item.family)",
            "- backend: \(item.backend.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "n/a" : item.backend)",
            "- risk: \(normalizedToolRisk)",
            "- approval: \(normalizedToolApproval)",
            "- required: \(requiredFieldsText)"
        ]
        let provenance = item.provenance.trimmingCharacters(in: .whitespacesAndNewlines)
        if !provenance.isEmpty {
            lines.append("- provenance: \(provenance)")
        }
        return lines.joined(separator: "\n")
    }
}

private struct OperatorDetailBlock: View {
    var label: String
    var value: String
    var lineLimit: Int? = nil

    var body: some View {
        VStack(alignment: .leading, spacing: 5) {
            Text(label)
                .font(.caption.weight(.semibold))
                .foregroundStyle(ElephantTheme.muted)
                .textCase(.uppercase)
            Text(value.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? "n/a" : value)
                .font(.callout)
                .foregroundStyle(ElephantTheme.ink)
                .lineLimit(lineLimit)
                .truncationMode(.tail)
                .fixedSize(horizontal: false, vertical: true)
        }
    }
}

private struct OperatorFallbackNameRows: View {
    var kind: String
    var names: [String]

    var body: some View {
        VStack(spacing: 0) {
            ForEach(names, id: \.self) { name in
                let logo = OperatorLogoSpec.forText(name, kind: kind)
                HStack(spacing: 12) {
                    OperatorCatalogLogo(
                        symbol: logo.symbol,
                        tint: logo.tint,
                        brandSlug: logo.brandSlug
                    )
                    Text(name)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                        .truncationMode(.middle)
                    Spacer(minLength: 0)
                }
                .padding(.horizontal, 12)
                .padding(.vertical, 10)
                if name != names.last {
                    Divider()
                        .padding(.leading, 64)
                }
            }
        }
        .background(Color(nsColor: .controlBackgroundColor).opacity(0.45), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line, lineWidth: 1))
    }
}

private struct OperatorLogoSpec {
    var symbol: String
    var tint: Color
    var brandSlug: String? = nil

    static func forItem(_ item: OperationItem, kind: String) -> OperatorLogoSpec {
        if kind == "skills" {
            let review = item.reviewStatus.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            let sourceKind = item.sourceKind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
            if review == "pending" || sourceKind.contains("draft") {
                return OperatorLogoSpec(symbol: "sparkles", tint: ElephantTheme.evolution)
            }
        }
        let raw = "\(item.id) \(item.title) \(item.detail)".lowercased()
        return forText(raw, kind: kind)
    }

    static func forText(_ text: String, kind: String) -> OperatorLogoSpec {
        let raw = text.lowercased()
        if let brandSlug = brandSlug(for: raw) {
            return OperatorLogoSpec(
                symbol: kind == "tools" ? "wrench.and.screwdriver" : "sparkles",
                tint: kind == "tools" ? ElephantTheme.accent : ElephantTheme.orange,
                brandSlug: brandSlug
            )
        }
        if kind == "tools" {
            if raw.contains("browser") || raw.contains("http") || raw.contains("url") {
                return OperatorLogoSpec(symbol: "safari", tint: ElephantTheme.accent)
            }
            if raw.contains("file") || raw.contains("read") || raw.contains("write") || raw.contains("source") {
                return OperatorLogoSpec(symbol: "doc.text.magnifyingglass", tint: ElephantTheme.green)
            }
            if raw.contains("shell") || raw.contains("terminal") || raw.contains("command") {
                return OperatorLogoSpec(symbol: "terminal", tint: ElephantTheme.orange)
            }
            if raw.contains("message") || raw.contains("gateway") || raw.contains("chat") {
                return OperatorLogoSpec(symbol: "message.badge", tint: ElephantTheme.green)
            }
            if raw.contains("calendar") || raw.contains("cron") || raw.contains("schedule") {
                return OperatorLogoSpec(symbol: "calendar.badge.clock", tint: ElephantTheme.orange)
            }
            if raw.contains("memory") || raw.contains("state") || raw.contains("recall") {
                return OperatorLogoSpec(symbol: "point.3.connected.trianglepath.dotted", tint: ElephantTheme.accent)
            }
            return OperatorLogoSpec(symbol: "wrench.and.screwdriver", tint: ElephantTheme.accent)
        }

        if raw.contains("apple") {
            return OperatorLogoSpec(symbol: "apple.logo", tint: ElephantTheme.ink)
        }
        if raw.contains("browser") || raw.contains("web") || raw.contains("site") {
            return OperatorLogoSpec(symbol: "safari", tint: ElephantTheme.accent)
        }
        if raw.contains("github") || raw.contains("code") || raw.contains("terminal") {
            return OperatorLogoSpec(symbol: "chevron.left.forwardslash.chevron.right", tint: ElephantTheme.orange)
        }
        if raw.contains("document") || raw.contains("paper") || raw.contains("doc") || raw.contains("arxiv") {
            return OperatorLogoSpec(symbol: "doc.text", tint: ElephantTheme.green)
        }
        if raw.contains("image") || raw.contains("design") || raw.contains("figma") {
            return OperatorLogoSpec(symbol: "photo.on.rectangle.angled", tint: ElephantTheme.orange)
        }
        if raw.contains("audio") || raw.contains("video") || raw.contains("speech") {
            return OperatorLogoSpec(symbol: "waveform", tint: ElephantTheme.accent)
        }
        if raw.contains("llm") || raw.contains("agent") || raw.contains("model") || raw.contains("research") {
            return OperatorLogoSpec(symbol: "brain.head.profile", tint: ElephantTheme.green)
        }
        return OperatorLogoSpec(symbol: "puzzlepiece.extension", tint: ElephantTheme.orange)
    }

    private static func brandSlug(for raw: String) -> String? {
        if raw.contains("openai") || raw.contains("chatgpt") || raw.contains("codex") { return "openai" }
        if raw.contains("anthropic") || raw.contains("claude") { return "claude" }
        if raw.contains("gemini") || raw.contains("google ai") || raw.contains("ai studio") { return "gemini" }
        if raw.contains("deepseek") { return "deepseek" }
        if raw.contains("qwen") || raw.contains("dashscope") || raw.contains("alibaba") { return "qwen" }
        if raw.contains("kimi") || raw.contains("moonshot") { return "moonshot" }
        if raw.contains("minimax") { return "minimax" }
        if raw.contains("mistral") { return "mistral" }
        if raw.contains("groq") { return "groq" }
        if raw.contains("xai") || raw.contains("grok") { return "xai" }
        if raw.contains("cohere") { return "cohere" }
        if raw.contains("perplexity") { return "perplexity" }
        if raw.contains("cerebras") { return "cerebras" }
        if raw.contains("nvidia") || raw.contains("nim") || raw.contains("nemotron") { return "nvidia" }
        if raw.contains("siliconflow") || raw.contains("silicon cloud") { return "siliconcloud" }
        if raw.contains("doubao") || raw.contains("volcengine") { return "doubao" }
        if raw.contains("tokenhub") { return "tencentcloud" }
        if raw.contains("hunyuan") || raw.contains("tencent") { return "hunyuan" }
        if raw.contains("qianfan") || raw.contains("wenxin") || raw.contains("baidu") { return "baidu" }
        if raw.contains("stepfun") { return "stepfun" }
        if raw.contains("modelscope") { return "modelscope" }
        if raw.contains("hugging") || raw.contains("transformers") { return "huggingface" }
        if raw.contains("ollama") { return "ollama" }
        if raw.contains("vllm") { return "vllm" }
        if raw.contains("figma") { return "figma" }
        if raw.contains("github") || raw.contains("gh-") || raw.contains("gh_") { return "github" }
        if raw.contains("notion") { return "notion" }
        if raw.contains("langchain") { return "langchain" }
        if raw.contains("langgraph") { return "langgraph" }
        if raw.contains("llamaindex") || raw.contains("llama index") { return "llamaindex" }
        if raw.contains("crewai") || raw.contains("crew ai") { return "crewai" }
        if raw.contains("dify") { return "dify" }
        if raw.contains("mcp") { return "mcp" }
        return nil
    }
}

struct RuntimeConfigSettingsContent: View {
    @EnvironmentObject private var model: ElephantAppModel
    @State private var draft = ""
    @State private var loadedPath = ""
    @State private var loadedYaml = ""

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            SettingsRow(
                label: localizedYouText(model.appLanguage, en: "File", zh: "文件", fr: "Fichier", de: "Datei"),
                value: model.snapshot.settingsPath.isEmpty ? localizedYouText(model.appLanguage, en: "not resolved", zh: "尚未解析", fr: "non résolu", de: "nicht aufgelöst") : model.snapshot.settingsPath
            )

            if model.snapshot.settingsYaml.isEmpty {
                EmptyLine(
                    symbol: "slider.horizontal.3",
                    text: localizedYouText(
                        model.appLanguage,
                        en: "The API did not return editable config text yet.",
                        zh: "API 还没有返回可编辑的配置内容。",
                        fr: "L'API n'a pas encore retourné de configuration modifiable.",
                        de: "Die API hat noch keinen bearbeitbaren Konfigurationstext zurückgegeben."
                    )
                )
            } else {
                VStack(alignment: .leading, spacing: 8) {
                    Text(localizedYouText(model.appLanguage, en: "Global YAML", zh: "全局 YAML", fr: "YAML global", de: "Globales YAML"))
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(ElephantTheme.muted)

                    TextEditor(text: $draft)
                        .font(.system(.callout, design: .monospaced))
                        .foregroundStyle(ElephantTheme.ink)
                        .settingsTextEditor(minHeight: 260)
                        .accessibilityLabel(localizedYouText(model.appLanguage, en: "Global runtime configuration YAML", zh: "全局运行时 YAML 配置", fr: "Configuration YAML globale du runtime", de: "Globale Runtime-Konfiguration als YAML"))
                }

                SettingsActionBar {
                    if !model.configActionResult.isEmpty {
                        Label(model.configActionResult, systemImage: "checkmark.circle.fill")
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(ElephantTheme.green)
                    } else if hasChanges {
                        Text(localizedYouText(model.appLanguage, en: "Unsaved", zh: "未保存", fr: "Non enregistré", de: "Nicht gespeichert"))
                            .font(.caption.weight(.semibold))
                            .foregroundStyle(ElephantTheme.orange)
                    }
                } actions: {
                    Button(localizedYouText(model.appLanguage, en: "Refresh", zh: "刷新", fr: "Actualiser", de: "Aktualisieren")) {
                        Task { try? await model.refreshDashboard() }
                    }
                    .settingsActionButton()

                    Button(localizedYouText(model.appLanguage, en: "Reset", zh: "重置", fr: "Réinitialiser", de: "Zurücksetzen")) {
                        draft = model.snapshot.settingsYaml
                        loadedYaml = model.snapshot.settingsYaml
                        loadedPath = model.snapshot.settingsPath
                    }
                    .settingsActionButton()
                    .disabled(!hasChanges)

                    Button(localizedYouText(model.appLanguage, en: "Save config", zh: "保存配置", fr: "Enregistrer la config", de: "Konfiguration speichern")) {
                        Task { await model.saveGlobalConfig(yamlText: draft) }
                    }
                    .settingsActionButton(.primary)
                    .disabled(!hasChanges || draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
        .onAppear {
            syncDraftIfNeeded()
        }
        .onChange(of: model.snapshot.settingsYaml) { _ in
            syncDraftIfNeeded()
        }
        .onChange(of: model.configActionResult) { result in
            if !result.isEmpty {
                syncDraftFromSnapshot()
            }
        }
    }

    private var hasChanges: Bool {
        draft != model.snapshot.settingsYaml
    }

    private func syncDraftIfNeeded() {
        if loadedPath == model.snapshot.settingsPath && !draft.isEmpty && draft != loadedYaml {
            loadedYaml = model.snapshot.settingsYaml
            return
        }
        syncDraftFromSnapshot()
    }

    private func syncDraftFromSnapshot() {
        draft = model.snapshot.settingsYaml
        loadedPath = model.snapshot.settingsPath
        loadedYaml = model.snapshot.settingsYaml
    }
}

