struct OnboardingFlow: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var onComplete: () -> Void
    @State private var transitionForward = true
    @State private var showLearningSkip = false
    @State private var advancingAsync = false
    private let welcomeStep = 0
    private let languageStep = 1
    private let groundingDepthStep = 8
    private let groundingQuestionStartStep = 9
    private let footerSideSlotWidth: CGFloat = 176
    private let footerProgressWidth: CGFloat = 210

    private var groundingQuestionCount: Int {
        model.onboardingGroundingQuestions.count
    }

    private var groundingQuestionRange: ClosedRange<Int> {
        groundingQuestionStartStep...(groundingQuestionStartStep + max(groundingQuestionCount, 1) - 1)
    }

    private var elephantStep: Int {
        groundingQuestionStartStep + groundingQuestionCount
    }

    private var herdDiscoveryStep: Int {
        elephantStep + 4
    }

    private var providerStep: Int {
        elephantStep + 1
    }

    private var modelStep: Int {
        elephantStep + 2
    }

    private var endpointStep: Int {
        elephantStep + 3
    }

    private var learnStep: Int {
        elephantStep + 5
    }

    private var readyStep: Int {
        elephantStep + 6
    }

    private var isGroundingPhase: Bool {
        model.onboardingStep >= groundingDepthStep && model.onboardingStep < elephantStep
    }

    private var isModelSetupPhase: Bool {
        model.onboardingStep >= providerStep && model.onboardingStep <= endpointStep
    }

    private var isHerdDiscoveryStep: Bool {
        model.onboardingStep == herdDiscoveryStep
    }

    private var isDropdownProfileStep: Bool {
        model.onboardingStep == 4 || model.onboardingStep == 5
    }

    private var isCompactPanelPhase: Bool {
        isGroundingPhase || isModelSetupPhase || isHerdDiscoveryStep
    }

    private var usesExpandedPanel: Bool {
        isCompactPanelPhase || isDropdownProfileStep || model.onboardingStep == learnStep
    }

    private var isWelcomeStep: Bool {
        model.onboardingStep == welcomeStep
    }

    private var panelHeight: CGFloat {
        if isHerdDiscoveryStep { return 668 }
        if model.onboardingStep == learnStep { return 604 }
        if isDropdownProfileStep { return 592 }
        return usesExpandedPanel ? 568 : 486
    }

    private var panelWidth: CGFloat {
        if isHerdDiscoveryStep { return 820 }
        return usesExpandedPanel ? 760 : 680
    }

    private var contentAlignment: Alignment {
        isGroundingPhase ? .center : .topLeading
    }

    var body: some View {
        ZStack {
            if isWelcomeStep {
                OnboardingWelcomeStep {
                    advanceIfPossible()
                }
                .transition(.opacity)
            } else {
                OnboardingBackdrop()
                VStack(spacing: isCompactPanelPhase ? 9 : 18) {
                VStack(spacing: isCompactPanelPhase ? 4 : 10) {
                    BrandMark(size: isCompactPanelPhase ? 52 : 112, framed: false)
                        .shadow(color: ElephantTheme.accent.opacity(isCompactPanelPhase ? 0.06 : 0.10), radius: isCompactPanelPhase ? 12 : 22, y: isCompactPanelPhase ? 5 : 10)
                    Text(model.text(.setupTitle))
                        .font(.system(size: isCompactPanelPhase ? 22 : 28, weight: .semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                    if !isCompactPanelPhase {
                        Text(model.text(.setupSubtitle))
                            .font(.callout)
                            .foregroundStyle(ElephantTheme.muted)
                            .lineLimit(1)
                    }
                }
                .frame(maxWidth: .infinity, alignment: .center)
                .padding(.top, isCompactPanelPhase ? -6 : 0)

                VStack(spacing: 0) {
                    ZStack(alignment: contentAlignment) {
                        stepContent
                            .id(model.onboardingStep)
                            .transition(stepTransition)
                    }
                    .clipped()
                    .animation(stepAnimation, value: model.onboardingStep)
                    .padding(.horizontal, isGroundingPhase ? 32 : 40)
                    .padding(.top, isGroundingPhase ? 22 : 32)
                    .padding(.bottom, isGroundingPhase ? 14 : 20)
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: contentAlignment)
                    Divider()
                    footer
                }
                .frame(width: panelWidth, height: panelHeight)
                .background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .stroke(Color.white.opacity(0.42), lineWidth: 1)
                )
                .shadow(color: Color.black.opacity(0.18), radius: 34, y: 22)

                OnboardingPhaseRail(
                    phases: phases,
                    activeStep: min(model.onboardingStep, readyStep),
                    language: model.appLanguage,
                    canNavigate: model.onboardingStep < learnStep
                ) { phase in
                    selectPhaseIfAllowed(phase)
                }
                .frame(width: panelWidth)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .padding(.vertical, isCompactPanelPhase ? 10 : 24)
            .padding(.horizontal, 28)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
        .onExitCommand {
            goBackIfPossible()
        }
        .task(id: learningSkipTaskKey) {
            await refreshLearningSkipVisibility()
        }
    }

    @ViewBuilder
    private var stepContent: some View {
        switch model.onboardingStep {
        case 1:
            OnboardingLanguageStep()
        case 2:
            OnboardingIdentityStep()
        case 3:
            OnboardingLockPasswordStep()
        case 4:
            OnboardingStepScrollContainer {
                OnboardingWorkStep()
            }
        case 5:
            OnboardingStepScrollContainer {
                OnboardingInterestsStep()
            }
        case 6:
            OnboardingLinksStep()
        case 7:
            OnboardingHealthNotesStep()
        case 8:
            OnboardingGroundingDepthStep()
        case let step where groundingQuestionRange.contains(step):
            OnboardingGroundingQuestionStep(questionIndex: step - groundingQuestionStartStep)
        case let step where step == elephantStep:
            OnboardingElephantStep()
        case let step where step == herdDiscoveryStep:
            OnboardingHerdDiscoveryStep()
        case let step where step == providerStep:
            OnboardingProviderModelStep()
        case let step where step == modelStep:
            OnboardingProviderSecretStep()
        case let step where step == endpointStep:
            OnboardingModelSelectionStep()
        case let step where step == learnStep:
            OnboardingLearningStep()
        default:
            OnboardingCelebrationStep()
        }
    }

    private var footer: some View {
        HStack(spacing: 12) {
            Group {
                if model.onboardingStep > 0 && model.onboardingStep < learnStep {
                    Button {
                        goBackIfPossible()
                    } label: {
                        Label(model.text(.back), systemImage: "chevron.left")
                    }
                    .controlSize(.large)
                    .keyboardShortcut(.cancelAction)
                } else {
                    Color.clear.frame(width: 1, height: 1)
                }
            }
            .frame(width: footerSideSlotWidth, alignment: .leading)

            Spacer(minLength: 0)

            VStack(spacing: 2) {
                Label(currentPhase.title.text(model.appLanguage), systemImage: currentPhase.symbol)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.muted)
                    .labelStyle(.titleAndIcon)
                    .lineLimit(1)
                if let nextRequirement {
                    Label(nextRequirement, systemImage: "exclamationmark.circle.fill")
                        .font(.caption2.weight(.semibold))
                        .foregroundStyle(ElephantTheme.orange)
                        .labelStyle(.titleAndIcon)
                        .lineLimit(1)
                        .minimumScaleFactor(0.78)
                } else {
                    Text(phaseProgressText)
                        .font(.caption2.weight(.semibold))
                        .foregroundStyle(ElephantTheme.faint)
                        .monospacedDigit()
                    }
            }
            .frame(width: footerProgressWidth)

            Spacer(minLength: 0)

            Group {
                if model.onboardingStep < learnStep {
                    HStack(spacing: 8) {
                        if isGroundingQuestionStep {
                            Button {
                                skipCurrentGroundingQuestion()
                            } label: {
                                Text(localizedYouText(model.appLanguage, en: "Skip", zh: "跳过", fr: "Passer", de: "Überspringen"))
                            }
                            .controlSize(.large)
                            .help(localizedYouText(model.appLanguage, en: "Skip this question for now", zh: "暂时跳过这道题", fr: "Passer cette question pour l'instant", de: "Diese Frage vorerst überspringen"))
                        }

                        Button {
                            advanceIfPossible()
                        } label: {
                            Label(nextTitle, systemImage: advancingAsync ? "hourglass" : "chevron.right")
                        }
                        .buttonStyle(.borderedProminent)
                        .controlSize(.large)
                        .tint(ElephantTheme.accent)
                        .disabled(nextDisabled || advancingAsync)
                        .help(nextRequirement ?? nextTitle)
                        .accessibilityHint(nextRequirement ?? nextTitle)
                        .keyboardShortcut(.defaultAction)
                    }
                } else if model.onboardingStep == learnStep && onboardingLearningCompleted {
                    Button {
                        onComplete()
                    } label: {
                        Label(model.text(.enterElephant), systemImage: "arrow.right.circle.fill")
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.large)
                    .tint(ElephantTheme.accent)
                    .keyboardShortcut(.defaultAction)
                    .transition(stepTransition)
                } else if model.onboardingStep == learnStep && showLearningSkip {
                    Button {
                        model.skipOnboardingLearningAndContinue()
                    } label: {
                        Label(
                            localizedYouText(model.appLanguage, en: "Skip and continue", zh: "跳过，后台继续学习", fr: "Passer et continuer", de: "Überspringen und weiter"),
                            systemImage: "arrow.right.circle.fill"
                        )
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.large)
                    .tint(ElephantTheme.accent)
                    .help(localizedYouText(model.appLanguage, en: "Enter Elephant now; learning keeps running in the background.", zh: "现在进入 Elephant，学习任务会在后台继续。", fr: "Entrer maintenant ; l'apprentissage continue en arrière-plan.", de: "Jetzt öffnen; Lernen läuft im Hintergrund weiter."))
                    .keyboardShortcut(.defaultAction)
                    .transition(stepTransition)
                } else if model.onboardingStep == readyStep {
                    Button {
                        onComplete()
                    } label: {
                        Label(model.text(.enterElephant), systemImage: "arrow.right.circle.fill")
                    }
                    .buttonStyle(.borderedProminent)
                    .controlSize(.large)
                    .tint(ElephantTheme.accent)
                    .keyboardShortcut(.defaultAction)
                } else {
                    Color.clear.frame(width: 1, height: 1)
                }
            }
            .frame(width: isGroundingQuestionStep ? 236 : footerSideSlotWidth, alignment: .trailing)
        }
        .padding(.horizontal, 30)
        .padding(.vertical, isGroundingPhase ? 13 : 18)
        .background(Color(nsColor: .windowBackgroundColor).opacity(0.40))
    }

    private func goBackIfPossible() {
        guard model.onboardingStep > 0 && model.onboardingStep < learnStep else { return }
        transitionForward = false
        withAnimation(stepAnimation) {
            model.onboardingStep = max(0, model.onboardingStep - 1)
        }
    }

    private func advanceIfPossible() {
        guard model.onboardingStep < learnStep, !nextDisabled, !advancingAsync else { return }
        if model.onboardingStep == 3 {
            _ = model.persistOnboardingLockPassword()
        }
        if model.onboardingStep == endpointStep {
            transitionForward = true
            advancingAsync = true
            Task {
                await model.createElephantFromOnboarding()
                _ = await model.scanLocalAgentsForHerd()
                await MainActor.run {
                    advancingAsync = false
                    withAnimation(stepAnimation) {
                        model.onboardingStep = herdDiscoveryStep
                    }
                }
            }
            return
        }
        if model.onboardingStep == herdDiscoveryStep {
            transitionForward = true
            advancingAsync = true
            Task {
                await MainActor.run {
                    advancingAsync = false
                    withAnimation(stepAnimation) {
                        model.onboardingStep = learnStep
                    }
                }
            }
            return
        }
        transitionForward = true
        withAnimation(stepAnimation) {
            model.onboardingStep = min(learnStep, model.onboardingStep + 1)
        }
    }

    private func skipCurrentGroundingQuestion() {
        guard let question = currentGroundingQuestion else {
            advanceIfPossible()
            return
        }
        model.skipOnboardingGroundingQuestion(questionID: question.id)
        advanceIfPossible()
    }

    private func selectPhaseIfAllowed(_ phase: OnboardingPhase) {
        guard model.onboardingStep < learnStep,
              phase.range.lowerBound <= model.onboardingStep
        else { return }
        transitionForward = phase.range.lowerBound >= model.onboardingStep
        withAnimation(stepAnimation) {
            model.onboardingStep = phase.range.lowerBound
        }
    }

    private var learningSkipTaskKey: String {
        "\(model.onboardingStep)|\(model.onboardingFinalizationComplete)|\(model.onboardingFinalizationStarted)|\(model.onboardingInitReflectJobID)"
    }

    @MainActor
    private func refreshLearningSkipVisibility() async {
        showLearningSkip = false
        guard model.onboardingStep == learnStep, !onboardingLearningCompleted else { return }
        try? await Task.sleep(nanoseconds: 60_000_000_000)
        guard !Task.isCancelled else { return }
        guard model.onboardingStep == learnStep, !onboardingLearningCompleted else { return }
        withAnimation(stepAnimation) {
            showLearningSkip = true
        }
    }

    private var stepTransition: AnyTransition {
        guard !reduceMotion else { return .opacity }
        let insertionX: CGFloat = transitionForward ? 34 : -34
        let removalX: CGFloat = transitionForward ? -28 : 28
        return .asymmetric(
            insertion: .offset(x: insertionX, y: 0)
                .combined(with: .opacity)
                .combined(with: .scale(scale: 0.985, anchor: .center)),
            removal: .offset(x: removalX, y: 0)
                .combined(with: .opacity)
                .combined(with: .scale(scale: 0.992, anchor: .center))
        )
    }

    private var stepAnimation: Animation {
        reduceMotion
            ? .easeInOut(duration: 0.16)
            : .spring(response: 0.42, dampingFraction: 0.86, blendDuration: 0.06)
    }

    private var nextTitle: String {
        if model.onboardingStep == 0 { return model.text(.continueAction) }
        if model.onboardingStep == herdDiscoveryStep {
            return model.onboardingSelectedBabyBackend.isEmpty
                ? localizedYouText(model.appLanguage, en: "Continue", zh: "继续", fr: "Continuer", de: "Weiter")
                : localizedYouText(model.appLanguage, en: "Use engine", zh: "使用引擎", fr: "Utiliser le moteur", de: "Antrieb nutzen")
        }
        if model.onboardingStep == endpointStep {
            return localizedYouText(model.appLanguage, en: "Create Agent", zh: "创建小象", fr: "Créer agent", de: "Agent erstellen")
        }
        if model.onboardingStep == 3, onboardingLockPasswordDraftIsEmpty {
            return localizedYouText(model.appLanguage, en: "Skip for now", zh: "稍后", fr: "Plus tard", de: "Später")
        }
        return model.text(.next)
    }

    private var nextRequirement: String? {
        guard nextDisabled else { return nil }
        switch model.onboardingStep {
        case 2:
            return model.text(.requirementPreferredName)
        case 3:
            if onboardingLockPasswordDraftIsEmpty {
                return nil
            }
            if model.onboardingLockPassword.trimmingCharacters(in: .whitespacesAndNewlines).count < 6 {
                return model.text(.lockPasswordRequirement)
            }
            return model.text(.lockPasswordMismatch)
        case let step where step == elephantStep:
            return model.text(.requirementElephantIdentity)
        case let step where step == providerStep:
            return model.text(.providerTitle)
        case let step where step == modelStep:
            return model.text(.requirementProviderDetails)
        case let step where step == endpointStep:
            return model.text(.selectModel)
        default:
            return nil
        }
    }

    private var currentPhase: OnboardingPhase {
        phases.first { $0.range.contains(min(model.onboardingStep, readyStep)) } ?? phases[0]
    }

    private var phaseProgressText: String {
        let currentID = currentPhase.id
        let index = phases.firstIndex { $0.id == currentID } ?? 0
        let overall = "\(index + 1)/\(phases.count)"
        guard currentPhase.range.lowerBound < currentPhase.range.upperBound else {
            return overall
        }
        let currentStep = min(max(model.onboardingStep, currentPhase.range.lowerBound), currentPhase.range.upperBound)
        let phaseIndex = currentStep - currentPhase.range.lowerBound + 1
        let phaseCount = currentPhase.range.upperBound - currentPhase.range.lowerBound + 1
        let inPhase = localizedYouText(
            model.appLanguage,
            en: "step \(phaseIndex)/\(phaseCount)",
            zh: "本阶段 \(phaseIndex)/\(phaseCount)",
            fr: "étape \(phaseIndex)/\(phaseCount)",
            de: "Schritt \(phaseIndex)/\(phaseCount)"
        )
        return "\(overall) · \(inPhase)"
    }

    private var phases: [OnboardingPhase] {
        [
            OnboardingPhase(id: "language", title: .phaseLanguage, symbol: "globe", range: languageStep...languageStep),
            OnboardingPhase(id: "profile", title: .phaseProfile, symbol: "person.crop.square", range: 2...7),
            OnboardingPhase(id: "patterns", title: .phasePattern, symbol: "checklist", range: groundingDepthStep...groundingQuestionRange.upperBound),
            OnboardingPhase(id: "elephant", title: .phaseElephant, symbol: "sparkles", range: elephantStep...elephantStep),
            OnboardingPhase(id: "model", title: .phaseModel, symbol: "cpu", range: providerStep...endpointStep),
            OnboardingPhase(id: "herd", title: .phaseHerd, symbol: "person.3.sequence", range: herdDiscoveryStep...herdDiscoveryStep),
            OnboardingPhase(id: "ready", title: .phaseReady, symbol: "checkmark.seal", range: learnStep...readyStep)
        ]
    }

    private var nextDisabled: Bool {
        switch model.onboardingStep {
        case 2:
            return model.onboardingPreferredName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        case 3:
            if onboardingLockPasswordDraftIsEmpty {
                return false
            }
            return !model.onboardingLockPasswordIsValid
        case let step where step == elephantStep:
            return model.onboardingName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                || model.onboardingPurpose.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        case let step where step == providerStep:
            let provider = model.onboardingProviderID.trimmingCharacters(in: .whitespacesAndNewlines)
            let catalog = onboardingProviderChoices(snapshotOptions: model.snapshot.providerOptions, language: model.appLanguage)
            return provider.isEmpty || !catalog.contains(where: { $0.id == provider })
        case let step where step == modelStep:
            return !providerCredentialsReady
        case let step where step == endpointStep:
            return !providerReady
        default:
            return false
        }
    }

    private var isGroundingQuestionStep: Bool {
        groundingQuestionRange.contains(model.onboardingStep)
    }

    private var onboardingLockPasswordDraftIsEmpty: Bool {
        model.onboardingLockPassword.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
            && model.onboardingLockPasswordConfirmation.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    private var currentGroundingQuestion: OnboardingGroundingQuestion? {
        guard isGroundingQuestionStep else { return nil }
        return model.onboardingGroundingQuestion(at: model.onboardingStep - groundingQuestionStartStep)
    }

    private var providerReady: Bool {
        let provider = model.onboardingProviderID.trimmingCharacters(in: .whitespacesAndNewlines)
        let modelID = model.onboardingModelID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !provider.isEmpty, !modelID.isEmpty else { return false }
        let catalog = onboardingProviderChoices(snapshotOptions: model.snapshot.providerOptions, language: model.appLanguage)
        guard catalog.contains(where: { $0.id == provider }) else { return false }
        return providerCredentialsReady
    }

    private var onboardingLearningCompleted: Bool {
        if model.onboardingFinalizationComplete {
            return true
        }
        let status = (model.onboardingLearningJob?.status ?? "")
            .trimmingCharacters(in: .whitespacesAndNewlines)
            .lowercased()
        return status.contains("completed")
            || status.contains("succeeded")
            || status == "success"
    }

    private var providerCredentialsReady: Bool {
        let provider = model.onboardingProviderID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !provider.isEmpty else { return false }
        let catalog = onboardingProviderChoices(snapshotOptions: model.snapshot.providerOptions, language: model.appLanguage)
        guard let option = catalog.first(where: { $0.id == provider }) else { return false }
        if option.active || option.connected || option.storedKeyCount > 0 {
            return true
        }
        if provider == "openai-compatible" {
            return !model.onboardingBaseURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                && !model.onboardingAPIKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
        let authKind = option.authKind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if authKind == "none" || authKind == "no_auth" || authKind == "local" {
            return true
        }
        return !model.onboardingAPIKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }
}

