struct OnboardingField: View {
    var title: String
    var placeholder: String
    @Binding var text: String
    var lines: ClosedRange<Int> = 1...1
    var secure = false
    var autoFocus = false
    var suggestions: [String] = []
    var minHeight: CGFloat? = nil
    var fillsAvailableHeight = false
    @FocusState private var focused: Bool
    @State private var hovering = false

    private var hasValue: Bool {
        !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Text(title)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(focused ? ElephantTheme.accent : ElephantTheme.muted)
                Spacer(minLength: 0)
                if hasValue {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(ElephantTheme.green)
                        .transition(.opacity.combined(with: .scale))
                }
            }
            .contentShape(Rectangle())
            .onTapGesture { focused = true }
            Group {
                if secure {
                    SecureField(placeholder, text: $text)
                        .focused($focused)
                } else {
                    TextField(placeholder, text: $text, axis: lines.upperBound > 1 ? .vertical : .horizontal)
                        .lineLimit(lines)
                        .focused($focused)
                }
            }
            .textFieldStyle(.plain)
            .font(.callout)
            .foregroundStyle(ElephantTheme.ink)
            .padding(.horizontal, 12)
            .padding(.vertical, lines.upperBound > 1 ? 12 : 11)
            .frame(
                maxWidth: .infinity,
                minHeight: fieldMinHeight,
                maxHeight: fillsAvailableHeight ? .infinity : nil,
                alignment: .topLeading
            )
            .background(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .fill(fieldFill)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 8, style: .continuous)
                    .stroke(fieldStroke, lineWidth: focused ? 1.4 : 1)
            )
            .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
            .onTapGesture { focused = true }
            .onHover { isHovering in
                hovering = isHovering
                isHovering ? NSCursor.iBeam.set() : NSCursor.arrow.set()
            }
            .shadow(color: ElephantTheme.accent.opacity(focused ? 0.10 : 0), radius: focused ? 10 : 0, y: focused ? 4 : 0)
            .help(helpText)
            .accessibilityLabel(accessibilityText)
            .animation(.easeOut(duration: 0.16), value: focused)
            .animation(.easeOut(duration: 0.16), value: hovering)
            .animation(.easeOut(duration: 0.16), value: hasValue)

            if !suggestions.isEmpty {
                OnboardingSuggestionChips(suggestions: suggestions, selection: $text)
            }
        }
        .frame(maxWidth: .infinity, maxHeight: fillsAvailableHeight ? .infinity : nil, alignment: .topLeading)
        .onAppear {
            guard autoFocus else { return }
            DispatchQueue.main.asyncAfter(deadline: .now() + 0.18) {
                focused = true
            }
        }
    }

    private var fieldMinHeight: CGFloat {
        if let minHeight { return minHeight }
        return lines.upperBound > 1 ? 92 : 46
    }

    private var fieldFill: Color {
        if focused {
            return ElephantTheme.accent.opacity(0.09)
        }
        if hovering {
            return Color(nsColor: .controlBackgroundColor).opacity(0.92)
        }
        return Color(nsColor: .controlBackgroundColor).opacity(0.72)
    }

    private var fieldStroke: Color {
        if focused {
            return ElephantTheme.accent.opacity(0.72)
        }
        if hovering {
            return ElephantTheme.accent.opacity(0.32)
        }
        return ElephantTheme.line.opacity(0.76)
    }

    private var helpText: String {
        if secure {
            return hasValue ? title : placeholder
        }
        return hasValue ? "\(title): \(text)" : placeholder
    }

    private var accessibilityText: String {
        if secure {
            return title
        }
        return "\(title), \(hasValue ? text : placeholder)"
    }
}

struct OnboardingSuggestionChips: View {
    var suggestions: [String]
    @Binding var selection: String

    private let columns = [
        GridItem(.adaptive(minimum: 116), spacing: 8)
    ]

    var body: some View {
        LazyVGrid(columns: columns, alignment: .leading, spacing: 8) {
            ForEach(suggestions, id: \.self) { suggestion in
                Button {
                    selection = suggestion
                } label: {
                    HStack(spacing: 6) {
                        Text(suggestion)
                            .font(.caption.weight(.semibold))
                            .lineLimit(1)
                            .minimumScaleFactor(0.82)
                        Spacer(minLength: 0)
                        if selection == suggestion {
                            Image(systemName: "checkmark.circle.fill")
                                .font(.caption2.weight(.semibold))
                        }
                    }
                    .foregroundStyle(selection == suggestion ? ElephantTheme.accent : ElephantTheme.ink)
                    .padding(.horizontal, 10)
                    .frame(maxWidth: .infinity, minHeight: 28)
                    .background(
                        selection == suggestion
                            ? ElephantTheme.accent.opacity(0.14)
                            : Color(nsColor: .controlBackgroundColor).opacity(0.58),
                        in: Capsule()
                    )
                    .overlay(
                        Capsule()
                            .stroke(selection == suggestion ? ElephantTheme.accent.opacity(0.48) : ElephantTheme.line.opacity(0.58), lineWidth: 1)
                    )
                    .contentShape(Capsule())
                }
                .buttonStyle(PressablePlainButtonStyle())
                .help(suggestion)
                .accessibilityLabel(suggestion)
            }
        }
    }
}

struct OnboardingMenuField: View {
    var title: String
    var placeholder: String
    var options: [String]
    @Binding var selection: String
    @State private var hovering = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                Text(title)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.muted)
                Spacer(minLength: 0)
                if !selection.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                    Image(systemName: "checkmark.circle.fill")
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(ElephantTheme.green)
                }
            }
            Menu {
                Button(placeholder) {
                    selection = ""
                }
                Divider()
                ForEach(options, id: \.self) { option in
                    Button(option) {
                        selection = option
                    }
                }
            } label: {
                HStack(spacing: 10) {
                    Text(selection.isEmpty ? placeholder : selection)
                        .font(.callout)
