struct SurveyQuestionBlock: View {
    var title: String
    var prompt: String
    var options: [String]
    @Binding var selection: String

    var body: some View {
        GeometryReader { proxy in
            let verticalSpacing: CGFloat = 22
            let gridSpacing: CGFloat = 12
            let rowCount = CGFloat(max(1, (options.count + 1) / 2))
            let availableGridHeight = max(180, proxy.size.height - 124 - verticalSpacing)
            let cardHeight = min(92, max(74, (availableGridHeight - gridSpacing * (rowCount - 1)) / rowCount))
            VStack(alignment: .center, spacing: verticalSpacing) {
                Spacer(minLength: 0)
                VStack(alignment: .center, spacing: 8) {
                    Text(title)
                        .font(.system(size: 22, weight: .bold, design: .rounded))
                        .foregroundStyle(ElephantTheme.ink)
                        .multilineTextAlignment(.center)
                    Text(prompt)
                        .font(.callout.weight(.semibold))
                        .foregroundStyle(ElephantTheme.muted)
                        .fixedSize(horizontal: false, vertical: true)
                        .multilineTextAlignment(.center)
                }
                .frame(maxWidth: 680)

                LazyVGrid(columns: [GridItem(.flexible(), spacing: gridSpacing), GridItem(.flexible(), spacing: gridSpacing)], spacing: gridSpacing) {
                    ForEach(options, id: \.self) { option in
                        Button {
                            selection = option
                        } label: {
                            SurveyOptionCard(
                                title: option,
                                selected: selection == option,
                                height: cardHeight
                            )
                        }
                        .buttonStyle(PressablePlainButtonStyle())
                        .help(option)
                        .accessibilityLabel(option)
                    }
                }
                .frame(maxWidth: 920)
                Spacer(minLength: 0)
            }
            .frame(width: proxy.size.width, height: proxy.size.height, alignment: .center)
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }
}

struct SurveyOptionCard: View {
    var title: String
    var selected: Bool
    var height: CGFloat
    @State private var hovering = false

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: selected ? "checkmark.circle.fill" : "circle")
                .font(.callout.weight(.semibold))
                .symbolRenderingMode(.hierarchical)
                .foregroundStyle(selected ? .white : hovering ? ElephantTheme.accent : ElephantTheme.faint)
                .frame(width: 22, height: 22)

            Text(title)
                .font(.callout.weight(.semibold))
                .foregroundStyle(selected ? .white : ElephantTheme.ink)
                .lineLimit(2)
                .minimumScaleFactor(0.76)
                .multilineTextAlignment(.leading)

            Spacer(minLength: 0)
        }
        .padding(.horizontal, 16)
        .frame(maxWidth: .infinity, minHeight: height, maxHeight: height, alignment: .center)
        .background(cardBackground)
        .overlay(
            RoundedRectangle(cornerRadius: 8, style: .continuous)
                .stroke(borderColor, lineWidth: selected ? 1.5 : 1)
        )
        .shadow(color: shadowColor, radius: selected ? 14 : hovering ? 10 : 0, y: selected ? 7 : 4)
        .contentShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
        .onHover { hovering = $0 }
        .animation(.easeOut(duration: 0.16), value: hovering)
        .animation(.easeOut(duration: 0.16), value: selected)
    }

    @ViewBuilder
    private var cardBackground: some View {
        RoundedRectangle(cornerRadius: 8, style: .continuous)
            .fill(Color(nsColor: .controlBackgroundColor).opacity(hovering ? 0.88 : 0.72))
        if selected {
            RoundedRectangle(cornerRadius: 8, style: .continuous)
                .fill(
                    LinearGradient(
                        colors: [
                            ElephantTheme.accent,
                            ElephantTheme.green.opacity(0.86)
                        ],
                        startPoint: .topLeading,
                        endPoint: .bottomTrailing
                    )
                )
        }
    }

    private var borderColor: Color {
        if selected { return Color.white.opacity(0.42) }
        if hovering { return ElephantTheme.accent.opacity(0.46) }
        return ElephantTheme.line.opacity(0.72)
    }

    private var shadowColor: Color {
        if selected { return ElephantTheme.accent.opacity(0.18) }
        if hovering { return ElephantTheme.accent.opacity(0.10) }
        return .clear
    }
}

private func onboardingProviderChoices(snapshotOptions: [ProviderOption], language _: AppLanguage) -> [ProviderOption] {
    snapshotOptions
}

struct OnboardingProviderModelStep: View {
    @EnvironmentObject private var model: ElephantAppModel
    @State private var loaded = false
    @State private var providerSearch = ""
    @State private var loadingCatalog = false
    @State private var catalogAttempts = 0

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            OnboardingStepHeader(
                title: model.text(.providerTitle),
                subtitle: model.text(.providerSubtitle),
                symbol: "cpu"
            )

            VStack(alignment: .leading, spacing: 8) {
                SectionLabel(
                    title: model.text(.providerFactory),
                    subtitle: providerFactorySubtitle
                )
                if providerChoices.isEmpty {
                    providerCatalogWaitingView
                } else {
                    ProviderSearchField(
                        text: $providerSearch,
                        placeholder: model.text(.providerSearchPlaceholder)
                    )
                    ScrollView(.vertical, showsIndicators: filteredProviders.count > 6) {
                        ProviderFactoryGrid(
                            options: filteredProviders,
                            selectedID: model.onboardingProviderID,
                            activeID: model.snapshot.providerID,
                            columnsCount: 3,
                            emptyText: localizedYouText(model.appLanguage, en: "No provider matches this search.", zh: "没有找到匹配的模型服务。", fr: "Aucun fournisseur ne correspond.", de: "Kein passender Anbieter.")
                        ) { option in
                            selectProvider(option)
                        }
                    }
                    .frame(height: 300)
                }
            }
        }
        .onAppear {
            guard !loaded else { return }
            loadFromSnapshot()
            loaded = true
        }
        .task {
            await waitForProviderCatalog(force: false)
        }
        .onChange(of: model.snapshot.providerOptions) { _ in
            guard !model.snapshot.providerOptions.isEmpty else { return }
            loadFromSnapshot()
        }
        .onChange(of: model.onboardingProviderID) { _ in
            applyProviderDefaults(onlyWhenEmpty: false)
        }
    }

    private var providerChoices: [ProviderOption] {
        onboardingProviderChoices(snapshotOptions: model.snapshot.providerOptions, language: model.appLanguage)
    }

    private var selectedOption: ProviderOption? {
        providerChoices.first(where: { $0.id == model.onboardingProviderID })
    }

    private var providerFactorySubtitle: String {
        if providerChoices.isEmpty {
            return localizedYouText(model.appLanguage, en: "preparing available model services", zh: "正在准备可用的模型服务", fr: "préparation des services disponibles", de: "verfügbare Modelldienste werden vorbereitet")
        }
        return "\(filteredProviders.count)/\(providerChoices.count) \(model.text(.providerFactorySubtitle))"
    }

    private var providerCatalogWaitingView: some View {
        VStack(alignment: .leading, spacing: 16) {
            HStack(alignment: .center, spacing: 14) {
                ZStack {
                    RoundedRectangle(cornerRadius: 8, style: .continuous)
                        .fill(ElephantTheme.accent.opacity(0.10))
                    ProgressView()
                        .controlSize(.small)
                }
                .frame(width: 42, height: 42)

                VStack(alignment: .leading, spacing: 4) {
                    Text(localizedYouText(model.appLanguage, en: "Preparing model services", zh: "正在准备模型服务", fr: "Préparation des services", de: "Modelldienste werden vorbereitet"))
                        .font(.system(size: 17, weight: .semibold))
                        .foregroundStyle(ElephantTheme.ink)
                    Text(localizedYouText(model.appLanguage, en: "Elephant is checking which model connections are ready on this Mac.", zh: "Elephant 正在检查这台 Mac 上哪些模型连接可以使用。", fr: "Elephant vérifie les connexions de modèles disponibles sur ce Mac.", de: "Elephant prüft, welche Modellverbindungen auf diesem Mac bereit sind."))
                        .font(.callout)
                        .foregroundStyle(ElephantTheme.muted)
                        .fixedSize(horizontal: false, vertical: true)
                }

                Spacer(minLength: 0)

                Button {
                    Task { await waitForProviderCatalog(force: true) }
                } label: {
                    Label(model.text(.refresh), systemImage: "arrow.clockwise")
                        .labelStyle(.titleAndIcon)
                }
                .buttonStyle(PressablePlainButtonStyle())
                .controlSize(.small)
                .help(model.text(.refresh))
            }

            VStack(spacing: 8) {
                providerCatalogWaitingStep(
                    title: localizedYouText(model.appLanguage, en: "Wake local service", zh: "唤醒本机服务", fr: "Réveiller le service local", de: "Lokalen Dienst wecken"),
                    detail: localizedYouText(model.appLanguage, en: "Getting Elephant ready to talk to models.", zh: "让 Elephant 准备好和模型沟通。", fr: "Prépare Elephant à parler aux modèles.", de: "Elephant wird für Modellgespräche vorbereitet."),
                    symbol: "bolt.horizontal",
                    active: true
                )
                providerCatalogWaitingStep(
                    title: localizedYouText(model.appLanguage, en: "Find available models", zh: "整理可用模型", fr: "Trouver les modèles disponibles", de: "Verfügbare Modelle finden"),
                    detail: localizedYouText(model.appLanguage, en: "Only choices that are ready now will appear.", zh: "只显示现在真实可用的选择。", fr: "Seuls les choix prêts apparaissent.", de: "Nur bereite Optionen erscheinen."),
                    symbol: "list.bullet.rectangle",
                    active: catalogAttempts > 0
                )
                providerCatalogWaitingStep(
                    title: localizedYouText(model.appLanguage, en: "Choose the best fit", zh: "选择合适的模型", fr: "Choisir le bon modèle", de: "Passendes Modell wählen"),
                    detail: localizedYouText(model.appLanguage, en: "Other local elephants can use the same choice later.", zh: "之后的小象也可以沿用这套选择。", fr: "Les autres elephants locaux pourront réutiliser ce choix.", de: "Andere lokale Elephants können diese Wahl später nutzen."),
                    symbol: "checkmark.seal",
                    active: false
                )
            }

            HStack(spacing: 8) {
                Image(systemName: "info.circle")
                    .foregroundStyle(ElephantTheme.accent)
                Text(catalogAttempts > 1
                    ? localizedYouText(model.appLanguage, en: "Checked \(catalogAttempts) times. Still waiting for an available choice.", zh: "已检查 \(catalogAttempts) 次，仍在等待可用选择。", fr: "\(catalogAttempts) vérifications ; attente d'un choix disponible.", de: "\(catalogAttempts) Prüfungen; warte auf eine verfügbare Wahl.")
                    : localizedYouText(model.appLanguage, en: "Next unlocks as soon as a usable model is ready.", zh: "有可用模型后，下一步会自动可用。", fr: "Suivant s'active dès qu'un modèle est prêt.", de: "Weiter wird aktiv, sobald ein Modell bereit ist.")
                )
                .font(.caption.weight(.semibold))
                .foregroundStyle(ElephantTheme.muted)
                .lineLimit(2)
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 8)
            .background(ElephantTheme.accent.opacity(0.07), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        }
        .padding(18)
        .frame(maxWidth: .infinity, minHeight: 242, alignment: .topLeading)
        .background(Color(nsColor: .textBackgroundColor).opacity(0.92), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line.opacity(0.58), lineWidth: 1))
        .shadow(color: Color.black.opacity(0.04), radius: 16, x: 0, y: 8)
    }

    private func providerCatalogWaitingStep(title: String, detail: String, symbol: String, active: Bool) -> some View {
        HStack(alignment: .top, spacing: 10) {
            Image(systemName: active ? "checkmark.circle.fill" : symbol)
                .font(.callout.weight(.semibold))
                .symbolRenderingMode(.hierarchical)
                .foregroundStyle(active ? ElephantTheme.green : ElephantTheme.faint)
                .frame(width: 22, height: 22)
                .padding(.top, 1)
            VStack(alignment: .leading, spacing: 2) {
                Text(title)
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(detail)
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
        .padding(.horizontal, 11)
        .padding(.vertical, 9)
        .background(Color(nsColor: .controlBackgroundColor).opacity(active ? 0.70 : 0.46), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
    }

    private var filteredProviders: [ProviderOption] {
        let needle = providerSearch.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return providerChoices
            .filter { option in
                guard !needle.isEmpty else { return true }
                return providerSearchText(option).contains(needle)
            }
            .sorted { left, right in
                let leftRank = providerSortRank(left)
                let rightRank = providerSortRank(right)
                if leftRank != rightRank {
                    return leftRank < rightRank
                }
                return left.displayName.localizedCaseInsensitiveCompare(right.displayName) == .orderedAscending
            }
    }

    private func providerSearchText(_ option: ProviderOption) -> String {
        [
            option.displayName,
            option.id,
            option.defaultModel,
            option.defaultBaseURL,
            option.status,
            option.source,
            option.authKind,
            option.summary,
            option.models.map(\.id).joined(separator: " ")
        ]
        .joined(separator: " ")
        .lowercased()
    }

    private func providerSortRank(_ option: ProviderOption) -> Int {
        if option.id == model.snapshot.providerID || option.active { return 0 }
        if option.connected { return 1 }
        if option.storedKeyCount > 0 { return 2 }
        if option.id == model.onboardingProviderID { return 3 }
        return 4
    }

    private func loadFromSnapshot() {
        guard !providerChoices.isEmpty else { return }
        let activeID = model.snapshot.providerID.trimmingCharacters(in: .whitespacesAndNewlines)
        let activeOption = providerChoices.first(where: { $0.id == activeID })
        let preferredOption = activeOption
            ?? providerChoices.first(where: { $0.connected || $0.active || $0.storedKeyCount > 0 })
            ?? providerChoices.first
        guard let preferredOption else { return }
        model.onboardingProviderID = preferredOption.id
        model.onboardingModelID = activeOption == nil ? "" : model.snapshot.providerModelID
        model.onboardingBaseURL = activeOption == nil ? "" : model.snapshot.providerBaseURL
        applyProviderDefaults(onlyWhenEmpty: true)
    }

    private func waitForProviderCatalog(force: Bool) async {
        guard force || providerChoices.isEmpty else { return }
        loadingCatalog = true
        while !Task.isCancelled && providerChoices.isEmpty {
            catalogAttempts += 1
            await model.refreshProviderCatalogForOnboarding()
            if !providerChoices.isEmpty {
                break
            }
            try? await Task.sleep(nanoseconds: 1_200_000_000)
        }
        loadingCatalog = false
        if !providerChoices.isEmpty {
            loadFromSnapshot()
        }
    }

    private func applyProviderDefaults(onlyWhenEmpty: Bool) {
        guard let option = selectedOption else { return }
        let canUseCatalogWithoutKey = option.active || option.connected || option.storedKeyCount > 0
        if canUseCatalogWithoutKey {
            if !onlyWhenEmpty || model.onboardingModelID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                model.onboardingModelID = option.defaultModel.isEmpty ? (option.models.first?.id ?? model.onboardingModelID) : option.defaultModel
            }
        } else if !onlyWhenEmpty {
            model.onboardingModelID = ""
        }
        if !onlyWhenEmpty || model.onboardingBaseURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            model.onboardingBaseURL = option.defaultBaseURL
        }
    }

    private func selectProvider(_ option: ProviderOption) {
        let changedProvider = model.onboardingProviderID != option.id
        model.onboardingProviderID = option.id
        if changedProvider {
            model.onboardingModelID = ""
            model.onboardingBabyProviderModelID = ""
            model.onboardingAPIKey = ""
        }
        applyProviderDefaults(onlyWhenEmpty: false)
    }
}

struct OnboardingModelSelectionStep: View {
    @EnvironmentObject private var model: ElephantAppModel
    @State private var discoveredModels: [String: [ProviderModelOption]] = [:]
    @State private var loadingModels = false
    @State private var loaded = false

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            OnboardingStepHeader(
                title: model.text(.modelSection),
                subtitle: providerAlreadyUsable ? model.text(.activeModelSubtitle) : model.text(.modelPickerSubtitle),
                symbol: "square.stack.3d.up"
            )

            if let option = selectedOption {
                ProviderOnboardingSummary(option: option, modelID: model.onboardingModelID)
            }

            HStack {
                SectionLabel(title: model.text(.modelList), subtitle: model.text(.modelPickerSubtitle))
                Spacer(minLength: 0)
                Button {
                    Task { await loadLiveModels(force: true) }
                } label: {
                    Label(loadingModels ? model.text(.fetching) : model.text(.fetch), systemImage: "arrow.clockwise")
                }
                .disabled(!canFetchModels || loadingModels)
                .controlSize(.small)
            }

            if !canFetchModels {
                modelCredentialHint
            } else {
                ScrollView(.vertical, showsIndicators: availableModels.count > 4) {
                    ModelOptionPicker(
                        options: availableModels,
                        selectedID: $model.onboardingModelID,
                        loading: loadingModels,
                        activeModelID: activeModelID
                    )
                    .padding(4)
                }
                .frame(height: 170)
                .background(Color(nsColor: .controlBackgroundColor).opacity(0.32), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
                .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.line.opacity(0.54), lineWidth: 1))
            }

            HStack(alignment: .top, spacing: 12) {
                OnboardingMenuField(
                    title: model.text(.modelList),
                    placeholder: loadingModels ? model.text(.fetching) : model.text(.selectModel),
                    options: availableModels.map(\.id),
                    selection: $model.onboardingModelID
                )
                OnboardingField(title: model.text(.customModelID), placeholder: "gpt-5.4 / claude-sonnet-4-5", text: $model.onboardingModelID)
            }
        }
        .onAppear {
            guard !loaded else { return }
            loaded = true
            Task { await prepareModels() }
        }
        .onChange(of: model.onboardingProviderID) { _ in
            applyProviderDefaults(onlyWhenEmpty: false)
            Task { await loadLiveModelsIfNeeded() }
        }
    }

    private func prepareModels() async {
        await model.refreshProviderCatalogForOnboarding()
        applyProviderDefaults(onlyWhenEmpty: true)
        await loadLiveModelsIfNeeded()
    }

    private func loadLiveModels(force: Bool = false) async {
        let providerID = model.onboardingProviderID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !providerID.isEmpty, canFetchModels else { return }
        loadingModels = true
        let rows = await model.discoverProviderModels(providerID: providerID, baseURL: model.onboardingBaseURL, apiKey: model.onboardingAPIKey)
        if !rows.isEmpty {
            discoveredModels[providerID] = rows
            if model.onboardingModelID.isEmpty || !rows.contains(where: { $0.id == model.onboardingModelID }) {
                model.onboardingModelID = rows.first?.id ?? model.onboardingModelID
            }
        }
        loadingModels = false
    }

    private func loadLiveModelsIfNeeded() async {
        let providerID = model.onboardingProviderID.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !providerID.isEmpty,
              canFetchModels,
              discoveredModels[providerID] == nil else { return }
        await loadLiveModels(force: false)
    }

    private var selectedOption: ProviderOption? {
        providerChoices.first(where: { $0.id == model.onboardingProviderID })
    }

    private var availableModels: [ProviderModelOption] {
        prioritizedModelOptions(
            discovered: discoveredModels[model.onboardingProviderID],
            catalog: selectedOption?.models ?? [],
            selectedID: model.onboardingModelID,
            activeID: activeModelID
        )
    }

    private var providerChoices: [ProviderOption] {
        onboardingProviderChoices(snapshotOptions: model.snapshot.providerOptions, language: model.appLanguage)
    }

    private var activeModelID: String {
        model.snapshot.providerID == model.onboardingProviderID ? model.snapshot.providerModelID : ""
    }

    private var providerAlreadyUsable: Bool {
        guard let option = selectedOption else { return false }
        return option.active || option.connected || option.storedKeyCount > 0
    }

    private var canFetchModels: Bool {
        guard let option = selectedOption else { return false }
        if providerAlreadyUsable { return true }
        let hasKey = !model.onboardingAPIKey.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        if option.id == "openai-compatible" {
            return hasKey && !model.onboardingBaseURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
        }
        let authKind = option.authKind.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if authKind == "none" || authKind == "no_auth" || authKind == "local" {
            return true
        }
        return hasKey
    }

    private var modelCredentialHint: some View {
        HStack(alignment: .top, spacing: 12) {
            Image(systemName: "key.horizontal")
                .font(.callout.weight(.semibold))
                .foregroundStyle(ElephantTheme.orange)
                .frame(width: 34, height: 34)
                .background(ElephantTheme.orange.opacity(0.10), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
            VStack(alignment: .leading, spacing: 4) {
                Text(localizedYouText(model.appLanguage, en: "Add credentials first", zh: "先填写凭证", fr: "Ajoutez d'abord les identifiants", de: "Zuerst Zugangsdaten eintragen"))
                    .font(.callout.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(localizedYouText(model.appLanguage, en: "Go back one step, add the key or endpoint, then Elephant can fetch the real model list.", zh: "回到上一步填写 key 或 endpoint 后，Elephant 才会拉取真实模型列表。", fr: "Revenez à l'étape précédente pour ajouter la clé ou l'endpoint.", de: "Gehe einen Schritt zurück und trage Key oder Endpoint ein."))
                    .font(.caption)
                    .foregroundStyle(ElephantTheme.muted)
                    .fixedSize(horizontal: false, vertical: true)
            }
            Spacer(minLength: 0)
        }
        .padding(14)
        .frame(maxWidth: .infinity, minHeight: 120, alignment: .topLeading)
        .background(ElephantTheme.orange.opacity(0.07), in: RoundedRectangle(cornerRadius: 8, style: .continuous))
        .overlay(RoundedRectangle(cornerRadius: 8, style: .continuous).stroke(ElephantTheme.orange.opacity(0.16), lineWidth: 1))
    }

    private func applyProviderDefaults(onlyWhenEmpty: Bool) {
        guard let option = selectedOption else { return }
        if providerAlreadyUsable {
            if !onlyWhenEmpty || model.onboardingModelID.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
                model.onboardingModelID = option.defaultModel.isEmpty ? (option.models.first?.id ?? model.onboardingModelID) : option.defaultModel
            }
        } else if !onlyWhenEmpty {
            model.onboardingModelID = ""
        }
        if !onlyWhenEmpty || model.onboardingBaseURL.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            model.onboardingBaseURL = option.defaultBaseURL
        }
    }

    private func prioritizedModelOptions(
        discovered: [ProviderModelOption]?,
        catalog: [ProviderModelOption],
        selectedID: String,
        activeID: String
    ) -> [ProviderModelOption] {
        var seen = Set<String>()
        var rows: [ProviderModelOption] = []

        func push(_ option: ProviderModelOption) {
            let id = option.id.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !id.isEmpty, !seen.contains(id) else { return }
            seen.insert(id)
            rows.append(option)
        }

        if !activeID.isEmpty {
            if let active = (discovered ?? []).first(where: { $0.id == activeID }) ?? catalog.first(where: { $0.id == activeID }) {
                push(active)
            } else {
                push(ProviderModelOption(id: activeID, label: activeID, source: "active", contextWindowTokens: 0, maxOutputTokens: 0))
            }
        }
        (discovered ?? []).forEach(push)
        catalog.forEach(push)
        if !selectedID.isEmpty, !seen.contains(selectedID) {
            push(ProviderModelOption(id: selectedID, label: selectedID, source: "custom", contextWindowTokens: 0, maxOutputTokens: 0))
        }

        return rows.sorted { left, right in
            let leftRank = modelOptionRank(left, selectedID: selectedID, activeID: activeID)
            let rightRank = modelOptionRank(right, selectedID: selectedID, activeID: activeID)
            if leftRank != rightRank { return leftRank < rightRank }
            return left.id.localizedCaseInsensitiveCompare(right.id) == .orderedAscending
        }
    }

    private func modelOptionRank(_ option: ProviderModelOption, selectedID: String, activeID: String) -> Int {
        if !activeID.isEmpty, option.id == activeID { return 0 }
        let source = option.source.lowercased()
        if source.contains("endpoint") || source.contains("discovered") || source.contains("live") { return 1 }
        if !selectedID.isEmpty, option.id == selectedID { return 2 }
        if source.contains("catalog") { return 3 }
        if source.contains("default") { return 4 }
        return 5
    }
}

