}

struct OnboardingLearningLivePanel: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var job: LearningJobItem?
    var statusText: String

    var body: some View {
        VStack(spacing: 12) {
            OnboardingLearningAnimation()
                .frame(width: 260, height: 156)
                .accessibilityHidden(true)

            VStack(spacing: 6) {
                Text(model.text(.learningTitle))
                    .font(.system(size: 22, weight: .semibold))
                    .foregroundStyle(ElephantTheme.ink)
                    .multilineTextAlignment(.center)
                Text(panelSubtitle)
                    .font(.callout)
                    .foregroundStyle(ElephantTheme.muted)
                    .multilineTextAlignment(.center)
                    .lineLimit(2)
                    .fixedSize(horizontal: false, vertical: true)
                    .frame(maxWidth: 520)
            }

            HStack(alignment: .center, spacing: 14) {
                ZStack {
                    Circle()
                        .fill(statusTint.opacity(0.13))
                    if isActive {
                        ProgressView()
                            .controlSize(.small)
                    } else {
                        Image(systemName: statusSymbol)
                            .font(.caption.weight(.bold))
                            .foregroundStyle(statusTint)
                    }
                }
                .frame(width: 36, height: 36)

                VStack(alignment: .leading, spacing: 4) {
                    Text(stageTitle)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                    Text(stageDetail)
                        .font(.caption)
                        .foregroundStyle(ElephantTheme.muted)
                        .lineLimit(2)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer(minLength: 0)
                Pill(text: statusLabel, tint: statusTint)
            }
            .frame(maxWidth: 590, minHeight: 52, alignment: .leading)

            Divider()
                .frame(maxWidth: 590)
                .opacity(0.55)

            OnboardingLearningToolTimeline(job: job, statusText: statusText)
                .frame(maxWidth: 590)
        }
        .padding(.horizontal, 18)
        .padding(.vertical, 2)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .animation(reduceMotion ? nil : .easeOut(duration: 0.18), value: activityKey)
    }

    private var activityKey: String {
        "\(job?.status ?? "")|\(job?.progressStage ?? "")|\(job?.progressDetail ?? "")|\(job?.modelProgress.text ?? "")|\(latestToolItem?.id ?? "")"
    }

    private var modelProgress: LearningModelProgress {
        job?.modelProgress ?? .empty
    }

    private var latestToolItem: OnboardingLearningToolTraceItem? {
        guard let events = job?.toolProgress.events else { return nil }
        for event in events.reversed() {
            let phase = resolvedToolPhase(event)
            guard !isHiddenToolPhase(phase) else { continue }
            return OnboardingLearningToolTraceItem(
                toolID: event.toolID,
                phase: phase,
                name: toolDisplayName(event.toolID),
                detail: toolPhaseDisplayName(phase),
                preview: event.preview,
                symbol: toolPhaseSymbol(phase),
                tint: toolPhaseTint(phase)
            )
        }
        return nil
    }

    private var panelSubtitle: String {
        localizedYouText(model.appLanguage, en: "This usually takes 3 to 5 minutes.", zh: "需要 3 到 5 分钟", fr: "Cela prend généralement 3 à 5 minutes.", de: "Das dauert meist 3 bis 5 Minuten.")
    }

    private var stageTitle: String {
        if !modelProgress.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return localizedYouText(model.appLanguage, en: "Elephant is writing", zh: "Elephant 正在整理", fr: "Elephant écrit", de: "Elephant schreibt")
        }
        if let latestToolItem {
            return latestToolItem.name
        }
        let stage = (job?.progressStage ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        switch stage {
        case "queued":
            return localizedYouText(model.appLanguage, en: "Queued for learning", zh: "学习任务已排队", fr: "Tâche en file", de: "Lernjob wartet")
        case "agent_running", "tool_running":
            return localizedYouText(model.appLanguage, en: "Learning from your answers", zh: "正在学习你的回答", fr: "Apprentissage en cours", de: "Lernt aus deinen Antworten")
        case "completed":
            return localizedYouText(model.appLanguage, en: "Learning pass completed", zh: "学习过程已完成", fr: "Passage terminé", de: "Lernlauf abgeschlossen")
        case "failed":
            return localizedYouText(model.appLanguage, en: "Needs attention", zh: "需要处理", fr: "À vérifier", de: "Benötigt Prüfung")
        default:
            return localizedYouText(model.appLanguage, en: "Preparing your first memory", zh: "正在准备第一版记忆", fr: "Préparation de la première mémoire", de: "Erste Erinnerung wird vorbereitet")
        }
    }

    private var stageDetail: String {
        if !modelProgress.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return modelProgress.text
        }
        if let latestToolItem {
            let preview = latestToolItem.preview.trimmingCharacters(in: .whitespacesAndNewlines)
            return preview.isEmpty ? latestToolItem.detail : "\(latestToolItem.detail) · \(preview)"
        }
        let detail = cleanProgress(job?.progressDetail ?? "")
        return detail.isEmpty ? statusText : detail
    }

    private var statusLabel: String {
        guard let job else {
            return localizedYouText(model.appLanguage, en: "preparing", zh: "准备中", fr: "préparation", de: "wird vorbereitet")
        }
        return localizedRuntimeStatus(job.status, language: model.appLanguage)
    }

    private var isActive: Bool {
        let status = (job?.status ?? "").lowercased()
        return !status.contains("completed") && !status.contains("failed") && !status.contains("cancel")
    }

    private var statusSymbol: String {
        let status = (job?.status ?? "").lowercased()
        if status.contains("completed") { return "checkmark.circle.fill" }
        if status.contains("failed") || status.contains("cancel") { return "exclamationmark.triangle.fill" }
        return "sparkles"
    }

    private var statusTint: Color {
        let status = (job?.status ?? "").lowercased()
        if status.contains("completed") { return ElephantTheme.green }
        if status.contains("failed") || status.contains("cancel") { return ElephantTheme.orange }
        return ElephantTheme.accent
    }

    private func resolvedToolPhase(_ event: LearningToolCallEvent) -> String {
        guard let progress = job?.toolProgress else { return event.phase }
        if ["requested", "execution.started", "execution.completed", "execution.failed"].contains(event.phase) {
            return event.phase
        }
        if progress.failedToolIDs.contains(event.toolID) {
            return "execution.failed"
        }
        if progress.completedToolIDs.contains(event.toolID) {
            return "execution.completed"
        }
        if progress.activeToolID == event.toolID {
            return "execution.started"
        }
        return event.phase
    }

    private func isHiddenToolPhase(_ phase: String) -> Bool {
        let normalized = phase.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return normalized.contains("failed") || normalized.contains("error") || normalized.contains("cancel")
    }

    private func toolDisplayName(_ tool: String) -> String {
        switch tool.replacingOccurrences(of: "tool.", with: "") {
        case "personal_model.search":
            return localizedYouText(model.appLanguage, en: "Reading your model", zh: "读取个人模型", fr: "Lire le modèle", de: "Modell lesen")
        case "personal_model.update":
            return localizedYouText(model.appLanguage, en: "Updating memory", zh: "更新记忆", fr: "Mettre à jour", de: "Gedächtnis aktualisieren")
        case "personal_model.questions":
            return localizedYouText(model.appLanguage, en: "Refining questions", zh: "整理问题", fr: "Questions", de: "Fragen")
        case "skill.list":
            return localizedYouText(model.appLanguage, en: "Reading skills", zh: "读取技能", fr: "Lister les compétences", de: "Fähigkeiten lesen")
        case "skill.view":
            return localizedYouText(model.appLanguage, en: "Inspecting a skill", zh: "查看技能", fr: "Voir une compétence", de: "Fähigkeit ansehen")
        case "web.read", "web.extract", "web.search":
            return localizedYouText(model.appLanguage, en: "Reading links", zh: "读取链接", fr: "Lire liens", de: "Links lesen")
        default:
            return tool.replacingOccurrences(of: "tool.", with: "")
        }
    }

    private func toolPhaseDisplayName(_ phase: String) -> String {
        switch phase {
        case "requested":
            return localizedYouText(model.appLanguage, en: "requested", zh: "已发起", fr: "demandé", de: "angefordert")
        case "execution.completed":
            return localizedYouText(model.appLanguage, en: "completed", zh: "已完成", fr: "terminé", de: "fertig")
        case "execution.failed":
            return localizedYouText(model.appLanguage, en: "failed", zh: "失败", fr: "échec", de: "fehlgeschlagen")
        default:
            return localizedYouText(model.appLanguage, en: "running", zh: "正在执行", fr: "en cours", de: "läuft")
        }
    }

    private func toolPhaseSymbol(_ phase: String) -> String {
        switch phase {
        case "requested":
            return "circle.dotted"
        case "execution.completed":
            return "checkmark.circle.fill"
        case "execution.failed":
            return "exclamationmark.triangle.fill"
        default:
            return "dot.radiowaves.left.and.right"
        }
    }

    private func toolPhaseTint(_ phase: String) -> Color {
        switch phase {
        case "execution.completed":
            return ElephantTheme.green
        case "execution.failed":
            return ElephantTheme.orange
        default:
            return ElephantTheme.accent
        }
    }

    private func cleanProgress(_ value: String) -> String {
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if normalized.isEmpty {
            return ""
        }
        if normalized.hasPrefix("tool_event_v1=") || normalized.hasPrefix("learning_event_v1=") {
            return localizedYouText(model.appLanguage, en: "Checking memory, questions, skills, and links.", zh: "正在检查记忆、问题、技能和链接。", fr: "Vérifie mémoire, questions, compétences et liens.", de: "Prüft Gedächtnis, Fragen, Fähigkeiten und Links.")
        }
        if normalized.contains("reflect agent running") || normalized.contains("features=pm") {
            return localizedYouText(model.appLanguage, en: "Turning your answers into long-term memory.", zh: "正在把你的回答整理成长期记忆。", fr: "Transforme vos réponses en mémoire durable.", de: "Macht aus deinen Antworten Langzeitgedächtnis.")
        }
        if normalized.contains("starting background learning agent") {
            return localizedYouText(model.appLanguage, en: "Turning your setup answers into the first version of memory.", zh: "正在把刚填写的信息整理成第一版记忆。", fr: "Transforme vos réponses en première mémoire.", de: "Macht aus deinen Antworten die erste Erinnerung.")
        }
        if normalized.contains("queued for background learning") || normalized == "queued" {
            return localizedYouText(model.appLanguage, en: "Queued for background learning.", zh: "学习任务已排队，会在后台继续。", fr: "En file pour l'apprentissage en arrière-plan.", de: "Für Hintergrundlernen eingereiht.")
        }
        return value
            .replacingOccurrences(of: "tool_event=", with: "")
            .replacingOccurrences(of: "called=", with: "called ")
            .replacingOccurrences(of: "tool.", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

struct OnboardingLearningToolTimeline: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var job: LearningJobItem?
    var statusText: String

    var body: some View {
        VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .center, spacing: 9) {
                Image(systemName: "waveform.path.ecg")
                    .font(.caption.weight(.bold))
                    .foregroundStyle(statusTint)
                    .frame(width: 18, height: 18)
                Text(statusLine)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(ElephantTheme.ink)
                    .lineLimit(1)
                    .truncationMode(.middle)
                Spacer(minLength: 0)
            }
            .padding(.horizontal, 2)
            .padding(.vertical, 2)

            ScrollViewReader { proxy in
                ScrollView(.vertical) {
                    VStack(spacing: 8) {
                        ForEach(feedMessages) { message in
                            OnboardingLearningMessageBubble(message: message)
                                .id(message.id)
                                .transition(toolSlotTransition)
                        }
                        Color.clear
                            .frame(height: 1)
                            .id("activity-bottom")
                    }
                }
                .scrollIndicators(.hidden)
                .onAppear { scrollActivityToBottom(proxy) }
                .onChange(of: activityScrollKey) { _ in
                    scrollActivityToBottom(proxy)
                }
            }
            .frame(height: liveContentHeight, alignment: .top)
            .frame(maxWidth: .infinity, alignment: .top)
            .clipped()
        }
        .frame(maxWidth: .infinity, minHeight: timelineHeight, maxHeight: timelineHeight, alignment: .top)
        .clipped()
        .animation(toolSlotAnimation, value: activityScrollKey)
    }

    private var modelProgress: LearningModelProgress {
        job?.modelProgress ?? .empty
    }

    private var statusLine: String {
        let title = stageTitle.trimmingCharacters(in: .whitespacesAndNewlines)
        let detail = stageDetail.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !detail.isEmpty, detail != title else { return title }
        return "\(title) · \(detail)"
    }

    private var liveContentHeight: CGFloat { 120 }

    private var timelineHeight: CGFloat { 156 }

    private var activityScrollKey: String {
        "\(feedMessages.map(\.id).joined(separator: "|"))|\(modelProgress.text)|\(job?.progressStage ?? "")|\(job?.progressDetail ?? "")"
    }

    private var feedMessages: [OnboardingLearningFeedMessage] {
        var messages: [OnboardingLearningFeedMessage] = toolTimelineItems.suffix(6).map { item in
            let isResult = item.phase == "execution.completed"
            let preview = item.preview
                .replacingOccurrences(of: "tool.", with: "")
                .replacingOccurrences(of: "_", with: " ")
                .trimmingCharacters(in: .whitespacesAndNewlines)
            let detail = preview.isEmpty ? item.detail : preview
            return OnboardingLearningFeedMessage(
                id: "tool-\(item.id)",
                title: isResult
                    ? localizedYouText(model.appLanguage, en: "Result", zh: "执行结果", fr: "Résultat", de: "Ergebnis")
                    : item.name,
                detail: detail,
                symbol: isResult ? "arrow.down.left.circle.fill" : item.symbol,
                tint: isResult ? ElephantTheme.green : item.tint,
                outgoing: !isResult,
                active: isActive && !isResult && item.id == latestToolItem?.id
            )
        }

        if !modelProgress.isEmpty {
            messages.append(
                OnboardingLearningFeedMessage(
                    id: "model-\(modelProgress.text.hashValue)",
                    title: localizedYouText(model.appLanguage, en: "Elephant", zh: "Elephant", fr: "Elephant", de: "Elephant"),
                    detail: modelProgress.text,
                    symbol: "sparkles",
                    tint: ElephantTheme.accent,
                    outgoing: true,
                    active: isActive
                )
            )
        }

        if messages.isEmpty {
            messages.append(
                OnboardingLearningFeedMessage(
                    id: "waiting",
                    title: localizedYouText(model.appLanguage, en: "Waiting", zh: "等待动态", fr: "En attente", de: "Wartet"),
                    detail: statusText,
                    symbol: "clock",
                    tint: statusTint,
                    outgoing: false,
                    active: isActive
                )
            )
        }

        return Array(messages.suffix(4))
    }

    private func scrollActivityToBottom(_ proxy: ScrollViewProxy) {
        if reduceMotion {
            proxy.scrollTo("activity-bottom", anchor: .bottom)
        } else {
            withAnimation(.easeOut(duration: 0.22)) {
                proxy.scrollTo("activity-bottom", anchor: .bottom)
            }
        }
    }

    private var statusLabel: String {
        guard let job else {
            return localizedYouText(model.appLanguage, en: "preparing", zh: "准备中", fr: "préparation", de: "wird vorbereitet")
        }
        return localizedRuntimeStatus(job.status, language: model.appLanguage)
    }

    private var isActive: Bool {
        let status = (job?.status ?? "").lowercased()
        return !status.contains("completed") && !status.contains("failed") && !status.contains("cancel")
    }

    private var stageTitle: String {
        let stage = (job?.progressStage ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        switch stage {
        case "queued":
            return localizedYouText(model.appLanguage, en: "Queued for learning", zh: "学习任务已排队", fr: "Tâche en file", de: "Lernjob wartet")
        case "tool_requested":
            return localizedYouText(model.appLanguage, en: "Next step started", zh: "下一步已开始", fr: "Étape suivante lancée", de: "Nächster Schritt gestartet")
        case "starting":
            return localizedYouText(model.appLanguage, en: "Elephant is getting ready", zh: "Elephant 正在准备", fr: "Elephant se prépare", de: "Elephant bereitet sich vor")
        case "agent_starting":
            return localizedYouText(model.appLanguage, en: "Starting the learning pass", zh: "正在启动学习过程", fr: "Démarrage du passage", de: "Lernlauf startet")
        case "agent_running":
            return localizedYouText(model.appLanguage, en: "Reading and updating the model", zh: "正在读取并更新模型", fr: "Lecture et mise à jour", de: "Liest und aktualisiert")
        case "tool_running":
            return localizedYouText(model.appLanguage, en: "Working through your answers", zh: "正在整理你的回答", fr: "Traitement de vos réponses", de: "Verarbeitet deine Antworten")
        case "tool_completed":
            return localizedYouText(model.appLanguage, en: "One step completed", zh: "已完成一步", fr: "Une étape terminée", de: "Ein Schritt abgeschlossen")
        case "tool_failed":
            return localizedYouText(model.appLanguage, en: "Continuing the build", zh: "继续整理信息", fr: "Construction en cours", de: "Aufbau läuft weiter")
        case "result_written":
            return localizedYouText(model.appLanguage, en: "Writing the learning result", zh: "正在写入学习结果", fr: "Écriture du résultat", de: "Schreibt Ergebnis")
        case "completed":
            return localizedYouText(model.appLanguage, en: "Learning pass completed", zh: "学习过程已完成", fr: "Passage terminé", de: "Lernlauf abgeschlossen")
        case "failed":
            return localizedYouText(model.appLanguage, en: "Needs attention", zh: "需要处理", fr: "À vérifier", de: "Benötigt Prüfung")
        default:
            return localizedYouText(model.appLanguage, en: "Preparing the learning job", zh: "正在准备学习任务", fr: "Préparation de la tâche", de: "Lernjob wird vorbereitet")
        }
    }

    private var stageDetail: String {
        let detail = cleanProgress(job?.progressDetail ?? "")
        if isToolProgressDetail(job?.progressDetail ?? ""), let latest = latestToolItem {
            let suffix = latest.preview.isEmpty ? "" : " · \(latest.preview)"
            return "\(latest.name) · \(latest.detail)\(suffix)"
        }
        if isToolProgressDetail(job?.progressDetail ?? ""), !modelProgress.isEmpty {
            return localizedYouText(model.appLanguage, en: "Receiving model reply", zh: "正在接收模型回复", fr: "Réponse du modèle en cours", de: "Modellantwort wird empfangen")
        }
        return detail.isEmpty ? statusText : detail
    }

    private var latestToolItem: OnboardingLearningToolTraceItem? {
        toolTimelineItems.last
    }

    private var toolTimelineItems: [OnboardingLearningToolTraceItem] {
        guard let progress = job?.toolProgress else { return [] }
        var rows: [OnboardingLearningToolTraceItem] = []
        var seen = Set<String>()
        for event in progress.events {
            let toolID = event.toolID.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !toolID.isEmpty else { continue }
            let phase = resolvedToolPhase(event, progress: progress)
            guard !isHiddenToolPhase(phase) else { continue }
            let key = "\(toolID)-\(phase)-\(event.preview)"
            guard !seen.contains(key) else { continue }
            seen.insert(key)
            rows.append(
                OnboardingLearningToolTraceItem(
                    toolID: toolID,
                    phase: phase,
                    name: toolDisplayName(toolID),
                    detail: toolPhaseDisplayName(phase),
                    preview: event.preview,
                    symbol: toolPhaseSymbol(phase),
                    tint: toolPhaseTint(phase)
                )
            )
        }
        return rows
    }

    private var toolSlotTransition: AnyTransition {
        if reduceMotion {
            return .opacity
        }
        return .asymmetric(
            insertion: .move(edge: .bottom).combined(with: .opacity),
            removal: .move(edge: .top).combined(with: .opacity)
        )
    }

    private var toolSlotAnimation: Animation? {
        reduceMotion
            ? .easeOut(duration: 0.12)
            : .spring(response: 0.42, dampingFraction: 0.88, blendDuration: 0.08)
    }

    private func toolDisplayName(_ tool: String) -> String {
        switch tool.replacingOccurrences(of: "tool.", with: "") {
        case "personal_model.search":
            return localizedYouText(model.appLanguage, en: "Review memory", zh: "回看记忆", fr: "Relire la mémoire", de: "Erinnerung prüfen")
        case "personal_model.update":
            return localizedYouText(model.appLanguage, en: "Save memory", zh: "写入记忆", fr: "Enregistrer la mémoire", de: "Erinnerung speichern")
        case "personal_model.questions":
            return localizedYouText(model.appLanguage, en: "Shape questions", zh: "整理问题", fr: "Préparer les questions", de: "Fragen vorbereiten")
        case "skill.list":
            return localizedYouText(model.appLanguage, en: "Review abilities", zh: "查看能力", fr: "Revoir les capacités", de: "Fähigkeiten prüfen")
        case "skill.view":
            return localizedYouText(model.appLanguage, en: "Open ability", zh: "查看能力", fr: "Ouvrir la capacité", de: "Fähigkeit öffnen")
        case "web.read", "web.extract", "web.search":
            return localizedYouText(model.appLanguage, en: "Read links", zh: "读取链接", fr: "Lire liens", de: "Links lesen")
        default:
            return tool.replacingOccurrences(of: "tool.", with: "")
        }
    }

    private func resolvedToolPhase(_ event: LearningToolCallEvent, progress: LearningToolCallProgress) -> String {
        if ["requested", "execution.started", "execution.completed", "execution.failed"].contains(event.phase) {
            return event.phase
        }
        if progress.failedToolIDs.contains(event.toolID) {
            return "execution.failed"
        }
        if progress.completedToolIDs.contains(event.toolID) {
            return "execution.completed"
        }
        if progress.activeToolID == event.toolID {
            return "execution.started"
        }
        return event.phase
    }

    private func isHiddenToolPhase(_ phase: String) -> Bool {
        let normalized = phase.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        return normalized.contains("failed") || normalized.contains("error") || normalized.contains("cancel")
    }

    private func toolPhaseDisplayName(_ phase: String) -> String {
        switch phase {
        case "requested":
            return localizedYouText(model.appLanguage, en: "requested", zh: "已发起", fr: "demandé", de: "angefordert")
        case "execution.completed":
            return localizedYouText(model.appLanguage, en: "completed", zh: "已完成", fr: "terminé", de: "fertig")
        case "execution.failed":
            return localizedYouText(model.appLanguage, en: "failed", zh: "失败", fr: "échec", de: "fehlgeschlagen")
        default:
            return localizedYouText(model.appLanguage, en: "running", zh: "正在执行", fr: "en cours", de: "läuft")
        }
    }

    private func toolPhaseSymbol(_ phase: String) -> String {
        switch phase {
        case "requested":
            return "circle.dotted"
        case "execution.completed":
            return "checkmark.circle.fill"
        case "execution.failed":
            return "exclamationmark.triangle.fill"
        default:
            return "dot.radiowaves.left.and.right"
        }
    }

    private func toolPhaseTint(_ phase: String) -> Color {
        switch phase {
        case "execution.completed":
            return ElephantTheme.green
        case "execution.failed":
            return ElephantTheme.orange
        default:
            return ElephantTheme.accent
        }
    }

    private var statusTint: Color {
        let status = (job?.status ?? "").lowercased()
        if status.contains("completed") { return ElephantTheme.green }
        if status.contains("failed") || status.contains("cancel") { return ElephantTheme.orange }
        return ElephantTheme.accent
    }

    private func cleanProgress(_ value: String) -> String {
        let normalized = value.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if normalized.isEmpty {
            return ""
        }
        if isToolProgressDetail(value) {
            return localizedYouText(model.appLanguage, en: "Following each step as it happens.", zh: "正在跟随每一步进展。", fr: "Suit chaque étape en direct.", de: "Folgt jedem Schritt live.")
        }
        if normalized.contains("reflect agent running") || normalized.contains("features=pm") {
            return localizedYouText(model.appLanguage, en: "Turning your answers into long-term memory.", zh: "正在把你的回答整理成长期记忆。", fr: "Transforme vos réponses en mémoire durable.", de: "Macht aus deinen Antworten Langzeitgedächtnis.")
        }
        if normalized.contains("starting background learning agent") {
            return localizedYouText(model.appLanguage, en: "Turning your setup answers into the first version of memory.", zh: "正在把刚填写的信息整理成第一版记忆。", fr: "Transforme vos réponses en première mémoire.", de: "Macht aus deinen Antworten die erste Erinnerung.")
        }
        if normalized.contains("tool_event") || normalized.contains("called=") {
            return localizedYouText(model.appLanguage, en: "Checking memory, questions, abilities, and links.", zh: "正在检查记忆、问题、能力和链接。", fr: "Vérifie mémoire, questions, capacités et liens.", de: "Prüft Erinnerung, Fragen, Fähigkeiten und Links.")
        }
        return value
            .replacingOccurrences(of: "tool_event=", with: "")
            .replacingOccurrences(of: "called=", with: "called ")
            .replacingOccurrences(of: "tool.", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
    }

    private func isToolProgressDetail(_ value: String) -> Bool {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.hasPrefix("tool_event_v1=") || trimmed.hasPrefix("learning_event_v1=")
    }
}

struct OnboardingLearningToolTraceItem: Identifiable {
    var id: String { "\(toolID)-\(phase)-\(preview)" }
    var toolID: String
    var phase: String
    var name: String
    var detail: String
    var preview: String = ""
    var symbol: String
    var tint: Color
}

struct OnboardingLearningFeedMessage: Identifiable {
    var id: String
    var title: String
    var detail: String
    var symbol: String
    var tint: Color
    var outgoing: Bool
    var active: Bool
}

struct OnboardingLearningMessageBubble: View {
    var message: OnboardingLearningFeedMessage

    var body: some View {
        HStack(alignment: .bottom, spacing: 8) {
            if message.outgoing {
                Spacer(minLength: 58)
            }

            HStack(alignment: .top, spacing: 8) {
                ZStack {
                    Circle()
                        .fill(message.tint.opacity(message.outgoing ? 0.14 : 0.12))
                    if message.active {
                        ProgressView()
                            .controlSize(.small)
                            .frame(width: 14, height: 14)
                    } else {
                        Image(systemName: message.symbol)
                            .font(.caption2.weight(.bold))
                            .foregroundStyle(message.tint)
                    }
                }
                .frame(width: 24, height: 24)

                VStack(alignment: .leading, spacing: 2) {
                    Text(message.title)
                        .font(.caption2.weight(.bold))
                        .foregroundStyle(message.outgoing ? ElephantTheme.accent : ElephantTheme.ink)
                        .lineLimit(1)
                    Text(message.detail)
                        .font(.caption)
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(2)
                        .fixedSize(horizontal: false, vertical: true)
                }
            }
            .padding(.horizontal, 10)
            .padding(.vertical, 8)
            .frame(maxWidth: 430, alignment: .leading)
            .background(
                message.outgoing
                    ? ElephantTheme.accent.opacity(0.095)
                    : Color(nsColor: .textBackgroundColor).opacity(0.62),
                in: RoundedRectangle(cornerRadius: 11, style: .continuous)
            )
            .overlay(
                RoundedRectangle(cornerRadius: 11, style: .continuous)
                    .stroke(message.tint.opacity(message.outgoing ? 0.18 : 0.14), lineWidth: 1)
            )

            if !message.outgoing {
                Spacer(minLength: 58)
            }
        }
        .frame(maxWidth: .infinity, alignment: message.outgoing ? .trailing : .leading)
    }
}

