struct OnboardingLearningModelLiveSlot: View {
    @EnvironmentObject private var model: ElephantAppModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    var progress: LearningModelProgress
    @State private var pulse = false

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 8) {
                ZStack {
                    Circle()
                        .fill(ElephantTheme.accent.opacity(0.12))
                    Circle()
                        .fill(ElephantTheme.accent.opacity(pulse ? 0.20 : 0.42))
                        .frame(width: 7, height: 7)
                }
                .frame(width: 28, height: 28)

                Text(localizedYouText(model.appLanguage, en: "Elephant", zh: "Elephant", fr: "Elephant", de: "Elephant"))
                    .font(.caption.weight(.bold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(localizedYouText(model.appLanguage, en: "writing", zh: "正在回复", fr: "écrit", de: "schreibt"))
                    .font(.caption2.weight(.semibold))
                    .foregroundStyle(ElephantTheme.accent)
                    .padding(.horizontal, 7)
                    .padding(.vertical, 3)
                    .background(ElephantTheme.accent.opacity(0.10), in: Capsule())
                Spacer(minLength: 0)
            }

            Text(progress.text)
                .font(.callout)
                .foregroundStyle(ElephantTheme.ink)
                .fixedSize(horizontal: false, vertical: true)
                .textSelection(.enabled)
                .animation(reduceMotion ? nil : .easeOut(duration: 0.16), value: progress.text)
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 6)
        .frame(maxWidth: .infinity, minHeight: 70, alignment: .topLeading)
        .onAppear {
            guard !reduceMotion else { return }
            pulse = true
        }
        .animation(
            reduceMotion ? nil : .easeInOut(duration: 0.75).repeatForever(autoreverses: true),
            value: pulse
        )
    }
}

struct OnboardingLearningToolLiveSlot: View {
    @EnvironmentObject private var model: ElephantAppModel
    var item: OnboardingLearningToolTraceItem

    var body: some View {
        HStack(alignment: .center, spacing: 11) {
            ZStack {
                Circle()
                    .fill(item.tint.opacity(0.12))
                Image(systemName: item.symbol)
                    .font(.caption.weight(.bold))
                    .foregroundStyle(item.tint)
            }
            .frame(width: 34, height: 34)

            VStack(alignment: .leading, spacing: 3) {
                HStack(alignment: .firstTextBaseline, spacing: 7) {
                    Text(slotEyebrow)
                        .font(.caption2.weight(.bold))
                        .foregroundStyle(item.tint)
                        .lineLimit(1)
                    Text(item.name)
                        .font(.caption.weight(.bold))
                        .foregroundStyle(ElephantTheme.ink)
                        .lineLimit(1)
                }
                Text(metaLine)
                    .font(.caption2.monospaced())
                    .foregroundStyle(ElephantTheme.muted)
                    .lineLimit(1)
                    .truncationMode(.middle)
            }
            Spacer(minLength: 8)
            Text(item.detail)
                .font(.caption2.weight(.bold))
                .foregroundStyle(item.tint)
                .lineLimit(1)
                .padding(.horizontal, 8)
                .padding(.vertical, 4)
                .background(item.tint.opacity(0.10), in: Capsule())
        }
        .padding(.horizontal, 12)
        .frame(maxWidth: .infinity, minHeight: 62, alignment: .center)
    }

    private var slotEyebrow: String {
        switch item.phase {
        case "requested":
            return localizedYouText(model.appLanguage, en: "Started", zh: "已开始", fr: "Lancé", de: "Gestartet")
        case "execution.completed":
            return localizedYouText(model.appLanguage, en: "Latest step", zh: "最新进展", fr: "Dernière étape", de: "Letzter Schritt")
        case "execution.failed":
            return localizedYouText(model.appLanguage, en: "Needs attention", zh: "需要处理", fr: "À vérifier", de: "Prüfen")
        default:
            return localizedYouText(model.appLanguage, en: "Working", zh: "正在处理", fr: "En cours", de: "In Arbeit")
        }
    }

    private var metaLine: String {
        let preview = item.preview
            .replacingOccurrences(of: "tool.", with: "")
            .replacingOccurrences(of: "_", with: " ")
            .trimmingCharacters(in: .whitespacesAndNewlines)
        guard !preview.isEmpty else {
            return localizedYouText(model.appLanguage, en: "Working in the background", zh: "正在后台处理", fr: "Traitement en arrière-plan", de: "Arbeitet im Hintergrund")
        }
        return preview
    }
}

struct OnboardingLearningAnimation: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 60.0, paused: reduceMotion)) { timeline in
            Canvas { context, size in
                let seconds = reduceMotion ? 0 : timeline.date.timeIntervalSinceReferenceDate
                let center = CGPoint(x: size.width / 2, y: size.height / 2)
                let horizontalRadius = size.width * 0.38
                let verticalRadius = size.height * 0.36
                let palette = [ElephantTheme.accent, ElephantTheme.green, ElephantTheme.ember]

                let glowRect = CGRect(
                    x: center.x - horizontalRadius * 1.18,
                    y: center.y - verticalRadius * 1.18,
                    width: horizontalRadius * 2.36,
                    height: verticalRadius * 2.36
                )
                context.fill(
                    Path(ellipseIn: glowRect),
                    with: .color(ElephantTheme.accent.opacity(0.055))
                )

                var nodes: [CGPoint] = []
                for index in 0..<9 {
                    let lane = CGFloat(index % 3)
                    let nodeRadius = 0.62 + lane * 0.18
                    let angle = seconds * (0.26 + Double(index % 4) * 0.035) + Double(index) * .pi * 2 / 9
                    let point = CGPoint(
                        x: center.x + CGFloat(cos(angle)) * horizontalRadius * nodeRadius,
                        y: center.y + CGFloat(sin(angle)) * verticalRadius * nodeRadius
                    )
                    nodes.append(point)
                }

                for index in nodes.indices {
                    let next = nodes[(index + 3) % nodes.count]
                    var path = Path()
                    path.move(to: nodes[index])
                    path.addLine(to: next)
                    context.stroke(
                        path,
                        with: .color(ElephantTheme.accent.opacity(0.08)),
                        style: StrokeStyle(lineWidth: 1.2, lineCap: .round)
                    )
                }

                for index in 0..<4 {
                    let inset = CGFloat(index) * 20
                    let rect = CGRect(
                        x: center.x - horizontalRadius + inset / 2,
                        y: center.y - verticalRadius + inset / 3,
                        width: (horizontalRadius * 2) - inset,
                        height: (verticalRadius * 2) - inset * 0.66
                    )
                    context.stroke(
                        Path(ellipseIn: rect),
                        with: .color(palette[index % palette.count].opacity(0.18)),
                        style: StrokeStyle(lineWidth: 1.8, lineCap: .round, dash: [24, 18], dashPhase: CGFloat(seconds * 16 + Double(index) * 12))
                    )
                }

                for index in nodes.indices {
                    let pulse = 0.74 + 0.18 * sin(seconds * 1.25 + Double(index))
                    let size = CGFloat(6.5 + Double(index % 3) * 1.2) * CGFloat(pulse)
                    let rect = CGRect(x: nodes[index].x - size / 2, y: nodes[index].y - size / 2, width: size, height: size)
                    context.fill(Path(ellipseIn: rect), with: .color(palette[index % palette.count].opacity(0.78)))
                }

                let corePulse = CGFloat(1.0 + 0.06 * sin(seconds * 1.5))
                let coreSize = CGFloat(24) * corePulse
                let core = CGRect(x: center.x - coreSize / 2, y: center.y - coreSize / 2, width: coreSize, height: coreSize)
                context.fill(Path(ellipseIn: core.insetBy(dx: -12, dy: -12)), with: .color(ElephantTheme.accent.opacity(0.08)))
                context.fill(Path(ellipseIn: core), with: .color(ElephantTheme.accent.opacity(0.22)))
                context.fill(Path(ellipseIn: core.insetBy(dx: 7, dy: 7)), with: .color(ElephantTheme.accent.opacity(0.62)))
            }
        }
    }
}

struct OnboardingCelebrationStep: View {
    @EnvironmentObject private var model: ElephantAppModel

    var body: some View {
        VStack(spacing: 22) {
            Spacer(minLength: 12)
            OnboardingCelebrationAnimation()
                .frame(width: 190, height: 170)
            VStack(spacing: 8) {
                Text(model.text(.celebrationTitle))
                    .font(.system(size: 26, weight: .semibold))
                    .foregroundStyle(ElephantTheme.ink)
                Text(model.text(.celebrationSubtitle))
                    .font(.callout)
                    .foregroundStyle(ElephantTheme.muted)
                    .multilineTextAlignment(.center)
                    .frame(maxWidth: 520)
            }
            HStack(spacing: 12) {
                Pill(text: "\(model.snapshot.facts)", symbol: "checkmark.seal", tint: ElephantTheme.green)
                Pill(text: "\(model.snapshot.waitingQuestions)", symbol: "questionmark.bubble", tint: ElephantTheme.orange)
                if !model.onboardingInitReflectJobID.isEmpty {
                    Pill(text: "init", symbol: "brain.head.profile", tint: ElephantTheme.accent)
                }
            }
            Spacer(minLength: 0)
        }
        .frame(maxWidth: .infinity, minHeight: 350)
    }
}

struct OnboardingCelebrationAnimation: View {
    @Environment(\.accessibilityReduceMotion) private var reduceMotion

    var body: some View {
        TimelineView(.animation(minimumInterval: 1.0 / 60.0, paused: reduceMotion)) { timeline in
            Canvas { context, size in
                let seconds = reduceMotion ? 0 : timeline.date.timeIntervalSinceReferenceDate
                let palette = [ElephantTheme.accent, ElephantTheme.green, ElephantTheme.ember, ElephantTheme.mint]
                let center = CGPoint(x: size.width / 2, y: size.height / 2 + 8)

                for index in 0..<26 {
                    let angle = Double(index) / 26.0 * Double.pi * 2
                    let pulse = 0.72 + 0.18 * sin(seconds * 1.7 + Double(index))
                    let distance = CGFloat(42 + Double(index % 5) * 10) * CGFloat(pulse)
                    let point = CGPoint(x: center.x + CGFloat(cos(angle)) * distance, y: center.y + CGFloat(sin(angle)) * distance)
                    let rect = CGRect(x: point.x - 2.5, y: point.y - 2.5, width: 5, height: 5)
                    context.fill(Path(roundedRect: rect, cornerRadius: 1.5), with: .color(palette[index % palette.count].opacity(0.82)))
                }

                let circleRect = CGRect(x: center.x - 42, y: center.y - 42, width: 84, height: 84)
                context.fill(Path(ellipseIn: circleRect), with: .color(ElephantTheme.green.opacity(0.12)))
                context.stroke(Path(ellipseIn: circleRect), with: .color(ElephantTheme.green.opacity(0.32)), lineWidth: 2)
            }
            .overlay {
                Image(systemName: "checkmark.seal.fill")
                    .font(.system(size: 64, weight: .semibold))
                    .foregroundStyle(ElephantTheme.green)
                    .shadow(color: ElephantTheme.green.opacity(0.22), radius: 18, y: 8)
            }
        }
    }
}
